char* merge(int numStrings, char** strings) {
    int maxLength = 0;
    char* sb;

    for (int i = 0; i < numStrings; i++) {
        if (strlen(strings[i]) > maxLength) {
            maxLength = strlen(strings[i]);
        }
    }

    sb = (char*)malloc(maxLength+1);

    for (int i = 0; i < maxLength; i++) {
        for (int j = 0; j < numStrings; j++) {
            if (strlen(strings[j]) > i) {
                int index = i;
                sb[index] = strings[j][index];
            }
        }
    }
    sb[maxLength] = '\0';

    return sb;
}

