char *getName(char *value) 
{ 
	char * buffer = calloc(256, sizeof(char)); 
	int offset = -1; 
	int number; 
	if (strlen(value) > 3) 
	   number = (int)strtol(value + (strlen(value) - 3), NULL, 10); 
	else 
	   number = (int)strtol(value, NULL, 10); 
	number %= 100; 
	if (number < 10) 
		offset = (number % 10) - 1; 
	else if (number < 20) 
		offset = (number % 20) - 1; 
	if (offset != -1 && offset < (sizeof(TOKENS) / sizeof(char *))) 
		strcpy (buffer, TOKENS[offset]); 
	return buffer; 
}

