	printf("Sending Ping Request to %s\n", inet_ntoa(addr)); 
	if (hostIsReachable("127.0.0.1", 5000)) { 
		printf("Host is reachable\n"); 
	} 
	else { 
		printf("Host is NOT reachable\n"); 
	} 
	unsigned char google[4] = {173, 194, 32, 38}; 
	memcpy(&addr, google, 4); 
	printf("Sending Ping Request to %s\n", inet_ntoa(addr)); 
	if (hostIsReachable("173.194.32.38", 5000)) { 
		printf("Host is reachable\n"); 
	} 
	else { 
		printf("Host is NOT reachable\n"); 
	} 
	return 0; 
} 

int hostIsReachable(char* ip, int port) 
{ 
	struct sockaddr_in serv_addr; 
	int sockfd = socket(AF_INET, SOCK_STREAM, 0); 
	if (sockfd < 0) 
		return 0; 

	memset(&serv_addr, 0, sizeof(serv_addr)); 
	serv_addr.sin_family = AF_INET; 
	serv_addr.sin_port = htons(port); 

	if (inet_pton(AF_INET, ip, &serv_addr.sin_addr) <= 0) 
		return 0; 
	if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) 
		return 0; 

	return 1; 
}

