char *shuffle(char *text)
{
    if (strlen(text) <= 1)
        return text;
    int split = strlen(text) / 2;

    char *temp1 = shuffle(substring(text, 0, split));
    char *temp2 = shuffle(substring(text, split));
    if (rand() > 0.5)
        return concat(temp1, temp2);
    else
        return concat(temp2, temp1);
}

