#include <stdlib.h>
#include <stdio.h>

int* genRandoms(int total, int numberOfRandoms, int minimumValue) {
  int *ret = malloc(sizeof(int) * numberOfRandoms);
  int totalLeft = total;
  srand(time(NULL)); 
  for (int i = 0; i < numberOfRandoms; i++) {
    int rollsLeft = numberOfRandoms - i;
    int thisMax = totalLeft - (rollsLeft - 1) * minimumValue;
    int thisMin = (minimumValue > totalLeft / rollsLeft) ? 
                   minimumValue : totalLeft / rollsLeft;
    int range = thisMax - thisMin;
    if (range < 0) {
      free(ret);
      fprintf(stderr, "Cannot have %d * %d < %d\n", minimumValue,
              numberOfRandoms, total);
      return NULL;
    }
    int rndValue = range;
    for (int j = 0; j * j < rollsLeft; j++) {
      rndValue = rand() % (rndValue + 1);
    }
    totalLeft -= ret[i] = rndValue + thisMin;
  }

  for (int i = numberOfRandoms - 1; i > 0; i--) {
    int j = rand() % (i + 1);
    int temp = ret[i];
    ret[i] = ret[j];
    ret[j] = temp;
  }

  return ret;
}

