void merge (int a[], int l[], int r[]) {
    int totElem = sizeof(l)/sizeof(l[0]) + sizeof(r)/sizeof(r[0]);
    int i, li, ri;
    i = li = ri = 0;
    while (i < totElem) {
        if ((li < sizeof(l)/sizeof(l[0])) && (ri < sizeof(r)/sizeof(r[0]))) {
            if (l[li] < r[ri]) {
                a[i] = l[li];
                i ++;
                li ++;
            } else {
                a[i] = r[ri];
                i ++;
                ri ++;
            }
        } else {
            if (li >= sizeof(l)/sizeof(l[0])) {
                while (ri < sizeof(r)/sizeof(r[0])) {
                    a[i] = r[ri];
                    i ++;
                    ri ++;
                }
            }
            if (ri >= sizeof(r)/sizeof(r[0])) {
                while (li < sizeof(l)/sizeof(l[0])) {
                    a[i] = l[li];
                    li ++;
                    i ++;
                }
            }
        }
    }
}

