int isNumber(char* str) {
  int i = 0;
  int len = strlen(str);
  int a = 0, b = 0, c = 0, d = 0;
  if (i < len && (str[i] == '+' || str[i] == '-')) { 
    i++;
  }
  while (i < len && isDigit(str[i])) {
    i++;
    a = 1;
  }
  if (i < len && str[i] == '.') {
    i++;
  }
  while (i < len && isDigit(str[i])) {
    i++;
    b = 1;
  }
  if (i < len && (str[i] == 'e' || str[i] == 'E') && (a == 1 || b == 1)) {
    i++;
    c = 1;
  }
  if (i < len && (str[i] == '+' || str[i] == '-') && (c == 1)) {
    i++;
  }
  while (i < len && isDigit(str[i])) {
    i++;
    d = 1;
  }
  return (i == len && (a == 1 || b == 1) && (!(c == 1) || (c == 1 && d == 1)));
}

