// A utility function to swap two elements
void swap(char* a, char* b) {
    char t = *a;
    *a = *b;
    *b = t;
}

int partition (char arr[], int low, int high)
{
    int pivot = arr[high];    // pivot
    int i = (low - 1);  // Index of smaller element

    for (int j = low; j <= high- 1; j++)
    {
        // If current element is smaller than or
        // equal to pivot
        if (arr[j] <= pivot)
        {
            i++;    // increment index of smaller element
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

/* The main function that implements QuickSort
 arr[] --> Array to be sorted,
  low  --> Starting index,
  high  --> Ending index */
void quickSort(char arr[], int low, int high)
{
    if (low < high)
    {
        /* pi is partitioning index, arr[p] is now
           at right place */
        int pi = partition(arr, low, high);

        // Separately sort elements before
        // partition and after partition
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

// Function to implement Dividing groups of elements 
void divideArray(char* arr, int n)
{
    // Sorting group elements
    quickSort(arr, 0, n-1);

    // Initializing count for current group
    int count = 0; 

    // Take a temporary array to store elements
    // of current group
    char temp[10]; 

    // Iterate through all elements
    for (int i=0; i<n; i++) {

        // If current element is same
        // as its previous element or
        // it is first element
        if (i == 0 || arr[i] == arr[i-1]) {

            // Store it in temporary array
            temp[count] = arr[i];
            count++;
        }

        // If current element different
        // than previous or it is last
        // element
        else {

            // Print the current group
            for (int j=0; j<count; j++)
                printf("%c ", temp[j]);
            printf("\n");

            // Reset the count
            count = 0;

            // Store current element in
            // temporary array
            temp[count] = arr[i];
            count++;
        }
    }

    // Print the last group
    for (int j=0; j<count; j++) 
        printf("%c ", temp[j]);
    printf("\n");
}

