	{
		set[i] = 0;		 
	}	

    int sum1 = 0;
    int sum2 = 0;
	for (int i = 0; i <= X; i ++) 
	{ 
		sum1 += i; 
	} 

	for (int i = 0; i < X; i++) 
	{ 
		if (set[A[i]]) 
