int solution (int X, int A[], int len) {
    if (X > len) {
        return -1;
    }

    int isFilled[X];
    int jumped = 0;
    memset(isFilled, 0, sizeof(isFilled));

    for (int i = 0; i < len; i++) {
        int x = A[i];
        if (x <= X) {
            if (isFilled[x-1] == 0) {
                isFilled[x-1] = 1;
                jumped += 1;
                if (jumped == X) {
                    return i;
                }
            }
        }
    }
    return -1;
}

