struct ListNode *reverse(struct ListNode *toBeNextNode, struct ListNode *currentNode) 
{
    struct ListNode *currentHead = currentNode;

    if ((currentNode == NULL || currentNode->next == NULL) && toBeNextNode == NULL) 
        return currentHead;

    if (currentNode->next != NULL) 
        currentHead = reverse(currentNode, currentNode->next);

    currentNode->next = toBeNextNode;
    return currentHead;
}

