void sort(int* input, int size){ 
  for(int i= 0; i < size-1; i++){ 
    int k = i+1; 
    int nxtVal = input[k]; 
    while(input[k-1] > nxtVal && k> 0){ 
      input[k] = input[k-1]; 
      k--; 
    } 
    input[k] = nxtVal; 
  } 
  printf("Medium sorting is done and the result is: \n"); 
  for (int i = 0; i < size; i++) { 
    printf("%d, ", input[i]); 
  } 
}

