int solution(int N) {
    char binary[33];
    int largestGap = 0;
    int gap = 0;
    itoa(N, binary, 2);
    for(int i = 1; i < strlen(binary); i++) {
        if(binary[i] == '0') {
            gap++;
        } else {
            if(gap > largestGap) {
                largestGap = gap;
            }
            gap = 0;
        }
    }

    return largestGap;
}

