int * solution (char *S, int *P, int *Q, int N) { 
   int *answer = (int *) malloc (sizeof (int) * N); 
   int A, C, G, T; 
   for (int i = 0; i < N; i++) { 
      A = 0; 
      C = 0; 
      G = 0; 
      T = 0; 
      for (int j = P[i]; j <= Q[i]; j++) { 
         switch (S[j]) { 
            case 'A': 
               A++; 
               break; 
            case 'C': 
               C++; 
               break; 
            case 'G': 
               G++; 
               break; 
            case 'T': 
               T++; 
               break; 
         } 
      } 
      if (A > 0) 
         answer[i] = 1; 
      else if (C > 0) 
         answer[i] = 2; 
      else if (G > 0) 
         answer[i] = 3; 
      else if (T > 0) 
         answer[i] = 4; 
   } 
   return answer; 
}

