char* getLongestSubstring(char* s) {
  if (strlen(s) == 0) return NULL;
  char currentChar = s[0];
  char longestString[strlen(s)]; 
  strncpy(longestString, &currentChar, 1); 
  char runningString[strlen(s)];
  strncpy(runningString, &currentChar, 1); 
  int currentLongestLength = 1;

  for (int i = 1; i < strlen(s); i++) {
    if (s[i] == currentChar) {
      strncat(runningString, &currentChar, 1); 
      if (strlen(runningString) > strlen(longestString)) {
        currentLongestLength++;
        strcpy(longestString, runningString);
      }
    } 
    else {
      strncpy(runningString, &s[i], 1); 
    }
  }

  return longestString;
}

