int main()
{
	int loops = 1000000;
	long regularCalls, reflectiveCalls, reflectiveLookup;
	clock_t start;
	start = clock();
	void *object;
	void *s;
	for(int i=0; i<loops; i++){
		s = object->getClass;
	}
	regularCalls = clock() - start;

	start = clock();
	Reflect_Class *method;
	method->setAccessible(True);
	for(int i=0; i<loops; i++){
		s = method->invoke(object);
	}
	reflectiveCalls = clock() - start;

	start = clock();
	Reflect_Class *method_;
	for(int i=0; i<loops; i++){
		for(int j=0; j<method_->length; j++){
			s = method_[j]->invoke(object);
		}
	}
	reflectiveLookup = clock() - start;

	printf("Average regular method calls: %d ns.\n", regularCalls/loops);
	printf("Average reflective method calls without lookup: %d ns.\n", reflectiveCalls/loops);
	printf("Average reflective method calls with lookup: %d ns.\n", reflectiveLookup/loops);

	return 0;
}

