void pack(const char* sourceDirPath, const char* zipFilePath){
    FILE *zs = fopen(zipFilePath, "w");
    struct dir *dp;
	struct dirent *dptr;
	char m[256]; 
	char filesname[256]; 
	sprintf(m, "%s/*", sourceDirPath);
	dp = opendir(m); 
	while((dptr = readdir(dp)) != NULL) {
		if (dptr->d_type == DT_REG) {
			strcpy(filesname, dptr->d_name); 
			struct stat st; 
			stat(filesname, &st);
			int file_size = st.st_size; 
			struct zipAdd f; 
			f.filename = filesname; 
			f.file_size = file_size; 
			f.file_to_zip = fopen(filesname, "rb");
			zip_addToZip(zs, f);
			fclose(f.file_to_zip);
		}
	}
	closedir(dp); 
	fclose(zs); 
}

