  if (privateKey instanceof ECPrivate <Key>) {
    ECPrivateKey *pk = (ECPrivateKey *)privateKey;
    ECParameterSpec *params = pk->getParams();
    return deriveCurveName(EC5Util.convertSpec(params, false));
  }
  else if (privateKey instanceof org.bouncycastle.jce.interfaces.ECPrivateKey) {
    org.bouncycastle.jce.interfaces.ECPrivateKey *pk = (org.bouncycastle.jce.interfaces.ECPrivateKey *)privateKey;
    return deriveCurveName(pk->getParameters());
  }
  else {
    return "Can only be used with instances of ECPrivateKey (either jce or bc implementation)";
  } 
}

