bool hasLoop(Node *root) {
    if (root == NULL) return false;
    Node *slow = root, *fast = root;
    int taken = 0, limit = 2;
    while (fast->next != NULL) {
        fast = fast->next;
        taken ++;
        if (slow == fast) return true;
        if (taken == limit) {
            taken = 0;
            limit <<= 1;
            slow = fast;
        }
    }
    return false;
}

