char* removeDuplicates(char* s)
{
	char* no_dupes = malloc(strlen(s)+1);
	int no_dupes_index =0;

	for (int i=0; i<strlen(s); i++)
	{
		int j;

		for (j=0; j<no_dupes_index; j++)
		{
			if (s[i] == no_dupes[j]) { break; }
		}
		if (j == no_dupes_index)
		{
			no_dupes[no_dupes_index] = s[i];
			no_dupes_index++;
		}
	}

	no_dupes[no_dupes_index] = '\0'; 

	return no_dupes;
}

void shuffle(void *a, int n)
{
    for (int i = 0; i < n; i++)
    {
        int r = i + (rand() % (n - i));
        void* swap = ((char*)a) + i * sizeof(*a);
        *((char*)a + r * sizeof(*a)) = *(char*)swap;
        *(char*)swap = *((char*)a + r * sizeof(*a));
    }
}

