char* getDurationBreakdown(long millis){ 
    if (millis < 0) { 
        perror("Duration must be greater than zero!"); 
        exit(1); 
    } 

    long days = millis / (1000 * 24 *60 *60); 
    millis -= days * (1000*24*60*60); 
    long hours = millis / (1000*60*60); 
    millis -= hours * (1000*60*60); 
    long minutes = millis / (1000*60); 
    millis -= minutes * (1000*60); 
    long seconds = millis / (1000); 

    char* output = malloc(sizeof(char)*64); 
    sprintf(output, "%ld Days %ld Hours %ld Minutes %ld Seconds", days, hours, minutes, seconds);
    return output; 
}

