char* shuffle(char* text) 
{ 
	int n = strlen(text); 

	// creating a temp array 
	char* temp = (char*)malloc((n + 1)*(sizeof(char))); 
	strcpy(temp, text); 

	// shuffle temp's characters 
	for (int i=0; i < n; i++) 
	{ 
		int r = rand() % n; 

		// swap elements of temp array 
		char t = temp[i]; 
		temp[i] = temp[r]; 
		temp[r] = t; 
	} 
	return temp; 
}

