//function for checking if the parentheses are balanced
bool isBalanced(const char * str) 
{
    int len = strlen(str);
    bool result = false;

    if(len < 2) 
        return false;

    char mapRight[256];
    char mapLeft[256];
    mapRight['}'] = '{';
    mapRight[')'] = '(';
    mapRight[']'] = '[';

    mapLeft['{'] = '}';
    mapLeft['('] = ')';
    mapLeft['['] = ']';

    //stack used to store the characters of expression
    char * stack = (char*)malloc(len * sizeof(char));
    int top = -1;

    int i;
    for(i = 0; i < len; i++)
    {
        char ch = str[i];

        //if current char is not a parentheses, then ignore it
        if(!mapRight[ch] && !mapLeft[ch])
            continue;

        //if current character is an opening parentheses, it means we’re 
        //pushing it onto stack
        if(mapLeft[ch])
            stack[++top] = ch;

        else
        {
            //for closing parenthesis, get the most recently pushed char
            char topElement = (top == -1)? '#' : stack[top--];
            if(topElement != mapRight[ch])
                return false;
            else 
                result = true;
        }
    }
    free(stack);

    if (top != -1)
        return false;

    return result;
}

