bool isExpectedPassword(char *password, char *salt, char* hash) {
    if(password ==  NULL || salt == NULL || hash == NULL)
    {
        printf("password, salt and hash must not be null\n");
        return false;
    }

    try {
        char *passwordBytes = (char *)malloc((strlen(password)+1)*sizeof(char));
        int l = strlen(password);
        memcpy(passwordBytes, password, l);
        int len = l + strlen(salt);
        char *all = (char*)malloc((len+1)*sizeof(char));
        memcpy(all, passwordBytes, l);
        memcpy(all+l, salt, strlen(salt));

        SHA3_DigestSHA3 md = new SHA3.Digest512();
        md.update (all);
        char *digest = md.digest();
        bool result = memcmp(digest, hash, strlen(digest)) == 0;

        free(passwordBytes);
        free(all);
        return result;
    } catch (UnsupportedEncodingException e) {
        printf("Caught UnsupportedEncodingException e: %s", e.message);
    }
    return false;
}

boolean isAnagram( char *first, char *second) {
    char positive[BUFFER_SIZE];
    strcpy(positive, first);
    toLower(positive);

    char negative[BUFFER_SIZE];
    strcpy(negative, second);
    toLower(negative);

    if(strlen(positive) != strlen(negative)) {
        return false;
    }

    int counts[26] = {0};
    int diff = 0;

    for(int i=0; i < strlen(positive); i++) {
        int pos = (int)positive[i] - 97;
        if(counts[pos] >= 0) {
            diff ++;
        }
        else {
            diff --;
        }
        counts[pos]++;

        int neg = (int) negative[i] - 97;
        if(counts[neg] <= 0) {
            diff ++;
        } else {
            diff --;
        }
        counts[neg]--;
    }
    return diff == 0;
}

