void removeDuplicates(char *str) {
  int count[256] = {0};    
  int ip_ind = 0, res_ind = 0;  
  while (*(str + ip_ind)) 
  {
    char temp = *(str + ip_ind);
    if (count[temp] == 0) 
    {
      count[temp] = 1;
      *(str + res_ind) = *(str + ip_ind);
      res_ind++;
    }
    ip_ind++;
  }   
  *(str + res_ind) = '\0';
}

