    if (read == -1) {
        return -1;
    }

    int pos = off - 1;
    for (int readPos = off; readPos < off + read; readPos++) {
        if (cbuf[readPos] == '@') {
            continue;
        } else {
            pos++;
        }

        if (pos < readPos) {
            cbuf[pos] = cbuf[readPos];
        }
    }
    return pos - off + 1;
}

