    for (int i = 0; i < arr.size; i++) {
        if (arr.elements[i] == obj) {
            return "..."; 
        }
    }

    arr.elements[arr.size++] = obj;

    char* className = (*(void**)obj == NULL) ? "String" : (*(void***)obj)[0];

    if (strcmp(className, "String") == 0) {
        return (char*)obj;
    } 

    if (strcmp(className + strlen(className) - 2, "[]") == 0) {
        char* componentType = className;
        int length = *(int*)(obj + 8);
        long offset = 16;

        char* result = malloc(100);
        strcat(result, componentType);
        strcat(result, "[]{");
        for (int i = 0; i < length; i++) {
            if (i > 0) {
                strcat(result, ",");
            }

            if (strcmp(componentType, "char") == 0) {
                char* val = obj + offset;
                strcat(result, *val);
                offset++;
            } else {
                char* val = *(void**)(obj + offset);
                strcat(result, *toString(val, arr));
                offset += 8;
            }
        }

        strcat(result, "}");

        return result;
    }

    char* result = malloc(100);
    strcat(result, className);

    void* superClass = (*(void***)(obj + 8))[1];
    bool isNotFirstLevel = false;
    while (superClass != NULL) {
        className = (*(void***)(superClass + 8))[0];
        long offset = 16;
        void** fieldNames = *(void***)(superClass + 16);
        size_t fieldNamesSize = *(size_t*)(superClass + 24);
        void** fieldTypes = *(void***)(superClass + 32);
        size_t fieldTypesSize = *(size_t*)(superClass + 40);
        void** fieldValues = *(void***)(obj + 16);
        size_t fieldValuesSize = *(size_t*)(obj + 24);

        if (!isNotFirstLevel) {
            isNotFirstLevel = true;
        } else {
            strcat(result, "[");
        }

        for (int i = 0; i < fieldNamesSize; i++) {
            if (i > 0) {
                strcat(result, ",");
            }

            char* fieldType = *(char**)(fieldTypes + i);
            char* fieldName = *(char**)(fieldNames + i);
            void* fieldValue = *(void**)(fieldValues + i);
            strcat(result, fieldName);
            strcat(result, "=");

            if (strcmp(fieldType, "char") == 0) {
                char* value = fieldValue;
                strcat(result, value);
            } else {
                char* value = *toString(fieldValue, arr);
                strcat(result, value);
            }

            offset += 8;
        }

        strcat(result, "]");

        superClass = (*(void***)(superClass + 8))[1];
    }

    return result;
}

