int* solution(char *S, int *P, int *Q, int N, int M) {
    int *result = (int *) malloc(M * sizeof(int));
    int lastOccurrencesMap[3][N];

    int lastA=-1;
    int lastC=-1;
    int lastG=-1;

    for (int i=0; i<N; i++) {
        char c = S[i];
        if (c == 'A') {
            lastA = i;
        } else if (c == 'C') {
            lastC = i;
        } else if (c == 'G') {
            lastG = i;
        }
        lastOccurrencesMap[0][i] = lastA;
        lastOccurrencesMap[1][i] = lastC;
        lastOccurrencesMap[2][i] = lastG;
    }
    for (int i=0; i<M; i++) {
        int startIndex = P[i];
        int endIndex = Q[i];
        int minimum = 4;
        for (int n=0; n<3; n++) {
            int lastOccurrence = getLastNucleotideOccurrence(startIndex, endIndex, n, lastOccurrencesMap);
            if (lastOccurrence != 0) {
                minimum = n+1;
                break;
            }
        }
        result[i] = minimum;
    }

    return result;
}

int getLastNucleotideOccurrence(int startIndex, int endIndex, int n, int lastOccurrencesMap[3][N]) {
    if (startIndex == 0)
        return lastOccurrencesMap[n][endIndex];
    else
        return lastOccurrencesMap[n][endIndex] - lastOccurrencesMap[n][startIndex - 1];
}

