bool isBalanced (char * str]
{
    bool result = false;
    int len = strlen(str);
    if (len < 2) return false;

    // Create a stack of character
    char * stack = malloc(sizeof(char) * len); 
    int stack_size = 0;

    for (int i = 0; i < len; i++)
    {
        char ch = str[i];
        if (! parenthesesMapRight.contains(ch) && 
            ! parenthesesMapLeft.contains(ch))
        {
            continue;
        }
        if (parenthesesMapLeft.contains(ch))
        {
            stack[stack_size] = ch;
            stack_size++;
        }
        else
        {
            if (stack_size == 0)
                return false;
            if (stack[stack_size-1] == 
                parenthesesMapRight.get(ch).charValue())
            {
                result = true;
            }
            else 
            {
                return false;
            }
            stack_size--;
        }
    }
    if (stack_size != 0) return result = false;
    free(stack);
    return result;
}

