void transform(HSSFRow rowOld, XSSFRow rowNew){
	XSSFCell cellNew;
	rowNew->setHeight(rowOld->getHeight());
	if (rowOld->getRowStyle() != NULL){
		int hash = rowOld->getRowStyle()->hashCode();
		if (!styleMap->containsKey(hash))
			transform(hash, rowOld->getRowStyle(), workbookNew->createCellStyle());
		rowNew->setRowStyle(styleMap->get(hash));
	}
	for (Cell* cell = rowOld->getFirstCell(); cell != NULL; cell = cell->getNextCell()) {
		cellNew = rowNew->createCell(cell->getColumnIndex(), cell->getCellType());
		if (cellNew != NULL)
			transform(cell, cellNew);
	}
	lastColumn = max(lastColumn, rowOld->getLastCellNum());
}

