void checkPythagTriplet(int limit)
{
    int a;
    for (a = 1; a <= limit / 3; a++) {
        int b;
        for (b = a + 1; b <= limit / 2; b++) {
            int c = limit - a - b;
            if (a * a + b * b == c * c)
                printf ("a=%d, b=%d, c=%d\n", a, b, c);
        }
    }
    }
