    int n = sizeof(A)/sizeof(A[0]); 
    int values[X+1] = {0}; 
    int count = 0; 

    for (int i=0; i<n; i++){ 
        if(values[A[i]] == 0) { 
            values[A[i]]++; 
            count++; 
            if(count == X) 
                return i; 
        } 
    } 
    return -1;
}

