char* toHexString(uint8_t bytes[], int byte_length) {
  if (bytes == NULL) {
    return NULL;
  }

  char *hex_string = (char*)malloc(byte_length * 2 * sizeof(char));
  for (int i = 0; i < byte_length; i++) {
     uint8_t high = (bytes[i] & 0xf0) >> 4;
     uint8_t low = bytes[i] & 0x0f; 
     *(hex_string + (2 * i)) = nibble2char(high);
     *(hex_string + (2 * i + 1)) = nibble2char(low);
  }

  return hex_string;
}

