const char *getName(char *value)
{
    bool negative = false;
    if (value[0] == '-')
    {
        negative = true;
        value++;
    }

    int decimals = 0;
    char *decimalValue = NULL;
    decimals = strchr(value, '.');
    if (decimals)
    {
        decimalValue = strdup(value + decimals + 1);
        value[decimals] = 0;
    }

    const char *name = processor.getName(value);
    if (!name[0])
    {
        name = ZERO_TOKEN;
    }
    else if (negative)
    {
        name = strcat(MINUS, SEPARATOR, name);
    }

    if (decimalValue)
    {
        strcat(name, SEPARATOR, UNION_AND, SEPARATOR, 
               processor.getName(decimalValue), 
               SEPARATOR, 
               SCALE.getName(-strlen(decimalValue)));
    }

    return name;
}

