char *join(char **arr, char *delim)
{
    if (!*arr) 
        return NULL;

    int arrc = 0;
    while(arr[arrc] != NULL)
        arrc++;

    int deliml = strlen(delim);
    int arrsz = 0;
    for(int i=0; i<arrc; i++){
        arrsz += strlen(arr[i]);
        arrsz += deliml;
    }

    char *res = malloc(sizeof(char) * arrsz - deliml + 1);
    size_t index = 0;
    for(int i=0; i<arrc; i++){
        index += sprintf(&res[index], "%s%s", arr[i], delim);
    }

    res[arrsz - deliml] = 0;
    return res;
}

