        return "";
    }

    int first = s[0];
    if(isupper(first)) {
        return s;
    } else {
        int new_len = strlen(s);
        char *result = malloc(new_len + 1);
        *result = toupper(first);
        strcpy(result + 1, s + 1);
        return result;
    }
}

