void printTable(char countries[][], int populations[], int countriesLen) 
{ 
    if(countriesLen > 0) 
    { 
        int longestNameInput = strlen(countries[0]); 
        int longestPopInput = digitCount(populations[0]); 
        for (int i=0; i<countriesLen; i++) 
        { 
            int countLength = strlen(countries[i]); 
            int popLength = digitCount(populations[i]); 
            if (countLength > longestNameInput) 
                longestNameInput = countLength; 
            if (popLength > longestPopInput) 
                longestPopInput = popLength; 
        } 
        for (int i=0; i<countriesLen; i++) 
        { 
            printf("%s", countries[i]); 
            for (int j=0; j<(longestNameInput - strlen(countries[i])); j++) 
                printf(" "); 
            printf(" | "); 
            for (int k=0; k<(longestPopInput - digitCount(populations[i])); k++) 
                printf(" "); 
            printf("%d\n", populations[i]); 
        } 
    } 
}

