            return (int)(((Primitive*)a)->id - ((Primitive*)b)->id);
        }
        void sort_primitive(Primitive* data, unsigned int length, size_t size, int (*cmp)(const void*, const void*)) {
            qsort(data, length, size, cmp);
        }
