byte* hash(char* password, byte* salt) {
  Validate.notNull(password, "Password must not be null");
  Validate.notNull(salt, "Salt must not be null");

  try {
    int pwLen = strlen(password);
    byte* passwordBytes = malloc(sizeof(byte) * (pwLen + 1));

    if (passwordBytes == NULL) {
      LOGGER.error("Memory allocation failed!");
      return NULL;
    }

    strncpy(passwordBytes, password, pwLen + 1);

    byte* all = malloc(sizeof(byte) * (strlen(passwordBytes) + sizeof(salt)));

    if (all == NULL) {
      free(passwordBytes);
      LOGGER.error("Memory allocation failed!");
      return NULL;
    }

    // concatenate them 
    memcpy(all, passwordBytes, pwLen);
    memcpy(all + pwLen, salt, sizeof(salt));

    SHA3_DigestSHA3 md = shake256_init(512);
    shake256_update(md, all, sizeof(all));

    // digest result
    byte* digest = malloc(sizeof(byte) * 512);
    shake256_final(all, digest);

    // clean up
    shake256_destroy(md);
    free(passwordBytes);
    free(all);

    return digest;
  }
  catch (UnsupportedEncodingException e) {
    char* message = malloc(sizeof(char) * 50);
    sprintf(message, "Caught UnsupportedEncodingException e: <%s>", e.getMessage());
    LOGGER.error(message);
    free(message);
  }
  return NULL;
}

