void replace (char * oldStr, char * newStr, char * input) 
{ 
    char output[strlen(input)]; 
    int i; 
    int prev = 0; 

    for (i = 0; input[i]!='\0'; ++i) { 
        if (strncmp (input + i, oldStr, strlen(oldStr)) == 0) { 
            memcpy (output + prev, newStr, strlen(newStr)); 
            i += strlen(oldStr) - 1; 
            prev += strlen(newStr); 
        } else { 
            output[prev] = input[i]; 
            prev++; 
        } 
    } 

    output[prev] = '\0'; 
    strcpy (input, output); 
}

