char* getDurationBreakdown(long millis) {
    char* units[4] = {"Days", "Hours", "Minutes", "Seconds"};
    int values[4] = {0};

    if (millis < 0) {
        char* exceptionString = "Duration must be greater than zero!";
        return exceptionString;
    }

    values[0] = millis / (1000 * 60 * 60 * 24);
    millis -= values[0] * (1000 * 60 * 60 * 24);
    values[1] = millis / (1000 * 60 * 60);
    millis -= values[1] * (1000 * 60 * 60);
    values[2] = millis / (1000 * 60);
    millis -= values[2] * (1000 * 60);
    values[3] = millis / 1000;

    char* output = NULL;
    int outputLength = 0;
    int startPrinting = 0;
    for (int i = 0; i < 4; i++) {
        if (startPrinting == 0 && values[i] != 0) {
            startPrinting = 1;
        }
        if (startPrinting) {
            outputLength += snprintf(NULL, 0, "%d%s ", values[i], units[i]);
        }
    }

    output = (char*)calloc(outputLength + 1, sizeof(char));
    outputLength = 0;
    startPrinting = 0;
    for (int i = 0; i < 4; i++) {
        if (startPrinting == 0 && values[i] != 0) {
            startPrinting = 1;
        }
        if (startPrinting) {
            outputLength += snprintf(output + outputLength, outputLength, "%d%s ", values[i], units[i]);
        }
    }

    return output;
}

