        if (length > 0) { 
            char x = ch[0]; 
            int count = 1; 
            for (int i = 1; i < length; i++) { 
                if (ch[i] == x) { 
                    count++; 
                } else { 
                    printf("Number of Occurrence of '%c' is: %d\n", 
                            ch[i - 1], count); 
                    x = ch[i]; 
                    count = 1; 
                } 
            } 
