char findFirstCharacter(char *s) 
{ 
    int seen[256] = {0}, unique[256] = {0}; 
    int i; 
    char result = '_'; 
    for (i=0; s[i]!='\0'; i++) 
    { 
        if (seen[s[i]] == 0) 
        { 
            seen[s[i]] = 1; 
            unique[s[i]] = 1; 
        } 

        else
        { 
            unique[s[i]] = 0; 
        } 
    } 

    for (i=0; i<256; i++) 
    { 
        if (unique[i] == 1) 
        { 
            result = (char)i; 
            break; 
        } 
    } 

    return result; 
}

