char* getName(char* value) {
    bool negative = false;
    int len = strlen(value);
    if (value[0] == '-') {
        negative = true;
        for (int i = 0; i < len; i++) {
            value[i] = value[i+1];
        }
        value[len-1] = 0; // null terminate
    } 
    int decimals = -1;
    for (int i = 0; i < len; i++) {
        if (value[i] == '.') {
            decimals = i;
            break;
        }
    }
    char* decimalValue = NULL;
    int decimalLen;
    if (decimals >= 0) {
        decimalLen = strlen(value) - decimals - 1; 
        decimalValue = malloc(decimalLen);
        strncpy(decimalValue, value + decimals + 1, decimalLen);
        value[decimals] = 0; // null terminate
    }
    char* name = processor.getName(value);
    if (!strcmp(name, "")) {
        sprintf(name, ZERO_TOKEN);
    } else if (negative) {
        sprintf(name, "%s%s%s", MINUS, SEPARATOR, name);
    }
    if (decimalValue && strcmp(decimalValue, "")) {
        char* zeroDecimalValue = malloc(decimalLen);
        for (int i = 0; i < decimalLen; i++) {
            zeroDecimalValue[i] = '0';
        }
        if (!strcmp(decimalValue, zeroDecimalValue)) {
            sprintf(name, "%s%s%s%s%s%s%s", name, SEPARATOR, UNION_AND, 
                    SEPARATOR, "zero", SEPARATOR, SCALE.getName(-decimalLen));
        } else {
            sprintf(name, "%s%s%s%s%s%s", name, SEPARATOR, UNION_AND, 
                    SEPARATOR, processor.getName(decimalValue), 
                    SEPARATOR, SCALE.getName(-decimalLen));
        }
        free(zeroDecimalValue);
    }
    free(decimalValue);
    return name;
}

void copyFolder(const char* src, const char* dest) {
    DIR* p_src = opendir(src);
    if (p_src == NULL) {
        fprintf(stderr, "Error: Couldn't open directory: %s\n", src);
        return;
    }
    int len = strlen(src)+1;
    int dest_len = strlen(dest)+1;
    char* path = (char*)malloc(len);
    char* dest_path = (char*)malloc(dest_len);
    strcpy(path, src);
    strcpy(dest_path, dest);
    struct dirent* p;
    while ((p = readdir(p_src)) != NULL) {
        int num = strlen(path);
        int dest_num = strlen(dest_path);
        path[len-1] = '/';
        path[len] = '\0';
        dest_path[dest_len-1] = '/';
        dest_path[dest_len] = '\0';
        strcat(path, p->d_name);
        strcat(dest_path, p->d_name);
        if (p->d_type == DT_DIR) {
            if (mkdir(dest_path, 0777) == -1) {
                fprintf(stderr, "Error: Couldn't create directory: %s\n", dest_path);
            }
        }
        else {
            copy(path, dest_path);
        }
        path[len-1] = '\0';
        dest_path[dest_len-1] = '\0';
    }
    closedir(p_src);
    free(path);
    free(dest_path);
}

int hasLoop(Node *root) {
    if (root == NULL) return 0;
    Node *slow = root, *fast = root;
    int taken = 0, limit = 2;
    while (fast->next != NULL) {
        fast = fast->next;
        taken ++;
        if (slow == fast) return 1;
        if (taken == limit) {
            taken = 0;
            limit <<= 1;
            slow = fast;
        }
    }
    return 0;
}

