int solution(int X, int A[], int N) {
  if (X > N) {
    return -1;
  }
  int isFilled[X], jumped = 0;
  for (int i = 0; i < X; i++) {
    isFilled[i] = 0;
  }
  for (int i = 0; i < N; i++) {
    int x = A[i];
    if (x <= X) {
      if (isFilled[x - 1] == 0) {
        isFilled[x - 1] = 1;
        jumped += 1;
        if (jumped == X) {
          return i;
        }
      }
    }
  }
  return -1;
}

