int binary_search(int int_to_search, int sorted_array[], int size) {
  int lower = 0;
  int upper = size -1;
  while (lower <= upper) {
    int mid = lower + (upper - lower) / 2;
    if (int_to_search < sorted_array[mid]) {
      upper = mid - 1;
    } else if (int_to_search > sorted_array[mid]) {
      lower = mid + 1;
    }
    else
      return mid;
  }
  return -1;
}

