    int i;
    for (i = 0; i < strlen(value) - 1; i++) {
        value[i] = value[i+1];
    }
    value[i] = '\0';
  }
  int decimals = -1; 
  char* decimalValue = NULL;
  int i;
  for (i = 0; i < strlen(value); i++) {
        if (value[i] == '.') {
            decimals = i;
        }
    }
  if (decimals != -1) {
    decimalValue = malloc(strlen(value)); 
    for (i = 0; i < strlen(value) - decimals; i++) {
        value[decimals + i] = value[decimals + 1 + i];
    }
    value[i] = '\0';
    strcpy(decimalValue, value + decimals + 1);
  }
  char* name = processor_getName(value);
  if (strcmp(name, "") == 0) {
    name = ZERO_TOKEN;
  } else if (negative) {
    char* newName = malloc(strlen(MINUS) + strlen(SEPARATOR) + strlen(name));
    strcpy(newName, MINUS);
    strcat(newName, SEPARATOR);
    strcat(newName, name);
    name = newName;    
  }
  if (decimalValue != NULL && strlen(decimalValue) > 0) {
    char zeroDecimalValue[strlen(decimalValue) + 1];
    for (i = 0; i < strlen(decimalValue); i++) {
      zeroDecimalValue[i] = '0';
    }
    zeroDecimalValue[i] = '\0';
    if (strcmp(decimalValue, zeroDecimalValue) == 0) {
      char* newName = malloc(strlen(name) + strlen(SEPARATOR) + strlen(UNION_AND) + strlen(SEPARATOR) + 5 + strlen(SEPARATOR) + strlen(SCALE_getName(-strlen(decimalValue))));
      strcpy(newName, name);
      strcat(newName, SEPARATOR);
      strcat(newName, UNION_AND);
      strcat(newName, SEPARATOR);
      strcat(newName, "zero");
      strcat(newName, SEPARATOR);
      strcat(newName, SCALE_getName(-strlen(decimalValue)));
      name = newName;      
    } else {
      char* newName = malloc(strlen(name) + strlen(SEPARATOR) + strlen(UNION_AND) + strlen(SEPARATOR) + strlen(processor_getName(decimalValue)) + strlen(SEPARATOR) + strlen(SCALE_getName(-strlen(decimalValue))));
      strcpy(newName, name);
      strcat(newName, SEPARATOR);
      strcat(newName, UNION_AND);
      strcat(newName, SEPARATOR);
      strcat(newName, processor_getName(decimalValue));
      strcat(newName, SEPARATOR);
      strcat(newName, SCALE_getName(-strlen(decimalValue)));
      name = newName;      
    }
  }  
  return name;
}

