char* filter(char* source, int start, int end, char* dest, int dstart, int dend) {
    char* out = super_filter(source, start, end, dest, dstart, dend);
    if (out != NULL) {
        source = out;
        start = 0;
        end = strlen(out);
    }
    int len = end - start;
    if (len == 0) {
        return source;
    }
    int dlen = strlen(dest);
    int i;
    for (i = 0; i < dstart; i ++) {
        if (dest && dest[i] == '.') {
            return (dlen - (i + 1) + len > digits) ? "" : strdup(source + start);
        }
    }
    for (i = start; i < end; ++ i) {
        if (source[i] == '.') {
            if ((dlen - dend) + (end - (i + 1)) > digits) return "";
            else break;
        }
    }
    return strdup(source + start);
}

