char * toHexString(unsigned char * bytes, int len) {
    int i; 
    int j; 
    size_t hexStringLen = 3 * len - 1;
    char *hexString = (char *)malloc(hexStringLen);
    char *p = hexString;

    for (i = 0 ; i < len ; i++) {
        j = bytes[i] & 0xff; 
        sprintf(p, "%02x", j); 
        p += 2; 
        if (i < len - 1) {
            *p = ' '; 
            p++;
        }
    } 
    return hexString;
}

