char* removeAdjacentDuplicates(char* input) {
    size_t length = strlen(input);
    if (length <= 1) {
        return input;
    }
    char* result = calloc(length + 1, sizeof(char));
    result[0] = input[0];
    size_t j = 1;
    for (size_t i = 1; i < length; i++) {
        if (input[i] != input[i - 1]) {
            result[j] = input[i];
            j++;
        }
    }
    return result;
}

