void onRequestPermissionsResult (int requestCode,char *permissions[], int grantResults[]){
    int index = (requestCode >> 16) & 0xffff;
    if (index != 0){
        index --;
        char *who = mPendingFragmentActivityResults.get (index);
        mPendingFragmentActivityResults.remove (index);
        if (who == NULL){
            printf ("Activity result delivered for unknown Fragment.");
            return;
        }
        Fragment frag = mFragments.findFragmentByWho (who);
        if (frag == NULL){
            printf ("Activity result no fragment exists for who: %s", who);
        }
        else {
            frag.onRequestPermissionsResult (requestCode & 0xffff, permissions, grantResults);
        }
    }
}

