bool isBalanced(char *strExpression) 
{ 
    //Hashmap to store mapping 
    char bracketPair[128]; 

    //Fill hashmap 
    bracketPair['('] = ')'; 
    bracketPair['['] = ']'; 
    bracketPair['{'] = '}'; 

    // Stores the characters in the Stack 
    char stack[128]; 

    // Initial position of top 
    int top = -1; 

    // Iterate over the characters in the input string 
    for (int i = 0; i < strlen(strExpression); i++) 
    { 
        // Working on Left Bracket 
        if (bracketPair[strExpression[i]] == '\0') 
        { 
            top++; 
            stack[top] = strExpression[i]; 
        } 

        // Working on Right Bracket 
        else if (top >= 0 && 
                 bracketPair[stack[top]] == strExpression[i]) 
            top--; 

        // If it is not a Right Bracket or 
        // No left bracket is present 
        else 
            return false; 
    } 

    if (top == -1) 
        return true; 

    // Not Balanced 
    return false; 
}

