// Method to generate and print the 
// pascal triangle using nCr formula 
void printPascal(int n) 
{ 
    for (int line = 0; line < n; line++) 
    { 
        for (int i = 0; i <= line; i++) 
            printf("%d ",nCr(line, i)); 
        printf("\n"); 
    } 
} 

int nCr(int n, int r) 
{ 
    int p = 1, k = 1;  

    if (n - r < r) 
        r = n - r;  

    if (r != 0)  
    { 
        while (r) 
        { 
            p *= n; 
            k *= r; 
            int m = __gcd(p, k);  
            p /= m; 
            k /= m; 
            n--; 
            r--; 
        } 
    }  

    else
        p = 1;  
    return p; 
} 

