#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static int DAY_IN_MS = 86400;

int has_date_expired(int days, struct tm saved_date)
{
	char date_utc[25], date_local[25];
	strftime(date_utc, sizeof(date_utc), "%Y-%m-%d %H:%M:%S", &saved_date);
	strftime(date_local, sizeof(date_local), "%Y-%m-%d %H:%M:%S", &saved_date);

	time_t time_now = time(NULL);
	struct tm* time_now_struct = gmtime(&time_now);
	strftime(date_utc, sizeof(date_utc), "%Y-%m-%d %H:%M:%S", time_now_struct);

	time_t expires = mktime(time_now_struct) + (DAY_IN_MS * days);
	struct tm* expires_date = gmtime(&expires);
	strftime(date_local, sizeof(date_local), "%Y-%m-%d %H:%M:%S", expires_date);

	printf("savedDate \t\t %s \nexpiresDate \t %s\n", date_local, date_utc);

	return saved_date.tm_year < expires_date->tm_year &&
		saved_date.tm_mon < expires_date->tm_mon &&
		saved_date.tm_mday < expires_date->tm_mday &&
