int findCombinationsCount (int amount, int coins [], int length) {
    // Base case
    if (length == 1) {
        return (amount % coins[0] == 0);
    }
    // Initialize result
    int result = 0;
    // Subtract all the coins one by one and
    // recur
    for (int i = 0; i <= amount / coins[0]; i++)
        result += findCombinationsCount(amount - i * coins[0], coins + 1, length-1);
    return result;
}

