void throwException( const char* className) {
    void* exceptionClass;
    try {
        exceptionClass  = dlsym(RTLD_DEFAULT, className);
    } catch (char* e) {
        throw IllegalArgumentException(e);
    }
    try {
        if (class_is_subclass_of(exceptionClass, CheckedException)) {
            class_construct(exceptionClass,  CheckedException);
        } else if (class_is_subclass_of(exceptionClass, UncheckedException)) {
            class_construct(exceptionClass, UncheckedException);
        } else {
            throw IllegalArgumentException(strf("Not a valid exception type: %s", className));
        }
    } catch (char* e) {
        throw IllegalStateException(e);
    }
}

