#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char * join(char* separator, char ** values, int size) {
  if (size == 0) return ""; // for no values, return empty string
  char *sep = separator;
  int totalSize = (size - 1) * strlen(sep);
  for (int i = 0; i < size; i++) {
    if (values[i] == NULL) values[i] = "";
    else totalSize += strlen(values[i]);
  }
  char *joined = malloc(totalSize + 1); 
  int pos = 0;
  for (int i = 0, end = size - 1; i < end; i++) {
    strcpy(&joined[pos], values[i]);
    pos += strlen(values[i]);
    strcpy(&joined[pos], sep);
    pos += strlen(sep);
  }
  strcpy(&joined[pos], values[size - 1]);

  return joined;
}

