FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {

    int lenSrc = 0;
    int lenDest = 0;
    char *strAbsPathSrc = malloc(lenSrc);
    char *strAbsPathDest = malloc(lenDest);
    File *dstFile = (File) malloc(lenDest + file.toAbsolutePath().toString().substring(lenSrc).length());

    if (dstFile->exists()) {
        return FileVisitResult.CONTINUE;
    }
    if (!dstFile->getParentFile()->exists()) {
        dstFile->getParentFile()->mkdirs();
    }
    Files.copy(file, dstFile->toPath());

    free(strAbsPathSrc);
    free(strAbsPathDest);
    free(dstFile);
    return FileVisitResult.CONTINUE;
}

