#include <stdbool.h>
#define NULL 0

struct Node { 
  int data; 
  struct Node* next; 
}; 

bool hasLoop(struct Node* root) {
    if (root == NULL) 
        return false; 
    struct Node *slow = root, *fast = root; 
    int taken = 0, limit = 2; 

    while (fast->next != NULL) { 
        fast = fast->next; 
        taken++; 

        if (slow == fast) 
            return true; 

        if (taken == limit) { 
            taken = 0; 
            limit = limit << 1; 
            slow = fast; 
        } 
    } 
    return false; 
}

