struct ListNode
{
    int data;
    struct ListNode* next;
};

struct ListNode* switchPairs(struct ListNode* node) 
{
    if (node == NULL || node->next == NULL)
        return node;

    struct ListNode* top = node->next;
    struct ListNode* first = node;
    struct ListNode* second = first->next;
    struct ListNode* third;

    do
    {
        third = second->next;
        second->next = first;
        first->next = third;
        first = third;
        // printf("@@@ %s\n", node->data);
        if (first != NULL)
        {
            second->next->next = first->next;
            second = first->next;
        }
    } while (first != NULL && second != NULL);

    return top;
}

