int solution (int N) {
    int result = 0;
    while (N > 0) {
        if ((N & 1) == 1) {
            int temp = 0;
            while ((N >>= 1) > 0 && ((N & 1) != 1)) {
                temp ++;
            }
            result = (result > temp) ? result : temp;
        } else {
            N >>= 1;
        }
    }
    return result;
}

