int * createArray(int size) {
    int *result = (int*) malloc(size * sizeof(int));
    int limit = (size + 1) / 2;
    int start = 0;
    int value = 0;
    int idx = 0;
    do {
        for (int i = start; i < start + limit && idx < size; ++i) {
            result[idx] = value;
            ++idx;
        }
        start += limit;
        limit = (limit + 1) / 2;
        ++value;
    } while (idx < size);
    return result;
}

