#include <stdio.h>

void sort(int input[], int length) {
    for(int i = 0; i < length - 1; i++) {
        int k = i + 1;
        int nxtVal = input[k];

        while(input[k - 1] > nxtVal && k > 0) {
            input[k] = input[k - 1];
            k--;
        }
        input[k] = nxtVal;
    }

    printf("Medium sorting is done and the result is: ");
    for(int i = 0; i < length; i++) {
        printf("%d,", input[i]);
    }
}

