bool isAnagram(char *s1, char *s2) {
    if (strlen(s1) != strlen(s2)) return false;
    int n = strlen(s1);
    int charMap[256] = {0};
    for (int i = 0; i < n; i++) {
        char c1 = s1[i];
        charMap[c1]++;
        char c2 = s2[i];
        charMap[c2]--;
    }
    for (int i = 0; i < 256; i++) {
        if (charMap[i] != 0) return false;
    }
    return true;
}

