int singleNumber(int nums[], int n) 
{ 
    sort(nums, nums+n); 

    int answer = 0; 

    int i; 
    for (i = 0; i < n - 1; i = i + 2) { 
        if (nums[i] != nums[i + 1]) { 
            answer = nums[i]; 
            break; 
        } 
    } 

    if (answer == 0) 
        answer = nums[i]; 

    return answer; 
}

