int** getRows(int i, int j, int** array) {
  int rowValueLength = j - i + 1;
  int** another = (int**)malloc(sizeof(int*) * rowValueLength);
  int count = 0; 
  while (i <= j) { 
    another[count] = (int*)malloc(sizeof(int)*rowValueLength);
    for (int x = 0; x < rowValueLength; x++) { 
      another[count][x] = array[i][x]; 
      i++; 
    } 
    count++; 
  } 
  return another; 
}

