    char compressedString[1000];
    for (int i = 0; i < strlen(str);i++) {
        countConsecutive++;
        if (strlen(str) == (i + 1)) {
            sprintf(compressedString, "%s% c%d", compressedString, str[i], countConsecutive);
            countConsecutive = 0;
            break;
        } else if (str[i] != str[i + 1]) {
            sprintf(compressedString, "%s% c%d", compressedString, str[i], countConsecutive);
