int solution(int X, int A[], int array_size) 
{ 
    int leaves[X]; 
    memset(leaves, 0, sizeof(leaves)); // Fill with 0 

     for (int i=0; i<array_size; i++) 
      { 
          if (A[i] <= X) // If element inside range 
              leaves[A[i]-1]++; 

          if (check(leaves, X)) 
              return i; 
      } 

    return -1; 
} 

int check(int arr[], int X) 
{ 
    for (int i=0; i<X; i++) 
      if (arr[i] == 0) 
        return 0; // False 
    return 1; // True 
}

