void factorial7(mpz_t result, int n) {
    mpz_t temp;
    mpz_init_set_ui(temp, 1);
    mpz_set_ui(result, n);
    while (--n) {
        mpz_mul_ui(temp, temp, n);
    }
    mpz_swap(result, temp);
    mpz_clear(temp);
}

