int hashCode(Iterable* iterable) {
    int hashCode = 1;
    Iterator* i = iterator(iterable);
    while (hasNext (i)) {
        Object* obj = next (i);
        if (obj == NULL) {
            hashCode = (31 * hashCode);
        } else {
            hashCode = (31 * hashCode) + obj->hashCode ();
        }
    }
    return hashCode;
}

