        if (lensix > i) {
            strcat(answer, sixLetter[i]);
            strcat(answer, " ");
        }
        if (lenfive > i) {
            strcat(answer, fiveLetter[i]);
            strcat(answer, " ");
        }
        if (lenfour > i) {
            strcat(answer, fourLetter[i]);
        }
        strcat(answer, "\n");
        for (int j = 0; j < count; j++) {
            strcat(answer, "\t");
        }
        count++;
    }
    return answer;
}

