#include <pthread.h> 

typedef struct { 
    int say_this_many_times; 
    int* said_hello; 
} MyThread; 

void* thread_function(void *obj) 
{ 
    MyThread* mt = (MyThread*)obj; 
    while (*(mt->said_hello) == 0) { 
        if (mt->say_this_many_times > 0) { 
            printf("Hello "); 
            mt->say_this_many_times--;
            *(mt->said_hello) = 1; 
        } 
        else
            break; 
    } 
    return NULL; 
} 

int main() 
{ 
    MyThread* mt = (MyThread*)malloc(sizeof(MyThread)); 
    mt->say_this_many_times = 5; 
    mt->said_hello = (int*)malloc(sizeof(int)); 
    mt->said_hello[0] = 0; 

    pthread_t id; 
    pthread_create(&id, NULL, &thread_function, (void*)mt); 
    for (int i = 0; i < 5; i++) { 
        while (mt->said_hello[0] == 0) 
            ; 
        printf("Hello\n"); 
        mt->said_hello[0] = 0; 
    } 

    pthread_join(id, NULL); 
    free(mt); 
    return 0; 
}

