int solution(int X, int A[]) {
    int emptyPosition[X];
    for (int i = 0; i < X; i++) {
        emptyPosition[i] = i+1;
    }

    for (int i = 0; i < sizeof(A)/sizeof(int); i++) {
        int j = 0;
        while (j < X && emptyPosition[j] != A[i]) {
            j++;
        }
        if (j == X) {
            return -1;
        }
        else if (emptyPosition[j] == A[i]) {
            emptyPosition[j] = -1;
        }
        int allFilled = 1;
        for (int k = 0; k < X; k++) {
            if (emptyPosition[k] != -1) {
                allFilled = 0;
            }
        }
        if (allFilled == 1) {
            return i;
        }
    }
    return -1;
}

