#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <libssh2.h>
#include <libssh2_sftp.h>

int main(int argc, char *argv[])
{
    LIBSSH2_SESSION *session = NULL;
    LIBSSH2_SFTP *sftp_session = NULL;

    const char *src = getenv("user.home");
    src = strcat(src, "/test_file");

    int err;

    // Initialize LibSSH2
    libssh2_init(0);

    // Create a LibSSH2 Session
    session = libssh2_session_init();

    // Connect Session
    libssh2_session_handshake(session, "localhost");

    // Authenticate Session
    libssh2_userauth_publickey_fromfile_ex(session, getenv("user.name"), strlen(getenv("user.name")), NULL, NULL, 0, NULL);

    // Initialize SFTP session
    sftp_session = libssh2_sftp_init(session);

    // Put the file
    err = libssh2_sftp_rename(sftp_session, src, "/tmp");
    if (err) {
        printf("Error: %s\n", strerror(err));
    }

    // Close session
    libssh2_sftp_shutdown(sftp_session);

    // Disconnect Session
    libssh2_session_disconnect(session, "Normal Shutdown");

    // Cleanup
    libssh2_session_free(session);

    // Cleanup LibSSH2
    libssh2_exit();

    return 0;
}

