bool isPalindrome(char* str){
    int i, j;
    int str_length = strlen(str);
    char temp;
    for(i=0, j=str_length-1; i<j; i++, j--){
        if(str[i] >= 'a' && str[i] <= 'z'){
            str[i] = str[i] - 32;
        }
        if(str[j] >= 'a' && str[j] <= 'z'){
            str[j] = str[j] - 32;
        }
        if (str[i] != str[j]){
            return false;
        }
    }
    return true;
}

