char **split(char *string, const char *delim) {
    char **result = calloc(strlen(string), sizeof(char *));
    int index = 0;
    for(char *token = strtok(string, delim); token != NULL; token = strtok(NULL, delim)) {
        result[index++] = strdup(token);
    }
    result[index] = NULL;
    return result;
}

