void draw(Graphics2D g) {
    float arrowRatio = 0.5f;
    float arrowLength = 80.0f;
    BasicStroke stroke = getStroke(g);
    float endX = 350.0f;
    float veeX = endX - (stroke.getLineWidth() * 0.5f) / arrowRatio;
    Path2D.Float path = getPath();
    float waisting = 0.5f;
    float waistX = endX - (arrowLength * 0.5f);
    float waistY = (arrowRatio * arrowLength * 0.5f) * waisting;
    float arrowWidth = arrowRatio * arrowLength;
    moveTo(path, veeX - arrowLength, -arrowWidth);
    quadTo(path, waistX, -waistY, endX, 0.0f);
    quadTo(path, waistX, waistY, veeX - arrowLength, arrowWidth);
    lineTo(path, (veeX - (arrow_length * 0.75f)), 0.0f);
    lineTo(path, veeX - arrowLength, -arrowWidth);
    setColor(g. Color.BLUE);
    fill(g, path);
    setColor(g, Color.RED);
    draw(g, new Line2D.Float(50.0f, 0.0f, (veeX - (arrowLength * 0.5f)), 0.0f));
}

