int solution (int X, int A[], int size){
	int counter[X+1];
	int ans = -1;
	int x = 0;

	for (int i = 0; i < size; i++){
		if (counter[A[i]] == 0){
			counter[A[i]] = A[i];
			x += 1;
			if (x == X)
				return i;
		}
	}

	return ans;
}

