char **split(char *string, const char *delim) {
    char **tokens = malloc((strlen(string) / 2 + 1) * sizeof(char *));
    int index = 0;
    char *dupstr = strdup(string);
    char *token = strtok(dupstr, delim);
    while(token != NULL) {
        tokens[index++] = strdup(token);
        token = strtok(NULL, delim);
    }
    tokens[index] = NULL;
    free(dupstr);
    return tokens;
}

