char* compressBad(char* str)
{
    char* compressedString;
    if(str != NULL && strlen(str) > 0)
    {
        int countConsecutive = 1;
        char prevChar = str[0];
        int i, j = 0;
        for(i = 1; i < strlen(str); i++)
        {
            if(str[i] != prevChar)
            {
                compressedString[j++] = prevChar;
                compressedString[j++] = countConsecutive + '0'; 
                prevChar = str[i];
                countConsecutive = 1;
                continue;
            }
            countConsecutive++;
        }
        compressedString[j++] = prevChar;
        compressedString[j++] = countConsecutive + '0'; 
        compressedString[j] = '\0';
    }
    return compressedString;
}

