int solution (int X, int A[], int N)
{
    int seen[X + 1] = {0};
    int sum1 = 0, sum2 = 0;
    int i;

    for(i = 1; i <= X; i++)
    {
        sum1 += i;
    }

    for (i = 0; i < N; i++)
    {
        if(seen[A[i]])
            continue;
        seen[A[i]] = 1;
        sum2 += A[i];
        if(sum1 == sum2)
            return i;
    }

    return -1;

}

