  while ((n = LineNumberReader_read(lnr, buf)) != -1) {
    previousN = n;
  }
  int ln = LineNumberReader_getLineNumber(lnr);
  if (previousN == -1) {
    return 0;
  } else {
    char lastChar = buf[previousN - 1];
    if (lastChar == '\n' || lastChar == '\r') {
      return ln;
    }
  }
  return ln + 1;
}

