Node* reverse(Node* previous, Node* current) {
	if (previous == NULL) {
		return NULL;
	}

	if (previous == head) {
		previous->next = NULL;
	}

	if (current == NULL) {
		head = previous;
		return head;
	} else {
		Node* temp = current->next;
		current->next = previous;
		reverse(current, temp);
		}
	return NULL;
}

