int solution(int X, int A[], int len_A) {
    if (X > len_A) {
        return -1;
    }
    int isFilled[X];
    memset(isFilled, 0, sizeof(isFilled));
    int jumped = 0;
    for (int i=0; i < len_A; i++) {
        int x = A[i];
        if (x <= X) {
            if (isFilled[x-1] == 0) {
                isFilled[x-1] = 1;
                jumped += 1;
                if (jumped == X) {
                    return i;
                }
            }
        }
    }
    return -1;
}

