char* interleave(char* you, char* me) 
{ 
  int maxLength = (strlen(you) > strlen(me)) ? strlen(you) : strlen(me); 
  char* inter = (char *)malloc((maxLength * 2 + 1) * sizeof(char)); 

  int i; 
  inter[0] = '\0'; 
  for (i = 0; i < maxLength; i++) 
  { 
    if (i < (int)strlen(you)) 
    { 
      strncat(inter, &you[i], 1); 
    } 

    if (i < (int)strlen(me)) 
    { 
      strncat(inter, &me[i], 1); 
    } 
  } 

  return inter; 
}

