char* translate_to_english(char* phrase){
    if(!phrase)
        return NULL;

    char* finished = phrase;

    finished = str_replace(finished, "4", "a");
    finished = str_replace(finished, "1", "l");
    finished = str_replace(finished, "2", "z");
    finished = str_replace(finished, "5", "s");
    finished = str_replace(finished, "8", "b");
    finished = str_replace(finished, "0", "o");
    finished = str_replace(finished, "7", "t");
    finished = str_replace(finished, "|_|", "u");
    finished = str_replace(finished, "3", "e");
    finished = str_replace(finished, " e ", " 3 ");

    if (strstr(finished, "e ") == finished)
        finished = strcat("3 ", finished + 2);

    int len = strlen(finished);
    if (strstr(finished, " e") == finished + len - 2)
        finished[len-2] = 0;
        finished = strcat(finished, " 3");

    return finished;
}

char* str_replace(char* phrase, const char* from, const char* to) {
    char* token;
    const char delimiter[2] = " ";
    char* saveptr;
    static char buffer[512];
    char* orig = phrase;

    buffer[0] = '\0';

    while((token = strtok_r(orig, delimiter, &saveptr)) != NULL){
        orig = NULL;
        if(strstr(token, from) == token){
            strcat(buffer, to);
            strcat(buffer, token + strlen(from));
        }
        else strcat(buffer, token);
        strcat(buffer, " ");
    }
    buffer[strlen(buffer)-1] = '\0';

    return buffer;
}

