#include<stdio.h>
#include<stdlib.h>
#include<string.h>

#define SIZE 100

struct Frame
{
    char *frameTitle;
    int row;
    int col;
    int status;
};

struct TextArea
{
    int row;
    int col;
    char **text;
};

struct List
{
    int size;
    char *labels[SIZE];
    char **fields;
};

void createFrame(struct Frame *frame, char *title, int row, int col, int status)
{
    frame->frameTitle = title;
    frame->row = row;
    frame->col = col;
    frame->status = status;
}

void createTextArea(struct TextArea *textArea,int row,int col)
{
    int i,j;
    textArea->row = row;
    textArea->col = col;

    textArea->text = malloc(row * sizeof(char *));
    for(i = 0; i < row; i++)
    {
        textArea->text[i] = malloc(col * sizeof(char));
    }
    printf("\nInitialized the Text Area\n");
    printf("Enter the text\n");

    for(i = 0; i < row; i++)
    {
        for(j = 0; j < col; j++)
        {
            scanf(" %c", &textArea->text[i][j]);
        }
    }
}

void createList(struct List *list)
{
    int i, j;
    char *labels[] = {"To:", "Cc:", "Bcc:", "Subject:"};
    int size = sizeof(labels)/sizeof(labels[0]);

    list->size = size;
    for (i = 0; i < size; i++) {
        list->labels[i] = labels[i];
    }

    list->fields = malloc(size * sizeof(char *));
    for(i = 0; i < size; i++)
    {
        list->fields[i] = malloc(SIZE * sizeof(char));
    }
    printf("\nEnter the list items: \n");
    for(i = 0; i < size; i++)
    {
        printf("%s ", labels[i]);
        for(j = 0; j < SIZE; j++)
        {
            scanf(" %c", &list->fields[i][j]);
        }
    }
}

void displayFrame(struct Frame frame)
{
    printf("\nTitle of the Frame: %s\nRow Size: %d\nColumn Size: %d\nFrame Status: %d\n", frame.frameTitle, frame.row, frame.col, frame.status);
}

void displayTextArea(struct TextArea textArea)
{
    int i, j;
    printf("\nText Area\n");
    for(i = 0; i < textArea.row; i++)
    {
        for(j = 0; j<textArea.col; j++)
        {
            printf("%c", textArea.text[i][j]);
        }
        printf("\n");
    }
}

void displayList(struct List list)
{
    int i;
    printf("\nList\n");
    for(i = 0; i < list.size; i++)
    {
        printf("%s %s\n", list.labels[i], list.fields[i]);
    }
}

int main()
{
    struct Frame frame;
    createFrame(&frame, "New Message", 100, 100, 1);
    displayFrame(frame);

    struct TextArea textArea;
    createTextArea(&textArea, 10, 50);
    displayTextArea(textArea);

    struct List list;
    createList(&list);
    displayList(list);

