Object *tokenizer(char *value, char **delimeters, int arraySize) {
    Object *list;
    list = (Object*)malloc(arraySize * sizeof(Object));
    for (int i=0; i<arraySize; i++) {
        if (strstr(value, delimeters[i]) != NULL) {
            char **strArr = strsplit(value, "\\");
            int j = 0;
            while (strArr[j]) {
                list[j] = strArr[j];
                if (!listContains(list, delimeters[i])) {
                    list[j+1] = delimeters[i];
                }
                j++;
            }
        }
    }
    return list;
}

int listContains(Object *list, char *value){
    for (int i=0; i<sizeof(list); i++) {
        if (strcmp(list[i], value) == 0) {
            return 1;
        }
    }
    return 0;
}

char** strsplit(char* a_str, const char a_delim) {
    char** result = 0;
    size_t count = 0;
    char* tmp = a_str;
    char* last_comma = 0;
    char delim[2];
    delim[0] = a_delim;
    delim[1] = 0;
    while (*tmp) {
        if (a_delim == *tmp) {
            count++;
            last_comma = tmp;
        }
        tmp++;
    }
    count += last_comma < (a_str + strlen(a_str) - 1);
    count++;
    result = malloc(sizeof(char*) * count);
    if (result) {
        size_t idx  = 0;
        char* token = strtok(a_str, delim);
        while (token) {
            assert(idx < count);
            *(result + idx++) = strdup(token);
            token = strtok(0, delim);
        }
        assert(idx == count - 1);
        *(result + idx) = 0;
    }
    return result;
}

