int findArray (int array[], int subArray[], int arrayLen, int subArrayLen) {
    int index = - 1;
    arrayLoop : for (int i = 0; i < arrayLen; i ++) {
        if (array[i] == subArray[0]) {
            for (int j = 1; j < subArrayLen; j ++) {
                if (i + j > arrayLen - 1 || array[i + j] != subArray[j]) 
                    continue arrayLoop;
            }
            index = i;
        }
    }
    return index;
}

