int countClamps (int arr[], int size)
{
    int result = 0;
    int prev = 0;
    int same = 0;
    int i;

    for(i = 0; i < size; i++)
    {
        if (i == 0)
        {
            prev = arr[i];
        }
        else
        {
            if (arr[i] == prev)
            {
                if (same == 0)
                {
                    result += 1;
                    same = 1;
                }
            }
            else
            {
                prev = arr[i];
                same = 0;
            }
        }
    }

    return result;
}

