int binarySearch(int anArray [], int first, int last, int value) 
{ 
    while (first<=last) 
    { 
        int mid = (first+last)/2; 
        if (anArray[mid] == value) {
            return mid;
        } else if (anArray[mid] > value){
            last = mid - 1; 
        } else {
            first = mid + 1; 
        }
    }
    return -1;
  }

