int solution (int number) {
   char binary[32]; 
   itoa(number, binary, 2); 
   char * gaps[32]; 
   char * biggestGap = ""; 

   int i; 
   int gapSize = split(binary, gaps, '1');

   for (i = 0; i < (binary[strlen(binary)-1] == '1' ? 
                          gapSize : gapSize - 1); i++) {
      if (contains(gaps[i], '0') && strlen(gaps[i]) > strlen(biggestGap)) 
         strcpy(biggestGap, gaps[i]);
   }
   return strlen(biggestGap);
}

