#include<stdio.h> 
#include<stdlib.h> 

// Position in Linked list 
struct node { 
    int data; 
    double val; 
    struct node* next; 
}; 

// Insert a node at the beginning of Linked List 
void insertAtTheBegin(struct node** head_ref, int new_data, double new_val) 
{ 
    // Allocate memory for node 
    struct node* new_node = 
        (struct node*) malloc(sizeof(struct node)); 

    // put in the data 
    new_node->data = new_data; 
    new_node->val = new_val; 

    // Make next of new node as head 
    new_node->next = (*head_ref); 

    // move the head to point to the new node 
    (*head_ref) = new_node; 
} 

// Print linked list 
void printList(struct node* node) 
{ 
    while (node != NULL) { 
        printf("data: %d \tval: %lf \n", node->data, node->val); 
        node = node->next; 
    } 
} 

// Delete a node from linked list 
struct node* deleteNode(struct node* head_ref, int data) 
{ 
    // Store head node 
    struct node* temp = head_ref, *prev; 

    // If head node itself holds the key to be deleted 
    if (temp != NULL && temp->data == data) { 
        head_ref = temp->next;   // Changed head 
        free(temp);               // free old head 
        return head_ref; 
    } 

    // Search for the key to be deleted, keep track of the 
    // previous node as we need to change 'prev->next' 
    while (temp != NULL && temp->data != data) { 
        prev = temp; 
        temp = temp->next; 
    } 

    // If key was not present in linked list 
    if (temp == NULL) return head_ref; 

    // Unlink the node from linked list 
    prev->next = temp->next; 

    // Free memory 
    free(temp); 

    return head_ref; 
} 

int main() 
{ 
    // Start with the empty list 
    struct node* head = NULL; 

    // Insert 6.  So linked list becomes 6->NULL 
    insertAtTheBegin(&head, 1, 1.01); 
    insertAtTheBegin(&head, 2, 2.02); 
    insertAtTheBegin(&head, 3, 3.03); 
    insertAtTheBegin(&head, 4, 4.04); 
    insertAtTheBegin(&head, 5, 5.05); 

    printf("Created Linked List: "); 
    printList(head); 

    while (head != NULL) { 
        //deleting head element
        struct node* deleted_node = head; 
        head = head->next;
        printf("Deleted node: \n");
        printf("data: %d \tval: %f \n", deleted_node->data, deleted_node->val);
        free(deleted_node); 
    } 

    printf("\nLinked List after deleting all elements: "); 
    printList(head); 

    return 0; 
}

