int solution(int X, int A[]){
    int len = sizeof(A) / sizeof(A[0]);
    if (X > len){
        return -1;
    }
    int isFilled[X];
    for (int i = 0; i < X; i++){
        isFilled[i] = 0;
    }
    int jumped = 0; 
    for (int i = 0; i < len; i++){
        int x = A[i];
        if (x <= X){
            if (isFilled[x-1] == 0){
                isFilled[x-1] = 1;
                jumped += 1;
                if (jumped == X){
                    return i;
                }
            }
        }
    }
    return -1;
}

