void contextDestroyed(ServletContextEvent sce) {
    ClassLoader cl = Thread_currentThread()->getContextClassLoader();
    Enumeration* drivers = DriverManager_getDrivers();
    while (drivers->hasMoreElements()) {
        Driver* driver = (Driver*) drivers->nextElement();
        if (driver->getClass()->getClassLoader() == cl) {
            log_info("Deregistering JDBC driver %s", driver);
            try {
                DriverManager_deregisterDriver(driver);
            } catch (SQLException ex) {
                log_error("Error deregistering JDBC driver %s %s", driver, ex);
            }
        } else {
            log_trace("Not deregistering JDBC driver %s as it does not belong to this webapp's ClassLoader", driver);
        }
    }
    freeEnumeration(drivers);
}

