byte * read(FILE * file) {
  if (ftell(file) > MAX_FILE_SIZE) {
    throw FileTooBigException(file)
  }
  byte * ous = NULL;
  int ios = NULL;
  try {
    byte * buffer = malloc(sizeof(byte) * 4096);
    ous = malloc(sizeof(byte) * MAX_FILE_SIZE);
    ios = fopen(file, "rb");
    size_t read = 0;
    while ((read = fread(buffer, 1, 4096, ios)) != 0) {
      memcpy(ous + read, buffer, read);
    }
  }
  finally {
    if (ous != NULL) {
      free(ous);
    }
    if (ios != NULL) {
      fclose(ios);
    }
  }
  return ous;
}

