int solution(int X, int A[], int N) {
    int set[X + 1], sum1 = 0, sum2 = 0;
    memset(set, 0, sizeof(int) * (X + 1));
    for (int i = 0; i <= X; i++) {
        sum1 += i; 
    } 
    for (int i = 0; i < N; i++) { 
        if (set[A[i]] != 0) 
            continue; 
        set[A[i]] = 1;
        sum2 += A[i];
        if (sum1 == sum2) 
            return i; 
    } 
    return -1; 
}

