char *replace_host_in_url(char *original_url, char *new_authority) {
    int i = 0;
    int port;
    char *scheme;
    char *user_info;
    char *host;
    char *path;
    char *query;
    char *fragment;

    while (original_url[i] != ':' && original_url[i] != '\0') {
        i++;
    }

    // check valid ':'
    if (original_url[i] == '\0') {
        return NULL;
    }
    scheme = strndup(original_url, i);

    // get authority
    i += 3;
    int j = i;
    while (original_url[j] != '/' && original_url[j] != '\0') {
        j++;
    }
    int authority_len = j - i;
    char *authority = strndup(original_url + i, authority_len);

    // get user_info, host and port
    j = 0;
    while (authority[j] != '@' && authority[j] != '\0') {
        j++;
    }
    if (authority[j] == '@') {
        user_info = strndup(authority, j);
        j++;
        i = j;
    }
    else {
        user_info = '\0';
        j = 0;
    }
    while (authority[j] != ':' && authority[j] != '\0') {
        j++;
    }
    host = strndup(authority + i, j - i);
    if (authority[j] == ':') {
        j++;
        port = atoi(authority + j);
    }
    else {
        port = 0;
    }

    // get path
    int path_len = orig_url_len - (i + authority_len);
    path = strndup(original_url + i + authority_len, path_len);

    // get query and fragment
    i = j = 0;
    while (path[i] != '?' && path[i] != '#' && path[i] != '\0') {
        i++;
    }
    query = strndup(path + j, i -j);

    if (path[i] == '?') {
        j = i + 1;
    }
    else {
        j = i;
    }

    while (path[j] != '#' && path[i] != '\0') {
        j++;
    }
    fragmnet = strndup(path + i, j - i);

    // Formulate return
    char *ret;
    ret = malloc(strlen(scheme) + strlen(new_authority) + strlen(path) + 3);

    strcpy(ret, scheme);
    strcat(ret, "://");
    strcat(ret, new_authority);
    strcat(ret, path);
    if (port > 0 && port == payload->default_port) {
        int offset = strlen(ret);
        ret[offset - 1] = '\0';
    }

    free(scheme);
    free(authority);
    free(user_info);
    free(host);
    free(path);
    free(query);
    free(fragmnet);

    return ret;
}

int computeHeight () {
    int maxHeight = 0;
    int heights[parent_length];

    for (int vertex = 0; vertex < n; vertex++) {
        if (heights[vertex] != 0)
            continue;

        int height = 0;
        int currVertex = vertex;

        while (currVertex != -1) {
            if (heights[currVertex] != 0) {
                height += heights[currVertex];
                break;
            } else {
                height += 1;
                currVertex = parent[currVertex];
            }
        }
        maxHeight = max(maxHeight, height);
        currVertex = vertex;
        while (currVertex != -1) {
            if (heights[currVertex] != 0)
                break;
            else
            {
                heights[currVertex] = height;
                height -= 1;
                currVertex = parent[currVertex];
            }
        }
    }
    return maxHeight;
}

