bool unsignedMultiplyOverflows(long a, long b) { 
    if (a == 0 || b == 0) { 
        return false;
    }
    long a_half = a >> 1;
    long b_half = b >> 1;
    int a_last_bit = a & 1;
    int b_last_bit = b & 1;
    if (a_last_bit == 0) {
        return (long)(LONG_MAX + 1) / b < a_half;
    } else if (b_last_bit == 0) {
        return (long)(LONG_MAX + 1) / a < b_half;
    } else {
        return (long)(LONG_MAX - b_half) / b < a_half;
    }
}

