    if (decimal_index) {
        size_t s = strlen(decimal_index);
        strcpy(val_buffer, decimal_index + 1);
        decimalValue = val_buffer;
        value[decimal_index-value] = 0;
    }
    char* name = processor.getName(value);
    if (!strcmp(name, "")) {
        strcpy(name, ZERO_TOKEN);
    }
    else if (negative) {
        char temp[50];
        sprintf(temp, "%s%s%s", MINUS, SEPARATOR, name);
        strcpy(name, temp);
    }
    if (decimalValue != NULL) {
        strcpy(val_buffer, decimalValue);
        char* zeroDecimalValue = malloc(strlen(decimalValue));
        memset(zeroDecimalValue, '0',  strlen(decimalValue));
        if (!strcmp(decimalValue, zeroDecimalValue)) {
            char temp[50];
            sprintf(temp, "%s%s%s%s%s%s%s", name, SEPARATOR, UNION_AND, SEPARATOR, "zero", SEPARATOR, SCALE.getName(-strlen(decimalValue)));
