int solution (int X, int A[])
{
    int i, j;
    int sum1 = 0;
    int sum2 = 0;
    bool visited[X + 1];

    for (i = 0; i <= X; i++)
       visited[i] = 0;

    for (i = 0; i <= X; i++)
        sum1 += i;

    for (j = 0; j < sizeof(A); j++)
    {
        if (visited[A[j]] == 0)
        {
            sum2 = sum2 + A[j];
            visited[A[j]] = 1;
        }
        if (sum1 == sum2)
            return j;
    }

    return -1;
}

