int * solution(char *S, int *P, int *Q, int N, int M) {
    int result[M], lastIndexesA[N], lastIndexesC[N], lastIndexesG[N], lastA = -1, lastC = -1, lastG = -1;
    int *lastOccurencesMap[3] = {lastIndexesA, lastIndexesC, lastIndexesG};

    for(int i = 0; i < N; i++) {
        char c = S[i];
        if(c == 'A') {
            lastA = i;
        } else if(c == 'C') {
            lastC = i;
        } else if(c == 'G') {
            lastG = i;
        }
        lastOccurencesMap[0][i] = lastA;
        lastOccurencesMap[1][i] = lastC;
        lastOccurencesMap[2][i] = lastG;
    }
    for(int i = 0; i < M; i++) {
        int startIndex = P[i];
        int endIndex = Q[i];
        int minimum = 4;
        for(int n = 0; n < 3; n++) {
            int lastOccurence = getLastNucleotideOccurrence(startIndex, endIndex, n);
            if(lastOccurence != 0) {
                minimum = n + 1;
                break;
            }
        }
        result[i] = minimum;
    }
    return result;
}

