struct node *reverse(struct node *n, struct node *p) {
    if (n == NULL) 
        return NULL;
    if (n->next == NULL) {
        n->next = p;
        return n;
    }
    struct node *r = reverse(n->next, n);
    n->next = p;
    return r;
}

