int* solution(char* S, int* P, int* Q, int N) {
    char character_input[N]; 
    int integer_input[N]; 
    for (int i=0; i<N; i++) {
        character_input[i] = S[i];
        integer_input[i] = character_mapping(character_input[i]);
    }
    int* result = (int*) malloc(N*sizeof(int));
    for (int i=0; i<N; i++) {
        if (P[i] == Q[i]) { 
            result[i] = integer_input[P[i]];
            break;
        } 
        int sub_array[Q[i]-P[i]+1];      
        int j = 0;
        for (int k=P[i]; k<=Q[i]+1; k++) {
            sub_array[j] = integer_input[k];     
            j++;
        }
        int min_value = min(sub_array, j);
        result[i] = min_value;           
    }
    return result; 
}

