bool isBalanced(char *brackets) {
  struct map {
    char key;
    char value;
  } braces[3] = {
    {'(', ')'},
    {'[', ']'},
    {'{', '}'}
  };
  int len = strlen(brackets);

  if (len % 2 != 0) {
    return false;
  }

  char *halfBraces[len/2];
  int hbSize = 0; 

  for (int i = 0; i < len; i++) {
    char ch = brackets[i];
    for (int j = 0; j < 3; j++) { 
      if (ch == braces[j].key) {
        halfBraces[hbSize] = &braces[j].value;
        hbSize++;
        break;
      }
    }
    if (hbSize && ch != *halfBraces[hbSize-1]) {
      return false;
    }
  }
  return (hbSize == 0);
}

