char *decrypt(char *msg) { 
  regex_t regex;
  regcomp(&regex, "((\\d\\d)(#)|(\\d))", 0); 

  regmatch_t match;
  char result[256];
  char c[2];
  int i = 0;

  while (regexec(&regex, msg, 1, &match, 0)==0) {
    if (msg[match.rm_so+1]=='#'){
      c[0] = msg[match.rm_so];
    }
    else {
      c[0] = msg[match.rm_so];
      c[1] = msg[match.rm_so+1];
    }

    d =atoi(c);
    result[i++] = (char) (('a' + d) - 1);
    msg += match.rm_eo;
  }
  result[i]='\0';
  return result;
}

