void draw(Graphics2D *g)
{
    float arrowRatio = 0.5f;
    float arrowLength = 80.0f;
    BasicStroke *stroke = g->getStroke();
    float endX = 350.0f;
    float veeX;
    switch (stroke->getLineJoin())
    {
    case BasicStroke.JOIN_BEVEL:
        veeX = endX - stroke->getLineWidth() * 0.25f;
        break;

    default:
    case BasicStroke.JOIN_MITER:
        veeX = endX - stroke->getLineWidth() * 0.5f / arrowRatio;
        break;

    case BasicStroke.JOIN_ROUND:
        veeX = endX - stroke->getLineWidth() * 0.5f;
        break;
    }

    Path2D p;
    p.moveTo(veeX - arrowLength, -arrowRatio * arrowLength);
    p.lineTo(veeX, 0.0f);
    p.lineTo(veeX - arrowLength, arrowRatio * arrowLength);

    g->setColor(Color.BLUE);
    g->draw(p);
    g->setColor(Color.YELLOW);
    g->draw(Line2D(50.0f, 0.0f, veeX, 0.0f));
    g->setColor(Color.RED);
    g->draw(Line2D(50.0f, 0.0f, veeX - stroke->getLineWidth() * 0.25f, 0.0f));
}

