int* zeroFront(int* nums, int length){
    if (nums == NULL)
        return NULL;

	int zeroesPos = 0;
	int othersPos = length - 1; 
	int* result = malloc(sizeof(int) * length);

	for (int i = 0; i < length; ++i){
		if (nums[i] == 0){
			result[zeroesPos] = 0;
			zeroesPos++;
		}
		else {
			result[othersPos] = nums[i];
			othersPos--; 
		}
	}
	return result;

}

float getRandomNumberBetween(float numberOne, float numberTwo) {
    if (numberOne == numberTwo){
        printf("Both the numbers cannot be equal\n");
        return 0;
    }
    float rand, highRange, lowRange, lowRand, highRand, genRand;
    rand = rand();
	highRange = numberOne > numberTwo ? numberOne : numberTwo;
	lowRange = numberOne < numberTwo ? numberOne : numberTwo;
	lowRand = floorf(rand - 1);
	highRand = ceilf(rand + 1);
	genRand = (highRange - lowRange) * ((rand - lowRand) / (highRand - lowRand)) + lowRange;

	return genRand;
}

