// Zipping source_dir to zip_name
void pack(char *source_dir_path, char *zip_name)
{
	// create zipfile instance
	FILE *fp = fopen(zip_name, "w"); 

    // read directory and get all the files
    // and store their full path in a character array 
	struct dirent *dp;	
    DIR *d;
    char dir_files[200][200];	  
    int i=0;

    d=opendir(source_dir_path);
    if(d==NULL)
    {
    	printf("Error : Unable to open specified directory - %s\n",strerror(errno));
        return;
    }

    while((dp = readdir(d)))
    {
		   // copy file name to the 
            strcpy(dir_files[i],  source_dir_path);
	        strcat(dir_files[i], dp->d_name);

			// get file stats
		    struct stat st;
			stat(dir_files[i], &st);

			// check if the file is regular
			if(S_ISREG (st.st_mode))	
			{	
					fwrite(dir_files[i], 1, strlen(dir_files[i]), fp);
			}

			i++;
   }
   closedir(d);	
   fclose(fp);
}

