void copyFolder(char *src, char *dest) 
{ 
    DIR *dir = opendir(src); 
    struct dirent *entry = readdir(dir); 
    struct stat statbuf; 

    while (entry != NULL) { 
        lstat(entry->d_name, &statbuf); 

        if (S_ISDIR(statbuf.st_mode)) { 

            if (strcmp(".", entry->d_name) == 0 || 
                strcmp("..", entry->d_name) == 0) 
                continue; 

            char newSrc[1024]; 
            char newDest[1024]; 
            strcat(newSrc, src); 
            strcat(newDest, dest); 

            int len = strlen(newSrc); 
            newSrc[len] = '/'; 
            newSrc[len + 1] = '\0'; 
            len = strlen(newDest); 
            newDest[len] = '/';
            newDest[len + 1] = '\0'; 

            strcat(newSrc, entry->d_name); 
            strcat(newDest, entry->d_name); 

            copyFolder(newSrc, newDest); 
        } 

        else { 
            char srcFileName[1024]; 
            strcat(srcFileName, src); 
            int len = strlen(srcFileName); 
            srcFileName[len] = '/'; 
            srcFileName[len + 1] = '\0'; 
            strcat(srcFileName, entry->d_name); 

            char destFileName[1024]; 
            strcat(destFileName, dest); 
            len = strlen(destFileName); 
            destFileName[len] = '/'; 
            destFileName[len + 1] = '\0'; 
            strcat(destFileName, entry->d_name); 

            FILE *fp1, *fp2; 
            char c; 
            fp1 = fopen(srcFileName, "r"); 
            fp2 = fopen(destFileName, "w"); 

            if (!fp1) { 
                break; 
            } 
            if (!fp2) { 
                break; 
            } 

            c = fgetc(fp1); 
            while (c != EOF) { 
                fputc(c, fp2); 
                c = fgetc(fp1); 
            } 
            fclose(fp1); 
            fclose(fp2); 
        } 

        entry = readdir(dir); 
    } 
    closedir(dir); 
}

bool hasLoop (struct Node *root) {
  if (root == NULL) return false;
  struct Node *slow = root;
  struct Node *fast = root;
  int taken = 0;
  int limit = 2;
  while (fast->next != NULL) {
    fast = fast->next;
    taken++;
    if (slow == fast) return true;
    if (taken == limit) {
      taken = 0;
      limit <<= 1;
      slow = fast;
    }
  }
  return false;
}

