GenericType parse (StreamTokenizer tokenizer) {
  char *baseName = tokenizer.sval;
  tokenizer.nextToken ();
  List *params = malloc(sizeof(List));
  params->head = NULL;

  if (tokenizer.ttype == '<') {
    ListNode *curNode = malloc(sizeof(ListNode));
    do {
      tokenizer.nextToken ();
      curNode->data = parse (tokenizer);
      curNode->next = malloc(sizeof(ListNode));
    } while (tokenizer.ttype == ',');
    tokenizer.nextToken ();
  }
  GenericType output = GenericType(baseName, params);
  return output;
}

