int isPermutation(char *a, char *b) {
    int aArrayLen = strlen(a);
    int bArrayLen = strlen(b);
    if (aArrayLen != bArrayLen) {
        return 0;
    }
    int found = 0;
    for (int i = 0; i < aArrayLen; i++) {
        int eachA = a[i];
        for (int k = 0; k < bArrayLen; k++) {
            if (eachA == b[k]) {
                found++;
                b[k] = '\uFFFF';
                break;
            }
        }
    }
    return found == aArrayLen;
}

