char *compress(char *text) 
{ 
    char *result = (char *)malloc(sizeof(char)  * 100);
    int resultIndex = 0; 
    int index = 0; 

    while (text[index] != '\0') { 
        char c = text[index]; 
        int count = 0; 
        while (text[index] != '\0' && text[index] == c) { 
            count++; 
            index++; 
        } 
        if(count == 1) 
            result[resultIndex++] = c; 
        else { 
            result[resultIndex++] = count + '0'; 
            result[resultIndex++] = c; 
        } 
    } 

    result[resultIndex] = '\0'; 

    return result; 
}

