int search(int A[], int K) 
{ 
    int l = 0; 
    int u = sizeof(A) / sizeof(A[0]) - 1; 

    while (l <= u) { 
        int m = (u - l) / 2 + l; 
        if (A[m] < K) 
            l = m + 1; 
        else if (A[m] == K) 
            return m; 
        else
            u = m - 1; 
    } 

    return -1; 
}

