int solution(int X, int A[])
{
    int count[X];
    for (int i = 0; i < sizeOfArray(A) ; i++)
    {
        if(A[i] > X)
        {
            continue;    
        }
        else
        {
            count[A[i] - 1]++; 
        }
        if(i >= X - 1)
        {
            for(int j = 0 ; j < X ; j++)
            {
                if(count[j] == 0)
                {
                    break;
                }
                if(j == X - 1)
                {
                    return i;
                }
            }
        }

    }
    return -1;
}

int solution(int X, int A[], int size) {
  int check[X];
  memset(check, 0, X);

  int cmp = 0;
  int time = -1;
  for (int x = 0; x < size; x++) {
    int temp = A[x];
    if (temp <= X) {
      if (check[temp-1] > 0) {
        continue;
      }
      check[temp-1]++;
      cmp++;
    }
    if (cmp == X) {
      time = x;
      break;
    }
  }
  return time;
}

