        counts[positive]++;
        counts[negative]--;
    }

    // Compare the string
    for (i = 0; i < 26; i++)
    {
        // If not equal then not anagram
        if (counts[i] != 0)
            return false;
    }

    // If control reaches here, string is anagram
    return true;
}

