void findPrevLine(void){
	if (lastChar == -1){
		fseek(in, lastPosInFile, SEEK_SET);
		lastChar = fgetc(in);
	}

	currentLineEnd = currentLineStart;

	if (currentLineEnd == 0){
		currentLineEnd = -1;
		currentLineStart = -1;
		currentPos = -1;
		return;
	}

	long filePointer = currentLineStart - 1;

	while (1){
		filePointer--;
		if (filePointer < 0){
			break;
		}

		fseek(in, filePointer, SEEK_SET);
		int readByte = fgetc(in);
		if (readByte == 0xA && filePointer != lastPosInFile){
			break;
		}
	}

	currentLineStart = filePointer + 1;
	currentPos = currentLineStart;
}

