char* toJavaMethodName(const char* nonJavaMethodName) {
	char* nameBuilder;
	int len = 0;
	int capacity = 10;
	nameBuilder = (char*)malloc(sizeof(char) * capacity);

	bool capitalizeNextChar = false;
	bool first = true;

	for (int i = 0; i < strlen(nonJavaMethodName); i++) {
		char c = nonJavaMethodName[i];
		if (!isalnum(c)) {
			if (!first) {
				capitalizeNextChar = true;
			}
		}
		else {
			if (capitalizeNextChar) {
				c = toupper(c);
			}
			else {
				c = tolower(c);
			}
			capitalizeNextChar = false;
			first = false;
		}

		nameBuilder[len] = c;
		len++;

		if (len == capacity) {
			capacity *= 2;
			nameBuilder = (char*)realloc(nameBuilder, capacity * sizeof(char));
		}
	}

	nameBuilder[len] = '\0';

	return nameBuilder;
}

