int solution(int number) { 
    char binary[32] = {0}; 
    int i = 0, biggestGap = 0; 

    itoa(number, binary, 2); 

    while (binary[i] != '\0') { 
        int gap = 0; 

        if (binary[i] == '0') { 
            for (; binary[i] != '1' && binary[i] != '\0'; i++) { 
                gap++; 
            } 

            if (gap > biggestGap) { 
                biggestGap = gap; 
            } 
        } 

        i++; 
    } 

    return biggestGap; 
}

