struct location { 
    long int lon; 
    long int lat; 
    char desc[50]; 
}; 

// compares two locations on the basis 
// of their longitude and latitude 
int compare(const void* loc1, const void* loc2) 
{ 
    struct location* l1 = (struct location*)loc1; 
    struct location* l2 = (struct location*)loc2; 

    if (l1->lon > l2->lon) 
        return 1; 

    else if (l1->lon < l2->lon) 
        return -1;  

    else if (l1->lat > l2->lat) 
        return 1; 

    else if (l1->lat < l2->lat) 
        return -1; 

    return 0; 
} 

// prints each element of a sorted array 
void print(struct location* arr, int arr_size) 
{ 
    int i; 
    printf("["); 
    for (i = 0; i < arr_size; i++) {  
        printf("{\"lon\": %ld, \"lat\": %ld, \"desc\": %s}, ", 
              arr[i].lon, arr[i].lat, arr[i].desc); 
    }   
    printf("\b\b]"); 
} 

