int main() 
{ 
    struct location arr[] = { 
        { 0.001, 0.001, "test" }, { 0.002, 0.001, "test3" }, 
        { 0.002, 0.005, "test4" }, { 0.002, 0.001, "test5" }, 
        { 0.001, 0.001, "test2" } }; 
