void transform (XSSFWorkbook workbookOld, HSSFWorkbook workbookNew, XSSFCell cellOld, HSSFCell cellNew) {
    cellNew.cellComment = cellOld.cellComment;
    int hash = cellOld.cellStyle.hash;
    if (this.styleMap != NULL && ! this.styleMap.ContainsKey (hash)) {
        this.transform (workbookOld, workbookNew, hash, cellOld.cellStyle, workbookNew.CreateCellStyle ());
    }
    cellNew.cellStyle = this.styleMap.GetValueOrDefault (hash);
    switch (cellOld.cellType) {
        case Cell.CELL_TYPE_BLANK :
            break;
        case Cell.CELL_TYPE_BOOLEAN :
            cellNew.cellValue = cellOld.BooleanCellValue;
            break;
        case Cell.CELL_TYPE_ERROR :
            cellNew.cellValue = cellOld.ErrorCellValue;
            break;
        case Cell.CELL_TYPE_FORMULA :
            cellNew.cellValue = cellOld.cellFormula;
            break;
        case Cell.CELL_TYPE_NUMERIC :
            cellNew.cellValue = cellOld.NumericCellValue;
            break;
        case Cell.CELL_TYPE_STRING :
            cellNew.cellValue = cellOld.StringCellValue;
            break;
        default :
            printf ("transform: Unbekannter Zellentyp %d", cellOld.cellType);
    }
}

