bool isImmutable(Object* obj) 
{
    Class* objClass = obj->getClass();
    Class* superClass = objClass->getSuperclass();
    if(superClass != Immutable) 
    {
        return false;
    }
    if(!objClass->getModifiers()->isFinal())
    {
        return false;
    }
    Field** objFields = objClass->getDeclaredFields();
    for(int i = 0; i < objClass->getFieldCount(); i++)
    {
        if(!objFields[i]->getModifiers()->isFinal() || !isValidFieldType(objFields[i]->getType()))
        {
            return false;
        }
    }
    return true;
}

