int binarySearch(int intToSearch, int sortedArray[], int length)
{
   int low = 0;
   int high = length - 1;
   int mid;

   while (low <= high)
   {
      mid = low + (high - low)/2;

      if (intToSearch < sortedArray[mid])
         high = mid - 1;
      else if (intToSearch > sortedArray[mid])
         low = mid + 1;
      else
         return mid;
   }

return -1; 
}

char* shuffle(char text[]) 
{ 
    if (strlen(text) <= 1) 
        return text; 

    int split = strlen(text) / 2; 
    char* temp1 = shuffle(substr(text, 0, split)); 
    char* temp2 = shuffle(substr(text, split)); 
    if (rand() % 2 > 0.5) 
        return concat(temp1, temp2); 
    else
        return concat(temp2, temp1); 
}

