bool isBalanced(char *str) 
{ 
  int size = strlen(str); 
  bool result = false; 

  if (size < 2) 
    return false; 

  Stack s; 
  create(&s, size); 
  for (int i = 0; i < size; i++) { 
    char ch = str[i]; 
    if (divObjectRight[ch] != 0 
        && 
        divObjectLeft[ch] != 0) 
      continue; 

    if (divObjectLeft[ch] != 0) 
      push(&s, ch); 
    else { 
      if (!isEmpty(&s) && 
          top(&s) == divObjectRight[ch]) 
        result = true; 
      else
        return false; 
    } 
  } 

  if (!isEmpty(&s)) 
    return result = false; 

  return result; 
}

