int * solution(char * S, int * P, int * Q, int size)
{ 
	int * answer = malloc(size * sizeof(*answer));
	int cumulativeAnswers[4][strlen(S) + 1];

	for (int iii = 0; iii < strlen(S); iii++) {

		if (iii > 0) {
			for (int zzz = 0; zzz < 4; zzz++) {
				cumulativeAnswers[zzz][iii + 1] = cumulativeAnswers[zzz][iii]; 
			}
		}

		switch (S[iii]) {
			case 'A' :
				cumulativeAnswers[0][iii + 1]++;
				break;
			case 'C' :
				cumulativeAnswers[1][iii + 1]++;
				break;
			case 'G' :
				cumulativeAnswers[2][iii + 1]++;
				break;
			case 'T' :
				cumulativeAnswers[3][iii + 1]++;
				break;
		}
	}

	for (int iii = 0; iii < size; iii++) {
		for (int zzz = 0; zzz < 4; zzz++) {
			if ((cumulativeAnswers[zzz][Q[iii] + 1] - cumulativeAnswers[zzz][P[iii]]) > 0){
				answer[iii] = zzz + 1;
				break;
			}
		}
	} 

	return answer;
}

int solution(int N) 
{ 
    int result = 0; 
    int temp  = 0; 

    while (N > 0) 
    { 
        // If last bit of current number is 1 
        if ((N & 1) == 1) 
        { 
            // Count number of consecutive Zeros  
            while (((N >> 1) & 1) != 1) 
            { 
                temp++; 
                N = (N >> 1); 
            } 

            // Update result 
            if (result < temp) 
                result = temp; 
        } 

        // If current last bit is 0 
        else
        { 
            N = (N >> 1); 
        } 
    } 
    return result; 
}

