void invoke(struct Request *request, struct Response *response) {
    struct NextItem *next_item = getNext();
    next_item->invoke(request, response);
    struct Session *session = NULL;

    try {
        session = request->get_session_internal();
    }
    catch (int e) {
        log->error("%s: Unable to perform replication request. %s", getInfo(), e);
    }

    char *context = request->get_context()->get_name();
    char *task = request->get_path_info();
    if (task == NULL) {
        task = request->get_request_uri();
    }

    if (session != NULL) {
        if (log->is_debug_enabled()) {
            log->debug("%s: [session=%s, instanceof=%s, context=%s, request=%s]",
                getInfo(), session->get_id(), session->get_name(),
                context, task);
        }

        if (session->instanceof(ReplicatedSession)) {
            session->set_is_dirty(true);

            if (log->is_debug_enabled()) {
                log->debug("%s: [session=%s, context=%s, request=%s] marked DIRTY",
                    getInfo(), session->get_id(), context, task);
            }
        }
        else {
            List cycled_names = new LinkedList();
            HttpSession deltaSession = (HttpSession) session;
            for (Enumeration<String> names = deltaSession.getAttributeNames(); names.hasMoreElements(); ) {
                String name = names.nextElement();
                deltaSession.setAttribute(name, deltaSession.getAttribute(name));
                cycled_names.add(name);
            }

            if (log->is_debug_enabled()) {
                log->debug("%s: [session=%s, context=%s, request=%s] cycled attributes=%s",
                    getInfo(), session->get_id(), context, task, cycled_names);
            }
        }
    }
    else {
        char *id = request->get_requested_session_id();
        log->warn("%s: [session=%s, context=%s, request=%s] Session not available, unable to send session over cluster.",
            getInfo(), id, context, task);
    }
}

