// a structure to represent a node in the binary tree
struct node {
    int value;
    struct node *left;
    struct node *right;
};

// a function to insert a node in the binary tree
// returns a pointer to the root of the tree
struct node* insert(struct node* node, int value) {
    if (node == NULL) {
        node = (struct node*)malloc(sizeof(struct node));
        node->value = value;
        node->left = NULL;
        node->right = NULL;
    } else {
        if (value < node->value)
            node->left  = insert(node->left, value);
        else
            node->right = insert(node->right, value);
    }
    return node;
}

// a function to inorder traverse the binary tree
void inOrder(struct node *node) {
    if (node) {
        inOrder(node->left);
        printf("%d ", node->value);
        inOrder(node->right);
    }
}

