bool isAnagram(char* s1, char* s2) {
    if (strlen(s1) != strlen(s2)) {
        return false;
    }
    int seen[256] = { 0 };
    for (int i = 0; s1[i]; i++) {
        s1[i] = tolower(s1[i]);
        seen[s1[i]]++;
    }
    for (int i = 0; s2[i]; i++) {
        s2[i] = tolower(s2[i]);
        if (seen[s2[i]] == 0) {
            return false;
        }
        seen[s2[i]]--;
    }
    for (int i = 0; i < 256; i++) {
        if (seen[i] != 0) {
            return false;
        }
    }
    return true;
}

