int gcd(int a, int b) {
    if (a == INT_MIN) {
        if (b == INT_MIN) {
            return -1;
        }
        return (1 << __builtin_ctz(abs(b)));
    }

    if (b == INT_MIN) {
        return (1 << __builtin_ctz(abs(a)));
    }
    a = abs(a);
    b = abs(b);
    if (a == 0) {
        return b;
    }
    if (b == 0) {
        return a;
    }

    int factors_of_two_in_a = __builtin_ctz(a);
    int factors_of_two_in_b = __builtin_ctz(b);
    int common_factors_of_two = (factors_of_two_in_a > factors_of_two_in_b ? factors_of_two_in_b : factors_of_two_in_a);
    a = a >> factors_of_two_in_a;
    b = b >> factors_of_two_in_b;
    while (a != b) {
        if (a > b) {
            a -= b;
            a = a >> (__builtin_ctz(a));
        }
        else {
            b -= a;
            b = b >> (__builtin_ctz(b));
        }
    }
    return (a << common_factors_of_two);
}

