char* sequenceNums(int* nums, size_t size)
{
    char* sb;
    if (size == 0) {
        return "";
    }
    int begin = nums[0], end = nums[0];
    size_t sbSize = 0;
    sb = malloc(sizeof(char) * 255);
    if (sb == NULL) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        int cur = nums[i];
        if (cur - end <= 1) {
            end = cur;
        } else {
            appendRange(&sb, begin, end, &sbSize);
            begin = end = cur;
        }
    }
    appendRange(&sb, begin, end, &sbSize);
    sb[sbSize] = '\0';
    return sb;
}

