int * solution(char * S, int * P, int * Q, int N) {
    int * result = (int*) malloc (sizeof(int) * N);
    int * factor1 = (int*) malloc (sizeof(int) * strlen(S));
    int * factor2 = (int*) malloc (sizeof(int) * strlen(S));
    int * factor3 = (int*) malloc (sizeof(int) * strlen(S));
    int * factor4 = (int*) malloc (sizeof(int) * strlen(S));
    int factor1Sum = 0;
    int factor2Sum = 0;
    int factor3Sum = 0;
    int factor4Sum = 0;
    for (int i = 0; i < strlen(S); i++) {
        switch (S[i]) {
            case 'A' :
                factor1Sum ++;
                break;
            case 'C' :
                factor2Sum ++;
                break;
            case 'G' :
                factor3Sum ++;
                break;
            case 'T' :
                factor4Sum ++;
                break;
            default :
                break;
        }
        factor1[i] = factor1Sum;
        factor2[i] = factor2Sum;
        factor3[i] = factor3Sum;
        factor4[i] = factor4Sum;
    }
    for (int i = 0; i < N; i++) {
        int start = P[i];
        int end = Q[i];
        if (start == 0) {
            if (factor1[end] > 0) {
                result[i] = 1;
            } else if (factor2[end] > 0) {
                result[i] = 2;
            } else if (factor3[end] > 0) {
                result[i] = 3;
            } else {
                result[i] = 4;
            }
        } else {
            if (factor1[end] > factor1[start - 1]) {
                result[i] = 1;
            } else if (factor2[end] > factor2[start - 1]) {
                result[i] = 2;
            } else if (factor3[end] > factor3[start - 1]) {
                result[i] = 3;
            } else {
                result[i] = 4;
            }
        }
    }
    return result;
}

