public static long BinomCoefficient (long n, long k) {
    if (k > n) {
        return 0;
    }
    else if (n == k) {
        return 1;
    }
    else if (k > n - k) {
        k = n - k;
    }
    long c = 1;
    for (long i = k; i > 0; i--) {
        c *= n --;
        c /= i;
    }
    return c;
}

