public static T [] Slice < T > (this T [] arr, int offset, int length) {
    int start, end;
    start = Math.Max(Math.Min(offset, arr.Length - 1), 0); 
    end = Math.Min(start + Math.Max(length, 0), arr.Length); 
    int len = end - start;
    T [] result = new T [len];
    for (int i = 0; i < len; i ++) {
        result [i] = arr [start + i];
    }
    return result;
}

