        string[][] values = File.ReadLines(path)
            .Skip(1) 
            .Select(l => l.Split(','))
            .ToArray();
        var headers = File.ReadLines(path).First().Split(',');
        var result = values.Select(array => array.Zip(headers, (value, header) =>  
