public static GenericType Parse(StreamTokenizer tokenizer)
{
    string baseName = tokenizer.sval;

    tokenizer.nextToken();
    List<GenericType> params = new List<GenericType>();

    if(tokenizer.ttype == '<')
    {
        do
        {
            tokenizer.nextToken();
            params.Add(Parse(tokenizer));
        }
        while(tokenizer.ttype == ',');

        tokenizer.nextToken();
    }

    return new GenericType(baseName, params);
}

