public void Invoke(Request request, Response response)
{
    GetNext().Invoke(request, response);

    Session session = null;
    try
    {
        session = request.GetSessionInternal();
    }
    catch (Exception e)
    {
        Log.Error($"{GetInfo()}: Unable to perform replication request. {e}");
    }

    var context = request.GetContext().Name;
    var task = request.GetPathInfo();
    if (task == null)
    {
        task = request.GetRequestURI();
    }

    if (session != null)
    {
        if (Log.IsDebugEnabled())
        {
            Log.Debug($"{GetInfo()}: [session={session.Id}, instanceof={session.GetType()}, context={context}, request={task}]");
        }

        if (session is ReplicatedSession)
        {
            ((ReplicatedSession)session).IsDirty = true;
            if (Log.IsDebugEnabled())
            {
                Log.Debug($"{GetInfo()}: [session={session.Id}, context={context}, request={task}] marked DIRTY");
            }
        }
        else
        {
            var cycledNames = new List<string>();
            var deltaSession = session as HttpSession;
            foreach (var name in deltaSession.GetAttributeNames())
            {
                deltaSession.SetAttribute(name, deltaSession.GetAttribute(name));
                cycledNames.Add(name);
            }

            if (Log.IsDebugEnabled())
            {
                Log.Debug($"{GetInfo()}: [session={session.Id}, context={context}, request={task}] cycled attributes={cycledNames}");
            }
        }
    }
    else
    {
        var id = request.GetRequestedSessionId();
        Log.Warn($"{GetInfo()}: [session={id}, context={context}, request={task}] Session not available, unable to send session over cluster.");
    }
}

