public static bool IsAnagram(string s1, string s2)
{
    if (s1.Length != s2.Length)
    {
        return false;
    }
    s1 = s1.ToLower();
    s2 = s2.ToLower();
    char[] c1 = s1.ToCharArray();
    char[] c2 = s2.ToCharArray();
    Array.Sort(c1);
    Array.Sort(c2);
    string sc1 = new string(c1);
    string sc2 = new string(c2);
    return sc1 == sc2;
