public string GetName(string value)
{
    StringBuilder buffer = new StringBuilder();
    int offset = -1;
    int number;
    if (value.Length > 3)
    {
        number = int.Parse(value.Substring(value.Length - 3), System.Globalization.NumberStyles.Integer);
    }
    else
    {
        number = int.Parse(value, System.Globalization.NumberStyles.Integer);
    }
    number %= 100;
    if (number < 10)
    {
        offset = (number % 10) - 1;
    }
    else if (number < 20)
    {
        offset = (number % 20) - 1;
    }
    if (offset != -1 && offset < TOKENS.Length)
    {
        buffer.Append(TOKENS[offset]);
    }
    return buffer.ToString();
}

