public byte [] OpenAndCombine (IList < byte [] > documents) {
    MemoryStream mainStream = new MemoryStream ();
    mainStream.Write (documents [0], 0, documents [0].Length);
    mainStream.Position = 0;
    int pointer = 1;
    byte [] ret;
    try {
        using (WordprocessingDocument mainDocument = WordprocessingDocument.Open (mainStream, true))
        {
            XElement newBody = XElement.Parse (mainDocument.MainDocumentPart.Document.Body.OuterXml);
            for (pointer = 1; pointer < documents.Count; pointer ++) {
                WordprocessingDocument tempDocument = WordprocessingDocument.Open (new MemoryStream (documents [pointer]), true);
                XElement tempBody = XElement.Parse (tempDocument.MainDocumentPart.Document.Body.OuterXml);
                newBody.Add (tempBody);
                mainDocument.MainDocumentPart.Document.Body = new Body (newBody.ToString ());
                mainDocument.MainDocumentPart.Document.Save ();
                mainDocument.Package.Flush ();
            }
        }}
    catch (OpenXmlPackageException oxmle) {
        throw new OfficeMergeControlException (string.Format (CultureInfo.CurrentCulture, "Error while merging files. Document index {0}", pointer), oxmle);
    }
    catch (Exception e) {
        throw new OfficeMergeControlException (string.Format (CultureInfo.CurrentCulture, "Error while merging files. Document index {0}", pointer), e);
    }
    finally {
        ret = mainStream.ToArray ();
        mainStream.Close ();
        mainStream.Dispose ();
    }
    return (ret);
}

public int Read(char[] cbuf, int off, int len)
{
    int read = base.Read(cbuf, off, len);
    if (read == -1)
    {
        return -1;
    }

    int pos = off - 1;
    for (int readPos = off; readPos < off + read; readPos++)
    {
        if (cbuf[readPos] == '@')
        {
            continue;
        }
        else
        {
            pos++;
        }

        if (pos < readPos)
        {
            cbuf[pos] = cbuf[readPos];
        }
    }
    return pos - off + 1;
}

public static bool IsInPolygon (Point [] poly, Point p) {
    Point p1, p2;
    bool inside = false;
    if (poly.Length < 3) {
        return inside;
    }
    var oldPoint = new Point (poly [poly.Length - 1].X, poly [poly.Length - 1].Y);
    for (int i = 0; i < poly.Length; i ++) {
        var newPoint = new Point (poly [i].X, poly [i].Y);
        if (newPoint.X > oldPoint.X) {
            p1 = oldPoint;
            p2 = newPoint;
        } else {
            p1 = newPoint;
            p2 = oldPoint;
        }
        if ((newPoint.X < p.X) == (p.X <= oldPoint.X) && (p.Y - (long) p1.Y) * (p2.X - p1.X) < (p2.Y - (long) p1.Y) * (p.X - p1.X)) {
            inside = ! inside;
        }
        oldPoint = newPoint;
    }
    return inside;
}

