public static string[] Tokenizer (string text, string[] delims)
{
    for (int i=0; i<delims.Length; ++i)
    {
        int index = text.IndexOf(delims[i]);
        if (index >=0)
        {
            string[] tail = Tokenizer(text.Substring(index + delims[i].Length), delims);
            string[] list = new string[tail.Length + 2];
            list[0] = text.Substring(0, index);
            list[1] = delims[i];
            Array.Copy(tail, 0, list, 2, tail.Length);
            return list;
        }
    }
    return new string[] {text};
}

