    StringBuilder sb = new StringBuilder();
    if (words[0].Length > 0)
    {
        sb.Append(char.ToUpper(words[0][0]) + words[0].Substring(1).ToLower());
        for (int i = 1; i < words.Length; i++)
        {
            sb.Append(" ");
            sb.Append(char.ToUpper(words[i][0]) + words[i].Substring(1).ToLower());
        }
    }
    return sb.ToString();
}

