public override int Read(byte[] buffer, int offset, int count)
{
    int result = 0;
    while (count > 0 && !bExit)
    {
        try
        {
            int len = stream.Read(buffer, offset, count);
            if (len == 0 || !client.Connected)
            {
                break;
            }
            result += len;
            count -= len;
            offset += len;
        }
        catch (Exception e)
        {
            if (e.HResult == -2146232800)
            {
                continue;
            }
            else
            {
                break;
            }
        }
    }
    return result;
}

