public static bool CheckZero(object toCheck)
{
    Type[] numerics = new Type[] { typeof(int), typeof(double), typeof(float), typeof(long), typeof(short), typeof(byte), typeof(int), typeof(double), typeof(float), typeof(long), typeof(short), typeof(byte)};

    try
    {
        Type clazz = toCheck.GetType();

        var fields = clazz.GetFields();
        foreach (var field in fields)
        {
            Type type = field.FieldType;
            bool isNumeric = false;
            foreach (Type numeric in numerics)
            {
                if (type == numeric)
                {
                    isNumeric = true;
                    break;
                }
            }
            if (isNumeric)
            {
                object value = field.GetValue(toCheck);
                if (value == 0)
                {
                    return true;
                }
            }
        }
    }
    catch (Exception e)
    {
        Console.WriteLine(e);
    }
    return false;
}

