public string[] Parse (string input) {
        bool open = false;
        int openIndex = -1;
        List<string> matches = new List<string>();
        for (int i = 0; i < input.Length; i++)
        {
            if (!open && input[i] == OpenToken)
            {
                open = true;
                openIndex = i;
            } else if (open && input[i] == CloseToken)
            {
                open = false;
                string match = input.Substring(openIndex +1, i - openIndex);
                matches.Add(match);
            } else if (open && input [i] == OpenToken && ThrowOnError)
            {
                throw new Exception("Open token found while match is open");
            } else if (!open && input[i] == CloseToken && ThrowOnError)
            {
                throw new ArgumentException("Close token found while match is not open");
            }
        }         
        return matches.ToArray();
}

public int solution (int X, int [] A) {
    int len = A.Length;
    if (X > len) {
        return - 1;
    }
    int [] isFilled = new int [X];
    int jumped = 0;
    Array.Fill (isFilled, 0);
    for (int i = 0; i < len; i ++) {
        int x = A [i];
        if (x <= X) {
            if (isFilled [x - 1] == 0) {
                isFilled [x - 1] = 1;
                jumped += 1;
                if (jumped == X) {
                    return i;
                }
            }
        }
    }
    return - 1;
}

