public static int maxBlock(string str)
{
    int maxCounter = 1;
    int counter = 1;

    if (str.Length == 0)
    {
        return 0;
    }

    for (int i = 1; i < str.Length; i++)
    {
        if (str[i - 1] == str[i])
        {
            counter++;
        }
        else
        {
            if (counter > maxCounter)
            {
                maxCounter = counter;
            }

            counter = 1;
        }
    }

    return Math.Max(maxCounter, counter);
}

private static IEnumerable < int > Approximations3 (IEnumerable < int > values, int target) {
    int sum = 0;
    bool first = true;
    foreach (var item in values) {
        if (sum + item < target || first) {
            first = false;
            sum += item;
        } else {
            int diff1 = Math.Abs(sum + item - target); //Added absolute value logic
            int diff2 = Math.Abs(target - sum); //Added absolute value logic
            if (diff1 < diff2) {
                yield return sum + item;
                sum = 0;
                first = true;
            } else {
                yield return sum;
                sum = item;
            }
        }
    }
    if (first)
        yield break;
    yield return sum;
}

