public static List < Int32 > LocatePartialSet (Byte [] superset, Byte [] partialSet) {
    if ((superset == null) || (partialSet == null)) {
        throw new ArgumentNullException ();
    }
    if ((superset.Length < partialSet.Length) || (superset.Length == 0) || (partialSet.Length == 0)) {
        return new List < Int32 > ();
    }
    var result = new List < Int32 > ();
    Int32 currentPosition = 0;
    Int32 maxPosition = superset.Length - partialSet.Length;
    while (currentPosition < maxPosition) {
        Int32 matchCount = EstimateMatches (superset, currentPosition, partialSet);
        if (matchCount == partialSet.Length) {
            result.Add (currentPosition);
        }
        currentPosition ++;
        if (matchCount > 0) {
            currentPosition += matchCount - 1;
        }
    }
    return result;
}

[Microsoft.SqlServer.Server.SqlFunction (IsDeterministic = true, IsPrecise = true, DataAccess = DataAccessKind.None)] public static SqlBytes BinaryCompress (SqlBytes input) {
    if (input.IsNull)
        return SqlBytes.Null;
    using (MemoryStream result = new MemoryStream ())
    {
        using (DeflateStream deflateStream = new DeflateStream (result, CompressionMode.Compress, true))
        {
            deflateStream.Write (input.Buffer, 0, input.Buffer.Length);
            deflateStream.Flush ();
            deflateStream.Close ();
        } return new SqlBytes (result.ToArray ());
    }}

