public int[] Solution(string s, int[] p, int[] q) 
{ 
    char[] characterInput = s.ToCharArray(); 
    int[] integerInput = new int[characterInput.Length]; 
    for (int counter = 0; counter < characterInput.Length; counter++) 
    { 
        integerInput[counter] = characterMapping[characterInput[counter]]; 
    } 
    int[] result = new int[p.Length]; 
    for (int index = 0; index < p.Length; index++) 
    { 
        if (p[index] == q[index]) 
        { 
            result[index] = integerInput[p[index]]; 
            break; 
        } 
        int[] subArray = new int[q[index] - q[index] - 1]; 
        int currentLength = 0; 
        for (int i = p[index]; i <= q[index]; i++) 
        { 
            subArray[currentLength] = integerInput[i]; 
            currentLength++; 
        } 
        int minimumValue = subArray.Min(); 
        result[index] = minimumValue; 
    } 
    return result; 
}

public static string DeriveCurveName (PrivateKey privateKey)
{
    if (privateKey is java.security.interfaces.ECPrivateKey) {
        var pk = privateKey as java.security.interfaces.ECPrivateKey;
        var params = pk.GetParams();
        return DeriveCurveName(EC5Util.ConvertSpec(params, false));
    } 
    else if (privateKey is org.bouncycastle.jce.interfaces.ECPrivateKey) 
    {
        var pk = privateKey as org.bouncycastle.jce.interfaces.ECPrivateKey;
        return DeriveCurveName(pk.GetParameters());
    }
    else
    { 
        throw new ArgumentException("Can only be used with instances of ECPrivateKey (either jce or bc implementation)");
    }

}

