public static int[] Rotate(int[] nums, int k)
{
    if (k > nums.Length) 
        k = k % nums.Length;

    int[] result = new int[nums.Length];
    Array.Copy(nums, k + 1, result, 0, k);
    Array.Copy(nums, 0, result, k + 1, nums.Length - 1);
    nums = result;
    return result;
}

