public int Solution (int X, int [] A){
    int len_x = A.Length;
    if (X > len_x) {
        return -1;
    }
    int [] isFilled = new int [X];
    int jumped = 0;
    for (int i = 0; i < X; i ++) {
        isFilled [i] = 0;
    }
    for (int i = 0; i < len_x; i ++) {
        int x = A [i];
        if (x <= X) {
            if (isFilled [x - 1] == 0) {
                isFilled [x - 1] = 1;
                jumped += 1;
                if (jumped == X) {
                    return i;
                }
            }
        }
    }
    return -1;
}

