private static float GetRandomNumberBetween(float numberOne, float numberTwo) {
    if (numberOne == numberTwo) {
        throw new Exception("Both the numbers can not be equal");
    }
    float rand = (float) new Random().NextDouble();
    float highRange = Math.Max(numberOne, numberTwo);
    float lowRange = Math.Min(numberOne, numberTwo);
    float lowRand = (float) Math.Floor(rand - 1);
    float highRand = (float) Math.Ceiling(rand + 1);
    float genRand = (highRange - lowRange) * ((rand - lowRand) / (highRand - lowRand)) + lowRange;
    return genRand;
}

public int [] Solution (string S, int [] P, int [] Q) {
    int N = S.Length;
    int M = P.Length;
    int [] result = new int [M];
    int [,] lastOccurrencesMap = new int [3, N];
    int lastA = - 1;
    int lastC = - 1;
    int lastG = - 1;
    for (int i = 0;
    i < N; i ++) {
        char c = S [i];
        if (c == 'A') {
            lastA = i;
        } else if (c == 'C') {
            lastC = i;
        } else if (c == 'G') {
            lastG = i;
        }
        lastOccurrencesMap [0, i] = lastA;
        lastOccurrencesMap [1, i] = lastC;
        lastOccurrencesMap [2, i] = lastG;
    }
    for (int i = 0;
    i < M; i ++) {
        int startIndex = P [i];
        int endIndex = Q [i];
        int minimum = 4;
        for (int n = 0;
        n < 3; n ++) {
            int lastOccurence = GetLastNucleotideOccurrence (startIndex, endIndex, n, lastOccurrencesMap);
            if (lastOccurence != 0) {
                minimum = n + 1;
                break;
            }
        }
        result [i] = minimum;
    }
    return result;
}

