public static double Pow (double basevalue, int exponentvalue) {
    if (exponentvalue == 0) {
        return 1;
    }
    if (exponentvalue == 1) {
        return baseValue;
    }
    double result = Pow (basevalue, exponentvalue / 2);
    result *= result;
    if (exponentvalue %2 == 1) {
        result *= baseValue;
    }
    return result;
}

