    foreach (PropertyInfo propertyInfo in leftType.GetProperties ()) {
        //Check if Can Read
        if (propertyInfo.CanRead) {
            object leftValue = propertyInfo.GetValue (first, null);
            object rightValue = propertyInfo.GetValue (second, null);
