private TreeNode findValueStartingAtNode (TreeNode node, IComparable value) {
    Console.WriteLine ("looking for value {0}", value);
    if (node == null) {
        Console.WriteLine ("node is null -- returning null");
        return null;
    }
    if (value.CompareTo (node.data) == 0) {
        Console.WriteLine ("value found at current node");
        Console.WriteLine ("current node data is {0}", node.data);
        Console.WriteLine ("done and returning node");
        return node;
    } 
    TreeNode left = findValueStartingAtNode (node.left_child, value);
    TreeNode right = findValueStartingAtNode (node.right_child, value);
    if (left != null || right != null)
        return (left == null)? right : left;
    Console.WriteLine ("value not found in either child");
    Console.WriteLine ("current node data is {0}", node.data);
    return null;
}

private static String [] SplitCodeArray (String codeToExecute) {
    List < String > items = new List < String > ();
    Int32 parenAndbracketCount = 0;
    String buffer = "";
    foreach (Char c in codeToExecute.ToCharArray ()) {
        if (c == '.') {
            if (buffer.Length > 0) {
                items.Add (buffer);
                buffer = "";
            }
            continue;
        } else if (c == '[') {
            parenAndbracketCount ++;
            if (buffer.Length > 0) {
                items.Add (buffer);
            }
            buffer = c.ToString ();
        } else if (c == ']' || c == ')') {
            parenAndbracketCount --;
            buffer += c;
            if (buffer.Length > 0) {
                items.Add (buffer);
                buffer = "";
            }
        } else if (Char.IsWhiteSpace (c) || Char.IsControl (c)) {
            if (parenAndbracketCount == 0) {
                continue;
            } else {
                buffer += c;
            }
        } else if (c == '(') {
            parenAndbracketCount ++;
            buffer += c;
        } else {
            buffer += c;
        }
    }
    if (buffer.Length > 0) {
        items.Add (buffer);
    }
    return items.ToArray ();
}

