    for (char c in strChars) {
        word.Add(c);
    }
    while (true) 
    {
        if ( (word.Count == 1) || (word.Count == 0) ) 
        {
            return true;
        }
        if ( word[0] == word[word.Count - 1] ) 
        {
            word.RemoveAt(0);
            word.RemoveAt(word.Count -1);
        }
        else 
        {
            return false;
        }
    } 
}

public static int Delta (int a, int b) {
    int delta = 0;
    if (a == b) {
        return 0;
    } else if (a < b) {
        while (a < b) {
            a ++;
            delta ++;
        }
        return delta;
    } else {
        while (b < a) {
            b ++;
            delta ++;
        }
        return delta;
    }
}

