public static Dictionary < int, string > GetItemList (Type enumType) {
    if (enumType.IsEnum == false)
        throw new ApplicationException("GetItemList does not support non-enum types");
    Dictionary < int, string > list = new Dictionary < int, string > ();
    foreach (FieldInfo field in enumType.GetFields(BindingFlags.Static | BindingFlags.GetField |BindingFlags.Public)) {
        int value;
        string display;
        value = (int) field.GetValue(null);
        display = Enum.GetName(enumType, value);
        foreach (Attribute currAttr in field.GetCustomAttributes(true)) {
            EnumValueDataAttribute valueAttribute = currAttr as EnumValueDataAttribute;
            if (valueAttribute != null)
                display = valueAttribute.NameString;
        }
        list.Add(value, display);
    }
    return list;
}

