public static long EvaluateExpression(string expression, Dictionary<string, long> variables)
{
    long result = 0;
    string[] terms = expression.Split(' ');

    for (int i = 0; i < terms.Length; i += 2)
    {
        switch (terms[i])
        {
            case "*":
                result = variables[terms[i - 1]] * variables[terms[i + 1]];
                break;
            // other terms
        }
        if (i + 2 >= terms.Length)
            break;
    }
    return result;
}

