public static string Join(string sep, params string[] values)
{
    // Check if empty
    if (values.Length == 0)
        return string.Empty;

    // Calculate total size
    int totalSize = (values.Length - 1) * sep.Length;
    for (int i = 0; i < values.Length; i++)
    {
        if (values[i] == null)
            values[i] = string.Empty;
        else
            totalSize += values[i].Length;
    }

    // Create character array to store joined values
    char[] joined = new char[totalSize];
    int pos = 0;
    for (int i = 0, end = values.Length - 1; i < end; i++)
    {
        // Copy value from value array into joined character array
        values[i].CopyTo(0, joined, pos, values[i].Length);
        pos += values[i].Length;

        // Copy value from separator into joined character array
        sep.CopyTo(0, joined, pos, sep.Length);
        pos += sep.Length;
    }

    // Copy last value into joined character array
    values[values.Length - 1].CopyTo(0, joined, pos, values[values.Length - 1].Length);

    // Return the joined character array
    return new string(joined);
}

