private static int pow (int x, int n) {
    if (n == 0) return 1;
    if (n == 1) return x;
    if (n < 0) {
        if (x == 1 || (x == 2 && n == - 1)) return 1;
        else return 0;
    }
    long num;
    if ((n & 1) == 0) {
        num = pow (x * x, n / 2);
        if (num > int.MaxValue) return int.MaxValue;
        return (int) num;
    } else {
        num = x * pow (x * x, n / 2);
        if (num > int.MaxValue) return int.MaxValue;
        return (int) num;
    }
}

public void Enqueue (T item) {
    // Check if queue already contains item
    int index = queue.IndexOf (item);
    if (index > -1) {
        // Remove item if already included
        queue.RemoveAt (index);
    }
    // Add item to queue
    queue.Add (item);
    // Truncate the queue to maximumSize if needed
    while (queue.Count > maximumSize) {
        Dequeue ();
    }
}

