private static IEnumerable<IEnumerable<T>> SplitItemsIterator<T>(IEnumerable<T> source, int size)
{
    List<T> output = new List<T>();
    foreach(T item in source)
    {
        output.Add(item);
        if (output.Count == size)
        {
            yield return output;
            output = new List<T>();
        }
    }
    if (output.Count > 0)
        yield return output;
}

