public class BinaryTreeWithoutRecursion<T>
{
    public class Node
    {
        public T data;
        public Node left;
        public Node right;
        public Node(T d)
        {
            data = d;
            left = null;
            right = null;
        }
    }

    public Node root;
    public BinaryTreeWithoutRecursion()
    {
        root = null;
    }

    public void Insert(T d)
    {
        Node newNode = new Node(d);
        if (root == null)
            root = newNode;
        else
        {
            Node temp = root;
            while (true)
            {
                if (Convert.ToInt32(d) < Convert.ToInt32(temp.data))
                {
                    if (temp.left == null)
                    {
                        temp.left = newNode;
                        break;
                    }
                    else
                        temp = temp.left;
                }
                else if (Convert.ToInt32(d) > Convert.ToInt32(temp.data))
                {
                    if (temp.right == null)
                    {
                        temp.right = newNode;
                        break;
                    }
                    else
                        temp = temp.right;
                }
                else
                    break;
            }
        }
    }

    public void InOrderPrint()
    {
        Node temp = root;
        Stack<Node> s = new Stack<Node>();
        while (true)
        {
            while (temp != null)
            {
                s.Push(temp);
                temp = temp.left;
            }
            if (s.Count > 0)
            {
                temp = s.Pop();
                Console.Write(temp.data + " ");
                temp = temp.right;
            }
            else
                break;
        }
    }

    public static void Main(string[] args)
    {
        BinaryTreeWithoutRecursion<int> bt = new BinaryTreeWithoutRecursion<int>();
        bt.Insert(1);
        bt.Insert(2);
        bt.Insert(3);
        bt.Insert(4);
        bt.Insert(5);
        bt.Insert(6);
        bt.Insert(7);
        bt.InOrderPrint();
    }
}

