public static object Read(JsonElement in) {
    if (in.IsJsonArray()) {
        List<object> list = new List<object>();
        JsonArray arr = in.GetAsJsonArray();
        foreach (JsonElement anArr in arr) {
            list.Add(Read(anArr));
        }
        return list;
    } else if (in.IsJsonObject()) {
        Dictionary<string, object> map = new Dictionary<string, object>();
        JsonObject obj = in.GetAsJsonObject();
        Iset<KeyValuePair<string, JsonElement>> entitySet = obj.EntrySet();
        foreach (KeyValuePair<string, JsonElement> entry in entitySet) {
            map.Add(entry.Key, Read(entry.Value));
        }
        return map;
    } else if (in.IsJsonPrimitive()) {
        JsonPrimitive prim = in.GetAsJsonPrimitive();
        if (prim.IsBoolean()) {
            return prim.GetAsBoolean();
        } else if (prim.IsString()) {
            return prim.GetAsString();
        } else if (prim.IsNumber()) {
            Number num = prim.GetAsNumber();
            if (Math.Ceiling(num.DoubleValue) == num.LongValue) {
                return num.LongValue;
            } else {
                return num.DoubleValue;
            }
        }
    }
    return null;
}

