public int Solution (int [] A) {
  if (A.Length == 2) return Math.Abs (A [0] - A [1]);
  int [] s1 = new int [A.Length - 1];
  s1 [0] = A [0];
  for (int i = 1; i < A.Length - 1; i ++) {
    s1 [i] = s1 [i - 1] + A [i];
  }
  int [] s2 = new int [A.Length - 1];
  s2 [A.Length - 2] = A [A.Length - 1];
  for (int i = A.Length - 3; i> = 0; i --) {
    s2 [i] = s2 [i + 1] + A [i + 1];
  }
  int finalSum = Int32.MaxValue;
  for (int j = 0; j < s1.Length; j ++) {
    int sum = Math.Abs (s1 [j] - s2 [j]);
    if (sum < finalSum) finalSum = sum;
  }
  return finalSum;
}

private static int FastPower(int x, int n) {
    if (n == 0) return 1;
    if (n == 1) return x;
    if(n % 2 == 0) return FastPower(x * x, n / 2);
    return x * FastPower(x * x, (n - 1) / 2);
}

