public void Sort(int[] input)
{
    for (int i = 0; i < input.Length - 1; i++)
    {
        int k = i + 1;
        int nxtVal = input[k];

        while (input[k - 1] > nxtVal && k > 0)
        {
            input[k] = input[k - 1];
            k--;
        }
        input[k] = nxtVal;
    }

    Console.WriteLine("Medium sorting is done and the result is:");
    for (int i = 0; i < input.Length; i++)
    {
        Console.Write(input[i] + ",");
    }
}

public static bool IsManagedAssembly (string fileName) {
    uint peHeader;
    uint peHeaderSignature;
    ushort machine;
    ushort sections;
    uint timestamp;
    uint pSymbolTable;
    uint noOfSymbol;
    ushort optionalHeaderSize;
    ushort characteristics;
    ushort dataDictionaryStart;
    uint [] dataDictionaryRVA = new uint [16];
    uint [] dataDictionarySize = new uint [16];
    try {
        Stream fs = new FileStream (fileName, FileMode.Open, FileAccess.Read);
        BinaryReader reader = new BinaryReader (fs);
        fs.Position = 0x3C;
        peHeader = reader.ReadUInt32 ();
        fs.Position = peHeader;
        peHeaderSignature = reader.ReadUInt32 ();
        machine = reader.ReadUInt16 ();
        sections = reader.ReadUInt16 ();
        timestamp = reader.ReadUInt32 ();
        pSymbolTable = reader.ReadUInt32 ();
        noOfSymbol = reader.ReadUInt32 ();
        optionalHeaderSize = reader.ReadUInt16 ();
        characteristics = reader.ReadUInt16 ();
        dataDictionaryStart = Convert.ToUInt16 (Convert.ToUInt16 (fs.Position) + 0x60);
        fs.Position = dataDictionaryStart;
        for (int i = 0; i < 15; i ++) {
            dataDictionaryRVA [i] = reader.ReadUInt32 ();
            dataDictionarySize [i] = reader.ReadUInt32 ();
        }
    }
    catch {
        return false;
    }
    finally {
        fs.Close ();
    }
    if (dataDictionaryRVA [14] == 0)
        return false;
    else
        return true;
}

public int ComputeHeight()
{
    int maxHeight = 0;
    int[] heights = new int[parent.Length];

    for (int vertex = 0; vertex < n; vertex++)
    {
        if (heights[vertex] != 0)
            continue;

        int height = 0;
        int currVertex = vertex;

        while (currVertex != -1)
        {
            if (heights[currVertex] != 0)
            {
                height += heights[currVertex];
                break;
            }
            else
            {
                height++;
                currVertex = parent[currVertex];
            }
        }
        maxHeight = Math.Max(maxHeight, height);
        currVertex = vertex;
        while (currVertex != -1)
        {
            if (heights[currVertex] != 0)
                break;
            else
            {
                heights[currVertex] = height;
                height--;
                currVertex = parent[currVertex];
            }
        }
    }
    return maxHeight;
}

