public static void Shuffle(object[] array)
{
    int n = array.Length;
    for (int i = 0; i < n; i++)
    {
        int r = i + (int)(Random.Range(0.0f, 1.0f)*(n - i));
        object swap = array[r];
        array[r] = array[i];
        array[i] = swap;
    }
