public int solution (int X, int [] A) {
    int list [] = A;
    int sum = 0;
    int searchedValue = X;
    int sumV = searchedValue * (searchedValue + 1) / 2;
    bool [] visited = new bool [searchedValue + 1];
    for (int iii = 0; iii < list.Length; iii ++) {
        if (list [iii] <= searchedValue && ! visited [list [iii]]) {
            sum += list [iii];
            if (sum == sumV) {
                return iii;
            }
            visited [list [iii]] = true;
        }
    }
    return - 1;
}

public static String replace (String oldStr, String newStr, String input) 
{ 
    StringBuilder sb = new StringBuilder (); 
    int i; 
    int prev = 0; 
    while ((i = input.IndexOf(oldStr, prev)) >= 0) 
    { 
        sb.Append(input.Substring(prev, i)).Append(newStr); 
        prev = i + oldStr.Length; 
    } 
    sb.Append(input.Substring(prev)); 
    return sb.ToString(); 
}

