public static string Rainbow(int numOfSteps, int step)
    {
                float r = 0.0f;
                float g = 0.0f;
                float b = 0.0f;
                float h = step / (float)numOfSteps;
                int i = (int)(h * 6);
                float f = h * 6f - i;
                float q = 1f - f;
                if (i % 6 <= 0)
                {
                    r = 1f;
                    g = f;
                    b = 0f;
                }
                else if (i % 6 == 1)
                {
                    r = q;
                    g = 1f;
                    b = 0f;
                }
                else if (i % 6 == 2)
                {
                    r = 0f;
                    g = 1f;
                    b = f;
                }
                else if (i % 6 == 3)
                {
                    r = 0f;
                    g = q;
                    b = 1f;
                }
                else if (i % 6 == 4)
                {
                    r = f;
                    g = 0f;
                    b = 1f;
                }
                else if (i % 6 == 5)
                {
                    r = 1f;
                    g = 0f;
                    b = q;
                }
                return "#" + ((int)(r * 255)).ToString("X2") + ((int)(g * 255)).ToString("X2") + ((int)(b * 255)).ToString("X2");
}

