static byte [] Year2Bcd (int year) {
    if (year < 0 || year > 9999)
        throw new ArgumentException ();
    int bcd = 0;
    int temp = year;
    for (int digit = 4; digit > 0; -- digit) {
        int nibble = temp % 10;
        bcd |= nibble << ((digit - 1) * 4);
        temp /= 10;
    }
    byte [] result = new byte[2];
    result[0] = (byte) ((bcd >> 8) & 0xff);
    result[1] = (byte) (bcd & 0xff);
    return result;
}

