public static string Rainbow(int numOfSteps, int step)
    {
                double r = 0.0;
                double g = 0.0;
                double b = 0.0;
                double h = (double)step / (double)numOfSteps;
                int i = (int)(h * 6);
                double f = h * 6.0 - i;
                double q = 1.0 - f;
                switch (i % 6)
                {
                    case 0:
                        {
                            r = 1.0;
                            g = f;
                            b = 0.0;
                            break;
                        }
                    case 1:
                        {
                            r = q;
                            g = 1.0;
                            b = 0.0;
                            break;
                        }
                    case 2:
                        {
                            r = 0.0;
                            g = 1.0;
                            b = f;
                            break;
                        }
                    case 3:
                        {
                            r = 0.0;
                            g = q;
                            b = 1.0;
                            break;
                        }
                    case 4:
                        {
                            r = f;
                            g = 0.0;
                            b = 1.0;
                            break;
                        }
                    case 5:
                        {
                            r = 1.0;
                            g = 0.0;
                            b = q;
                            break;
                        }
                }
                return "#" + ((int)(r * 255)).ToString("X2") + ((int)(g * 255)).ToString("X2") + ((int)(b * 255)).ToString("X2");
}

