public static IEnumerable < IEnumerable < T > > Segment < T > (IEnumerable < T > sequence, Func < T, T, int, bool > newSegmentIdentifier) {
    var index = 0;
    using (var iter = sequence.GetEnumerator ())
    {
        var segment = new List < T > ();
        var prevItem = default (T);
        while (iter.MoveNext ()) {
            var isNewSegment = newSegmentIdentifier (iter.Current, prevItem, index);
            ++ index;
            prevItem = iter.Current;
            if (! isNewSegment) {
                segment.Add (iter.Current);
                continue;
            }
            yield return segment;
            segment = new List < T > {iter.Current};
        }
        if (segment.Count > 0)
            yield return segment;
    }
}

public T GetFromPool () {
    T item = null;
    do
        {
            Monitor.Enter (this);
            try
            {
                if (this.pool.Count == 0) {
                    if (this.currentSize < this.maxSize) {
                        item = this.constructor ();
                        this.currentSize ++;
                    }
                } else {
                    item = this.pool.Dequeue ();
                }
            }
            finally
            {
                Monitor.Exit (this);
            }
            if (null == item) {
                this.poolReleasedEvent.WaitOne ();
            }
        } while (null == item);
    return item;
}

private static string GetPropertyName < TPropertySource > (Expression < Func < TPropertySource, object > > expression) 
	{
    	var lambda = expression as LambdaExpression;
    	if (lambda.Body is UnaryExpression) 
		{
        	var unaryExpr = lambda.Body as UnaryExpression;
        	if (unaryExpr.Operand is MemberExpression) 
			{
            	var memberExpression = unaryExpr.Operand as MemberExpression;
            	var propertyInfo = memberExpression.Member as PropertyInfo;
            	return propertyInfo.Name;
        	}
    	}
    	else if (lambda.Body is MemberExpression)
		{
        	var memberExpression = lambda.Body as MemberExpression;
        	var propertyInfo = memberExpression.Member as PropertyInfo;
        	return propertyInfo.Name;
    	}
   		 Debug.Assert (false, "Please provide a lambda expression like 'n => n.PropertyName'");
    	return null;
}

