    var ret = base.Read(buffer, index, count);
    for (int i = 0; i < ret; i++) {
        int idx = index + i;
        char curChar = buffer[idx];
        if (!((curChar == 0x9)
            || (curChar == 0xA)
            || (curChar == 0xD)
            || ((curChar >= 0x20) && (curChar <= 0xD7FF)) 
            || ((curChar >= 0xE000) && (curChar <= 0xFFFD)))) {
            buffer[idx] = ' ';
        }
    }
    return ret;
}

public IEnumerable < T > DequeueAll () {
    while (! shutDown) {
        do
            {
                T item;
                lock (queue)
                {
                    if (queue.Count == 0) {
                        if (shutDown)
                            break;
                        Monitor.Wait (queue);
                        if (queue.Count == 0)
                            break;
                    }
                    item = queue.Dequeue ();
                } yield return item;
            } while (! shutDown);
    }
}

