static void ThrowException(string exClassName) 
{
    Class clazz;
    try 
    {
        clazz = Class.ForName(exClassName);
    }
    catch (ClassNotFoundException cnfe) 
    {
        throw new InternalError(exClassName, cnfe);
    }

    if(typeof(CheckedException).IsAssignableFrom(clazz)) 
    {
        throw newException(clazz.asSubclass(typeof(CheckedException)));
    }
    else if (typeof(UncheckedException).IsAssignableFrom(clazz)) 
    {
        throw newException(clazz.asSubclass(typeof(UncheckedException)));
    }
    else 
    {
        throw new InternalError(exClassName + " is not a valid exception");
    }
}

