public static String Join(string delimiter, params string[] parts)
{
    var builder = new StringBuilder();
    foreach (String part in parts)
    {
        if (!String.IsNullOrEmpty(part))
        {
            if (builder.Length > 0)
            {
                builder.Append(delimiter);
            }
            builder.Append(part);
        }
    }
    return builder.ToString();
}

public static int gcd(int a, int b)
{
    if (a == int.MinValue)
    {
        if (b == int.MinValue)
        {
            throw new ArgumentException("GCD is greater than int.MaxValue");
        }
        return 1 << (int)Math.Log(Math.Abs(b), 2);
    }
    if (b == int.MinValue)
    {
        return 1 << (int)Math.Log(Math.Abs(a), 2);
    }
    a = Math.Abs(a);
    b = Math.Abs(b);
    if (a == 0)
    {
        return b;
    }
    if (b == 0)
    {
        return a;
    }
    int factorsOfTwoInA = (int)Math.Log(a, 2);
    int factorsOfTwoInB = (int)Math.Log(b, 2);
    int commonFactorsOfTwo = Math.Min(factorsOfTwoInA, factorsOfTwoInB);
    a >>= factorsOfTwoInA;
    b >>= factorsOfTwoInB;
    while (a != b)
    {
        if (a > b)
        {
            a -= b;
            a >>= (int)Math.Log(a, 2);
        }
        else
        {
            b -= a;
            b >>= (int)Math.Log(b, 2);
        }
    }
    return a << commonFactorsOfTwo;
}

