public static bool IsExpectedPassword(string password, byte[] salt, byte[] hash)
{
    if(password == null || salt == null || hash == null)
    {
        Console.WriteLine("Password, salt and hash must not be null");
        return false;
    }

    try
    {
        byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
        byte[] all = passwordBytes.Concat(salt).ToArray();
        SHA3.DigestSHA3 md = new SHA3.Digest512();
        md.Update(all);
        byte[] digest = md.Digest();
        return StructuralComparisons.StructuralEqualityComparer.Equals(digest, hash);
    }
    catch (UnsupportedEncodingException e)
    {
        Console.WriteLine("Caught UnsupportedEncodingException e: {0}", e.message);
    }
    return false;
}

