public static string SequenceNums(int[] nums)
{
    var sb = new StringBuilder();
    if (nums.Length == 0)
        return "";
    var begin = nums[0];
    var end = nums[0];
    foreach (var cur in nums)
    {
        if (cur - end <= 1)
            end = cur;
        else
        {
            AppendRange(sb, begin, end);
            begin = end = cur;
        }
    }

    AppendRange(sb, begin, end);
    return sb.ToString().Substring(1);
}

