int Solution(int N) {
    string binary = Convert.ToString(N, 2);
    int largestGap = 0;
    int gap = 0;
    for(int i = 1; i < binary.Length; i++) {
        while(i < binary.Length && binary[i] == '0') {
            i++;
            gap++;
        }
        if(gap > largestGap && i < binary.Length) {
            largestGap = gap;
        }
        gap = 0;
    }
    return largestGap;
}

