static int Pow(int x, int n) { 
    if (n == 0)
        return 1; 
    else if (n == 1) 
        return x; 
    else if (n < 0) { 
        if (x == 1 || (x == 2 && n == -1)) 
            return 1; 
        else 
            return 0; 
    } 
    else { 
        long num; 
        if ((n & 1) == 0) 
            num = Pow(x * x, n / 2); 
        else 
            num = x * Pow(x * x, n / 2); 
        if (num > int.MaxValue) 
            return int.MaxValue; 
        return (int) num; 
    } 
}

