public PointF? Intersect (LineEquation other) {
    if (isVertical && other.isVertical)
        return null;
    else if (a == other.a)
        return null;
    else if (isVertical) {
        return other.Intersect(xConstForVertical);
    }
    else if (other.isVertical) {
