public static int binarySearch(int intToSearch, int[] sortedArray)
{
  int lower = 0;
  int upper = sortedArray.Length - 1;
  while (lower <= upper)
  {
    int mid = lower + (upper - lower) / 2;
    if (intToSearch < sortedArray[mid])
    {
      upper = mid - 1;
    }
    else if (intToSearch > sortedArray[mid])
    {
      lower = mid + 1;
    }
    else
      return mid;
  }
  return -1;
}

