private static int score (char [] a, char [] b, int idxA, int idxB) {
    int value;
    if (idxA >= a.Length || idxB >= b.Length) {
        value = 0;
    } else if (a [idxA] == b [idxB]) {
        value = 1 + score (a, b, idxA + 1, idxB + 1);
    } else {
        int x;
        int y;
        x = score (a, b, idxA + 1, idxB);
        y = score (a, b, idxB, idxB + 1);
        value = Math.Max (x, y);
    }
    return (value);
}

