    var TanAngle = Math.Tan (Math.PI * Frequency / SampleRate);
    double norm = 1/ (1 + TanAngle / Q + TanAngle * TanAnglee); 
    A0 = TanAngle * TanAngle * norm;
    A1 = 2 * A0;
    A2 = A0; 
    B1 = 2 * (TanAngle * TanAngle - 1) * norm;
    B2 = (1 - TanAngle / Q + TanAngle * TanAngle) * norm;
}

