public static bool IsAnagram (string first, string second) 
{
    string positive = first.ToLower ();
    string negative = second.ToLower ();
    if (positive.Length != negative.Length)
    {
        return false;
    }
    int [] counts = new int [26];
    int diff = 0;
    for (int i = 0; i < positive.Length; i++)
    {
        int pos = (int) positive [i] - 97;
        if (counts [pos] >= 0) 
        {
            diff ++;
        } 
        else 
        {
            diff --;
        }
        counts [pos] ++;
        int neg = (int) negative [i] - 97;
        if (counts [neg] <= 0) 
        {
            diff ++;
        } 
        else 
        {
            diff --;
        }
        counts [neg] --;
    }
    return diff == 0;
}

