private int CountDivisorsOfNumber (int number) {
    int count = 0;
    double end = Math.Sqrt (number);
    for (int i = 1; i < end; i ++) {
        if (number % i == 0)
            count += 2;
    }
    if (end == (int)end)
        count ++;
    return count;
}

