public void InOrder(BSTNode m_root)
{
    if (m_root == null) {
        return;
    }
    var myStack = new Stack<BSTNode>();
    var current = m_root;
    while (current != null) {
        myStack.Push(current);
        current = current.GetLeft();
    }
    while (myStack.Any()) {
        current = myStack.Pop();
        System.Console.Write(current.GetInfo() + " ");
        if (current.GetRight() != null) {
            current = current.GetRight();
            while (current != null) {
                myStack.Push(current);
                current = current.GetLeft();
            }
        }
    }
}

