public static void Dispose (this ILGenerator ilGen) {
    if (ilGen != null) {
        var type = typeof (ILGenerator);
        var fieldInfo = type.GetField("m_localSignature", BindingFlags.Instance | BindingFlags.NonPublic);
        var sigHelper = fieldInfo.GetValue(ilGen) as SignatureHelper;
        sigHelper?.Dispose();
        fieldInfo.SetValue(ilGen, null);
    }
}

public RegionContext GetContext (string regionCode) {
    RegionContext temp = null;
    RegionContext rc = null;
    bool containskey = false;
    lock (this.contextCache) {
        containskey = this.contextCache.ContainsKey (regionCode.ToUpper ());
    }
    if (!containskey) {
        temp = new RegionContext (regionCode);
        lock (this.contextCache) {
            if (!this.contextCache.ContainsKey (regionCode.ToUpper ())) {
                this.contextCache.Add (regionCode.ToUpper (), temp);
                rc = temp;
                temp = null;
            }
        }
    }
    else {
        rc = this.contextCache[regionCode.ToUpper ()]; 
    } 
    return rc;
}

public static StreamReader LoadWeb (string URL) {
    if (! URL.StartsWith ("http")) {
        URL = "http://" + URL;
    }
    HttpWebResponse myResponse = null;
    HttpWebRequest myRequest = (HttpWebRequest) WebRequest.Create (new Uri (URL));
    System.IO.Stream myStream = null;
    StreamReader myStreamReader = null;
    myRequest.Method = "POST";
    myRequest.Proxy = WebProxy.GetDefaultProxy();
    myRequest.Timeout = 60000;
    myRequest.KeepAlive = true;
    try {
        myResponse = (HttpWebResponse) myRequest.GetResponse ();
    }
    catch (Exception ex) {
        System.Windows.Forms.MessageBox.Show ("Error : " + ex.Message);
        return null;
    }
    if (myResponse != null) {
        if (myResponse.StatusCode == System.Net.HttpStatusCode.OK) {
            myStream = myResponse.GetResponseStream ();
            myStreamReader = new StreamReader (myStream);
        }
    }
    return myStreamReader;
}

