public int Solution(int X, int[] A)
{
    int size = A.Length;
    int[] check = new int[X];
    int cmp = 0;
    int time = -1;
    for (int x = 0; x < size; x++)
    {
        int temp = A[x];
        if (temp <= X)
        {
            if (check[temp - 1] > 0)
            {
                continue;
            }
            check[temp - 1]++;
            cmp++;
        }
        if (cmp == X)
        {
            time = x;
            break;
        }
    }
    return time;
}

public int Compare (string s1, string s2) {
    int s1r, s2r;
    var s1n = IsNumeric (s1, out s1r);
    var s2n = IsNumeric (s2, out s2r);
    if (s1n && s2n)
        return s1r - s2r;
    else if (s1n)
        return - 1;
    else if (s2n)
        return 1;
    var num1 = Regex.Match (s1, @"(\d+)([^\d]+)(\d+)$");
    var num2 = Regex.Match (s2, @"(\d+)([^\d]+)(\d+)$");
    if (num1.Groups[1].Value == num2.Groups[1].Value && num1.Groups[2].Value == num2.Groups[2].Value) {
        if (num1.Groups[3].Success && num2.Groups[3].Success)
            return Int32.Parse (num1.Groups[3].Value) - Int32.Parse (num2.Groups[3].Value);
        else if (num1.Groups[3].Success)
            return 1;
        else if (num2.Groups[3].Success)
            return - 1;
    }
    return string.Compare (s1, s2, true);
}

public static bool IsPowerOfTwo (ulong n) {
    /* Algorithm:
       iterate through bits, if the number of '1' bits more than
       one then return false else return ture. */
    if (n == 0)
        return false;
    int count = 0; 
    for (ulong i = n; i > 0; i >>= 1) 
        if ((i & 1) == 1)
            count++; 
    if (count > 1)
       return false;
    return true;
}

private static JToken NormalizeToken (JToken token) {
    JObject o;
    JArray array;
    if ((o = token as JObject) != null) {
        List < JProperty > orderedProperties = new List < JProperty > (o.Properties ());
        orderedProperties.Sort (delegate (JProperty x, JProperty y) {
            return x.Name.CompareTo (y.Name);
        });
        JObject normalized = new JObject ();
        foreach (JProperty property in orderedProperties) {
            normalized.Add (property.Name, NormalizeToken (property.Value));
        }
        return normalized;
    } else if ((array = token as JArray) != null) {
        for (int i = 0; i < array.Count; i ++) {
            array [i] = NormalizeToken (array [i]);
        }
        return array;
    } else {
        return token;
    }
}

