    if (previous == head) 
        previous.Next = null; 

    if (current == null) 
    { 
        head = previous; 
        return head; 
    } 
    else 
    { 
        Node temp = current.next; 
        current.next = previous; 
        reverse(current, temp); 
    } 
    return null; 
}

