private static IEnumerable<int> Approximations(IEnumerable<int> values, int target)
{
    int sum = 0;
    bool first = true;
    foreach (var item in values)
    {
        if (sum + item < target || first)
        {
            first = false;
            sum += item;
        }
        else
        {
            yield return (sum + item - target < target - sum) ? sum + item : sum;
            sum = item;
        }
    }
    if (!first) 
        yield return sum;    
}

