public static string ReplaceHostInUrl(string originalUrl, string newAuthority)
{
    Uri uri = new Uri(originalUrl);
    uri = new Uri(uri.Scheme.ToLowerInvariant(), newAuthority, uri.AbsolutePath, uri.Query, uri.Fragment);
    int port = uri.Port;
    if (port > 0 && port == uri.GetDefaultPort())
    {
        uri = new Uri(uri.Scheme, uri.UserInfo, uri.Host, -1, uri.AbsolutePath, uri.Query, uri.Fragment);
    }

    return uri.ToString();
}

