public static double Sqrt(int n)
{
    double low = 0;
    double high = (double)n;
    double mid = (high - low) / 2;

    while (Math.Abs(mid * mid - n) > 0.000000000001)
    {
        if (mid * mid > (double)n)
        {
            high = mid;
            mid = (high - low) / 2;
        }
        else
        {
            low = mid;
            mid = mid + ((high - low) / 2);
        }
    }
    return mid;
}

