public static bool IsAnagram(string s1, string s2)
{
    if (s1.Length != s2.Length) return false;
    var seen = new int[256];
    s1 = s1.ToLower();
    s2 = s2.ToLower();
    for (int i = 0; i < s1.Length; i++)
    {
        seen[s1[i]] = seen[s1[i]] + 1;
    }
    for (int i = 0; i < s2.Length; i++)
    {
        if (seen[s2[i]] == 0) return false;
        seen[s2[i]] = seen[s2[i]] - 1;
    }
    for (int i = 0; i < 256; i++)
    {
        if (seen[i] != 0) return false;
    }
    return true;
}

public static T [,] To2dArray <T> (this List < List < T > > list) {
    if (list.Count == 0 || list [0].Count == 0)
        throw new ArgumentException ("The list must have non-zero dimensions.");
    var result = new T [list.Count, list [0].Count];
    for (int i = 0; i < list.Count; i ++) {
        if (list [i].Count != list [0].Count)
            throw new InvalidOperationException ("The list cannot contain elements (lists) of different sizes.");
        for (int j = 0; j < list [i].Count; j ++)
            result [j, i] = list [i] [j];
    }
    return result;
}

