public Message WrapB (int b, int millisecondsTimeout) {
    Message returnMessage = null;
    lock (gate)
    {
        while (pendingB != null) {
            Monitor.Wait (gate, 100);
        }
        pendingB = b;
        if (! Monitor.Wait (gate, millisecondsTimeout)) {
            pendingB = null;
            Monitor.Pulse (gate);
            returnMessage = new Message (null, b);
        }
    }
    return returnMessage;
}

