public static String deriveCurveName (PublicKey publicKey)
{
    if (publicKey is jce.interfaces.ECPublicKey)
    {
        var pk = (jce.interfaces.ECPublicKey) publicKey;
        var params = pk.getParams();
        return deriveCurveName (EC5Util.convertSpec (params, false));
    } 
    else if (publicKey is org.bouncycastle.jce.interfaces.ECPublicKey)
    {
        var pk = (org.bouncycastle.jce.interfaces.ECPublicKey) publicKey;
        return deriveCurveName (pk.getParameters());
    }
    else
    {
        throw new ArgumentException ("Can only be used with instances of ECPublicKey (either jce or bc implementation)");
    }
}

private static Bitmap RotateImage (Bitmap bmp, float angle) {
    Bitmap rotatedImage = new Bitmap (bmp.Width, bmp.Height);
    using (Graphics g = Graphics.FromImage (rotatedImage)){
        g.RotateTransform (angle);
        g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
        g.DrawImage (bmp, 0, 0);
    }
    return rotatedImage;
}

public static GraphicsPath Shrink (this GraphicsPath path, float width) {
    using (var p = new GraphicsPath ())
    {
        p.AddPath (path, false);
        p.CloseAllFigures ();
        p.Widen (new Pen (Color.Black, width * 2));
        var position = 0;
        var result = new GraphicsPath ();
        while (position < p.PointCount) {
            position += CountNextFigure (p.PathData, position);
            var figureCount = CountNextFigure (p.PathData, position);
            var points = new PointF [figureCount];
            var types = new byte [figureCount];
            Array.Copy (p.PathPoints, position, points, 0, figureCount);
            Array.Copy (p.PathTypes, position, types, 0, figureCount);
            position += figureCount;
            result.AddPath (new GraphicsPath (points, types), false);
        }
        path.Reset ();
        path.AddPath (result, false);
        return path;
    }}

