bool IsCompletedBy(Keys key) {
    for (var i = 0; i < Keys.Count; i++) {
        if (Keys[i] == key)
            Position = i;
    }
    if (Position == Keys.Count - 1) {
        Position = -1;
        return true;
    }
    return false;
}

public Node Reverse(Node n, Node p) 
{ 
    if (n == null) 
        return null; 

    if (n.Next == null) 
    { 
        n.Next = p; 
        return n; 
    } 
    Node r = Reverse(n.Next, n); 
    n.Next = p; 
    return r; 
}

