public string LongestSequenceOfChar(string str)
{
  string interimResult = "";
  string result = "";
  for(int i = 0; i < str.Length; i++)
  {
    char ch = str[i];
    interimResult += ch;
    for(int j = i + 1; j < str.Length; j++)
    {
      char ch1 = str[j];
      if(ch != ch1)
        break;
      interimResult += ch;
    }
    if(interimResult.Length > result.Length)
      result = interimResult;
    interimResult = "";
  }
  return result;
}

