static string Shuffle(string text) {
    if (text.Length <= 1) return text;
    int split = text.Length / 2;
    string temp1 = Shuffle (text.Substring(0, split));
    string temp2 = Shuffle (text.Substring(split));

    if (Random.Range(0f, 1f) > 0.5f) 
        return temp1 + temp2;
    else 
        return temp2 + temp1;
}

