public static void ThrowException(string className)
{
    try
    {
        Type exceptionClass = Type.GetType(className); 
        if (typeof(CheckedException).IsAssignableFrom(exceptionClass))
        {
            throw exceptionClass.GetConstructor().Invoke(null) as CheckedException;
        }
        else if (typeof(UncheckedException).IsAssignableFrom(exceptionClass))
        {
            throw exceptionClass.GetConstructor(null).Invoke(null) as UncheckedException;
        }
        else
        {
            throw new ArgumentException("Not a valid exception type: " + exceptionClass.FullName);
        }
    }
    catch (Exception e)
    {
        throw new InvalidOperationException(e.Message, e);
    }
}

