    if (m.Msg == 0x0084)
    {
        Point pos = new Point(m.LParam.ToInt32() & 0xffff, m.LParam.ToInt32() >> 16);
        if (pos.X >= this.ClientSize.Width - 10 && pos.Y >= this.ClientSize.Height - 10)
        {
