public Node reverse(Node previous, Node current)
{
    if (previous == null) return null;
    if (previous.equals(head)) previous.Next = null;
    if (current == null)
    {
        head = previous;
        return head;
    }
    else
    {
        Node temp = current.Next;
        current.Next = previous;
        reverse(current, temp);
    }
    return null;
}

