public static void FindGoodFont (Graphics Graf, string sStringToFit, Size TextRoomAvail, ref Font FontToUse, GraphicsUnit FontUnit) {
    SizeF RealSize = Graf.MeasureString (sStringToFit, FontToUse);
    Debug.WriteLine ("big string is {0}, orig size = {1},{2}", sStringToFit, RealSize.Width, RealSize.Height);
    if (RealSize.Width < TextRoomAvail.Width && RealSize.Height < TextRoomAvail.Height) {
        Debug.WriteLine ("The space is big enough already");
        return;
    }
    float heightScale = TextRoomAvail.Height / RealSize.Height;
    float widthScale = TextRoomAvail.Width / RealSize.Width;
    float scale = (heightScale < widthScale) ? heightScale : widthScale;
    float newFontSize = FontToUse.Size * scale;
    Debug.WriteLine ("Resizing with scales {0},{1} chose {2}", heightScale, widthScale, scale);
    Debug.WriteLine ("Old font size was {0}, new={1} ", FontToUse.Size, newFontSize);
    FontStyle oldFontStyle = FontToUse.Style;
    FontToUse.Dispose();
    FontToUse = new Font (FontToUse.FontFamily, newFontSize, oldFontStyle, FontUnit);
}

