public static string ToJavaMethodName(string nonJavaMethodName)
{
    StringBuilder nameBuilder = new StringBuilder();
    bool capitalizeNextChar = false;
    bool first = true;
    for (int i = 0; i < nonJavaMethodName.Length; i++)
    {
        char c = nonJavaMethodName[i];
        if (!Char.IsLetterOrDigit(c))
        {
            if (!first)
            {
                capitalizeNextChar = true;
            }
        }
        else
        {
            nameBuilder.Append(capitalizeNextChar ? Char.ToUpper(c) : Char.ToLower(c));
            capitalizeNextChar = false;
            first = false;
        }
    }

    return nameBuilder.ToString();
}

