public override bool Equals (float a, float b) {
    if (a == b) {
        return true;
    } else if (Math.Abs (a) == 0 || Math.Abs (b) == 0 || Math.Abs (a - b) < InternalEpsilon) {
        return Math.Abs (a - b) < InternalEpsilon;
    } else {
        return Math.Abs (a - b) / (Math.Abs (a) + Math.Abs (b)) < InternalEpsilon;
    }
    return true;
}

