static void ResourceKeyChanged (DependencyObject d, DependencyPropertyChangedEventArgs e) {
    var target = d as FrameworkElement;
    if (target == null)
        return;
    var newVal = e.NewValue as ResourceKey;
    if (newVal != null) {
        target.SetResourceReference (e.Property, newVal);
        return;
