        foreach (Char c in codeToExecute.ToCharArray ()) {
            if (Char.IsWhiteSpace (c) || Char.IsControl (c)) {
                if (parenAndBracketCount == 0) {
                    continue;
                }
            }
            if (c == '.') {
                if (buffer.Length > 0 && parenAndBracketCount == 0) {
                    items.Add (buffer);
                    buffer = "";
                } else {
                    buffer += c;
                }
            } else if (c == '[') {
                parenAndBracketCount ++;
                if (buffer.Length > 0) {
                    items.Add (buffer);
                }
                buffer = c.ToString ();
            } else if (c == ']' || c == ')') {
                parenAndBracketCount --;
                buffer += c;
                if (buffer.Length > 0) {
                    items.Add (buffer);
                    buffer = "";
                }
            } else if (c == '(') {
                parenAndBracketCount ++;
                buffer += c;
            } else {
                buffer += c;
            }
        }
        if (buffer.Length > 0) {
            items.Add (buffer);
        }
        return items.ToArray ();
}

