public static void DrawNormalizedAudio (ref float [] data, PictureBox pb, Color color) {
    StoppedBitmap bmp;
    if (pb.Image == null) {
        bmp = new StoppedBitmap (pb.Width, pb.Height);
    } else {
        bmp = (StoppedBitmap) pb.Image;
    }
    int BORDER_SIZE = 5;
    int width = bmp.Width - (2 * BORDER_SIZE);
    int height = bmp.Height - (2 * BORDER_SIZE);
    using (Graphics g = Graphics.FromImage (bmp))
    {
        g.Clear (Color.Black);
        Pen pen = new Pen (color);
        int size = data.Length;
        for (int iPixel = 0; iPixel < width; iPixel ++) {
            int start = (int) ((float) iPixel * ((float) size / (float) width));
            int end = (int) ((float) (iPixel + 1) * ((float) size / (float) width));
            float min = float.MaxValue;
            float max = float.MinValue;
            for (int i = start; i < end; i ++) {
                float val = data [i];
                min = Math.Min(min, val);
                max = Math.Max(max, val);
            }
            int yMax = BORDER_SIZE + height - (int) ((max + 1) *.5 * height);
            int yMin = BORDER_SIZE + height - (int) ((min + 1) *.5 * height);
            g.DrawLine (pen, iPixel + BORDER_SIZE, yMax, iPixel + BORDER_SIZE, yMin);
        }
    } pb.Image = bmp;
}

public void ReadXml (System.Xml.XmlReader reader) {
    int count = 0;
    XmlSerializer keySerializer = new XmlSerializer (typeof (TKey));
    XmlSerializer valueSerializer = new XmlSerializer (typeof (TValue));
    bool wasEmpty = reader.IsEmptyElement;
    reader.Read ();
    if (wasEmpty) {
        return;
    }
    while (reader.NodeType != System.Xml.XmlNodeType.EndElement) {
        reader.ReadStartElement ("item");
        reader.ReadStartElement ("key");
        TKey key = (TKey) keySerializer.Deserialize (reader);
        reader.ReadEndElement ();
        reader.ReadStartElement ("value");
        TValue value = (TValue) valueSerializer.Deserialize (reader);
        reader.ReadEndElement ();
        bool isValid = false;
        if(key.GetType() == typeof(string)) {
            if(!string.IsNullOrEmpty((string)key)) {
                isValid = true;
            }
        } else {
            isValid = true;
        }
        if(isValid) {
            this.Add (key, value);
            count++;
        }
        reader.ReadEndElement ();
        reader.MoveToContent ();
    }
    reader.ReadEndElement ();
}

private static bool AlreadyRunning () {
