private static int ParseNybble (char c) {
    int val;
    if (c >= '0' && c <= '9') {
        val = c - '0';
    }
    else if (c >= 'A' && c <= 'F') {
        val = c - 'A' + 10;
    }
    else if (c >= 'a' && c <= 'f') {
        val = c - 'a' + 10;
    }
    else
    {
        throw new ArgumentOutOfRangeException ("Invalid hex digit: " + c);
    }
    return val;
}

