private static int Encode (int value, byte [] buffer, int index) {
        byte temp;
        bool leading = true;
        for (int i = 0; i < 4; i++)
        {
            int shiftAmount = (3 - i) * 8;
            temp = (byte)((value >> shiftAmount) & 0xFF);
            if (temp > 0 || leading == false) {
                buffer [index ++] = temp;
                leading = false;
            } 
        } 
        return index;
}

