public string[][] AllUniqueCombinations()
{
    int n = dataStructure.Keys.Count;
    int solutions = 1;
    foreach(List<string> vector in dataStructure.Values)
    {
        solutions *= vector.Count;
    }
    string[][] allCombinations = new string[solutions + 1][];
    allCombinations[0] = dataStructure.Keys.ToArray();
    for (int i = 0; i < solutions; i++)
    {
        List<string> combination = new List<string>(n);
        int j = 1;
        foreach (List<string> vec in dataStructure.Values)
        {
            combination.Add(vec[(i / j) % vec.Count]);
            j *= vec.Count;
        }
        allCombinations[i + 1] = combination.ToArray();
    }
    return allCombinations;
}

