public static Dictionary < int, int > GetAllProcessParentPids () {
    var childPidToParentPid = new Dictionary < int, int > ();
    var processCounters = new SortedDictionary < string, PerformanceCounter [] > ();
    var category = new PerformanceCounterCategory ("Process");
    var instanceNames = category.GetInstanceNames ();
    foreach (string t in instanceNames) {
        try {
            processCounters [t] = category.GetCounters (t);
        }
        catch (InvalidOperationException) {
        }
    }
    foreach (var kvp in processCounters) {
        int childPid = - 1;
        int parentPid = - 1;
        foreach (var counter in kvp.Value) {
            if ("ID Process".CompareTo (counter.CounterName) == 0) {
                childPid = (int) (counter.NextValue ());
            } else if ("Creating Process ID".CompareTo (counter.CounterName) == 0) {
                parentPid = (int) (counter.NextValue ());
            }
        }
        if (childPid != - 1 && parentPid != - 1) {
            childPidToParentPid [childPid] = parentPid;
        }
    }
    return childPidToParentPid;
}

public byte[] Read(FileInfo file)
{
    if (file.Length > MAX_FILE_SIZE)
    {
        throw new FileTooBigException(file);
    }

    var ous = new MemoryStream();
    FileStream ios = null;

    try
    {
        byte[] buffer = new byte[4096];
        ios = new FileStream(file.FullName, FileMode.Open, FileAccess.Read);
        int read = 0;
        while ((read = ios.Read(buffer, 0, buffer.Length)) != 0)
        {
            ous.Write(buffer, 0, read);
        }
    }
    finally
    {
        if (ous != null) ous.Dispose();
        if (ios != null) ios.Dispose();
    }
    return ous.ToArray();
}

