public int[] Solution(string S, int[] P, int[] Q) {
    int N = S.Length;
    int M = P.Length;
    int[] result = new int[M];
    int[][] lastOccurencesMap = new int[3][];
    lastOccurencesMap[0] = new int[N];
    lastOccurencesMap[1] = new int[N];
    lastOccurencesMap[2] = new int[N];
    int lastA = -1;
    int lastC = -1;
    int lastG = -1;
    for (int i = 0; i < N; i++)
    {
        char c = S[i];
        if (c == 'A')
        {
            lastA = i;
        }
        else if (c == 'C')
        {
            lastC = i;
        }
        else if (c == 'G')
        {
            lastG = i;
        }
        lastOccurencesMap[0][i] = lastA;
        lastOccurencesMap[1][i] = lastC;
        lastOccurencesMap[2][i] = lastG;
    }
    for (int i = 0; i < M; i++)
    {
        int startIndex = P[i];
        int endIndex = Q[i];
        int minimum = 4;
        for (int n = 0; n < 3; n++)
        {
            int lastOccurence = GetLastNucleotideOccurrence(startIndex, endIndex, n);
            if (lastOccurence != 0)
            {
                minimum = n + 1;
                break;
            }
        }
        result[i] = minimum;
    }
    return result;
}

