private static DateTime NthOf (DateTime CurDate, int Occurrence, DayOfWeek Day) {
    var fday = new DateTime (CurDate.Year, CurDate.Month, 1);
    if (Occurrence == 1) {
        for (int i = 0; i < 7; i ++) {
            if (fday.DayOfWeek == Day) {
                break;
            } else {
                fday.AddDays (1);
            }
        }
    } else {
        var fOc = fday.DayOfWeek == Day ? fday : fday.AddDays (Day - fday.DayOfWeek);
        if (fOc.Month < CurDate.Month)
            Occurrence += 1;
        fday = fOc.AddDays (7 * (Occurrence - 1));
    }
    return fday;
}

private static void DownloadRemoteImageFile(string uri, string fileName) 
{
    HttpWebRequest request = HttpWebRequest.Create(uri) as HttpWebRequest;
    HttpWebResponse response = (HttpWebResponse) request.GetResponse();
    if(response.StatusCode == HttpStatusCode.OK || response.StatusCode == HttpStatusCode.Moved || response.StatusCode == HttpStatusCode.Redirect && response.ContentType.StartsWith("image", StringComparison.OrdinalIgnoreCase))
    {
        using(Stream responseStream =response.GetResponseStream())
        using(FileStream fileStream = File.Create(fileName))
        {
            byte[] buffer = new byte[4096];
            int bytesRead;
            do
            {
                bytesRead = responseStream.Read(buffer, 0, buffer.Length);
                fileStream.Write(buffer, 0, bytesRead);
            } while (bytesRead != 0);
        }
    }
}

static Result Play (Input userInput) {
    Input computer = Input.Scissors;
    bool paper = (userInput == Input.Paper),
        rock = (userInput == Input.Rock),
