static void doubleNumber (int [] n) {
    int carry = 0;
    for (int i = n.Length - 1; i > 0; i --) {
        n [i] <<= 1;
        n [i] += carry;
        if (n [i] >= 1000000000) {
            carry = 1;
            n [i] -= 1000000000;
        } else {
            carry = 0;
        }
    }
}

