	double norm = 1.0 / (1.0 + (k / Q) + (k * k));
	A0 = (k / Q) * norm;
	A1 = 0.0;
	A2 = -A0;
	B2 = ((1.0 - (k / Q)) + (k * k)) * norm;
	B1 = (2.0 * ((k * k) - 1.0)) * norm;
}

