public static IEnumerable < T > TakeLast < T > (this IEnumerable < T > input, int count) {
    if (count <= 0)
        yield break;
    var inputList = input as IList < T >;
    if (inputList != null) {
        int last = inputList.Count;
        int index = last - count;
        if (index < 0)
            index = 0;
        while (index != last) {
            yield return inputList [index];
            index ++;
        }
    } else {
        T [] buffer = new T [count];
        int index = 0;
        int listIndex = 0;
        foreach (T item in input) {
            if (listIndex >= count)
                buffer [index] = item;
            listIndex ++;
            index = (index + 1) % count;
        }
        if (listIndex < count)
            index = 0;
        else
            listIndex = count;
        while (listIndex > 0) {
            yield return buffer [index];
            index = (index + 1) % count;
            listIndex --;
        }
    }
}

