public override int Read (byte [] buffer, int offset, int count) {
    if (streams.Count == 0)
        return 0;
    int bytesRead = 0;
    while (bytesRead < count) {
        if(streams.Peek ().CanRead)
            bytesRead += streams.Peek ().Read (buffer, offset+bytesRead, count-bytesRead);
        if (bytesRead == 0) {
            streams.Dequeue ().Dispose ();
        } else {
            break;
        }
    }
    return bytesRead;
}

