private static bool AlreadyRunning () {
    Process [] processes = Process.GetProcesses ();
    List <Process> matchingProcesses = new List <Process> ();
    Process currentProc = Process.GetCurrentProcess ();
    logger.LogDebug ("Current proccess: {0}", currentProc.ProcessName);
    foreach (Process process in processes) {
        if (currentProc.ProcessName == process.ProcessName) {
            matchingProcesses.Add (process);
        }
    }
    if (matchingProcesses.Count > 1) {
        foreach (Process process in matchingProcesses) {
            if (currentProc.Id != process.Id) {
                logger.LogInformation ("Another instance of this process is already running: {pid}", process.Id);
                return true;
            }
        }
    }
    return false;
}

public static string Rainbow(int numOfSteps, int step)
    {
                double red = 0.0;
                double green = 0.0;
                double blue = 0.0;
                double hue = (double)step / (double)numOfSteps;
                int index = (int)(hue * 6);
                double fraction = hue * 6.0 - index;
                double difference = 1.0 - fraction;
                switch (index % 6)
                {
                    case 0:
                        {
                            red = 1.0;
                            green = fraction;
                            blue = 0.0;
                            break;
                        }
                    case 1:
                        {
                            red = difference;
                            green = 1.0;
                            blue = 0.0;
                            break;
                        }
                    case 2:
                        {
                            red = 0.0;
                            green = 1.0;
                            blue = fraction;
                            break;
                        }
                    case 3:
                        {
                            red = 0.0;
                            green = difference;
                            blue = 1.0;
                            break;
                        }
                    case 4:
                        {
                            red = fraction;
                            green = 0.0;
                            blue = 1.0;
                            break;
                        }
                    case 5:
                        {
                            red = 1.0;
                            green = 0.0;
                            blue = difference;
                            break;
                        }
                }
                return "#" + ((int)(red * 255)).ToString("X2") + ((int)(green * 255)).ToString("X2") + ((int)(blue * 255)).ToString("X2");
}

