private static IEnumerable<IEnumerable<T>> ClumpIterator4<T>(IEnumerable<T> source, int size) {
    Debug.Assert (source != null, "source is null.");
    List<T> items = new List<T>();
    int count = 0;
    foreach (var item in source) {
        count ++;
        items.Add(item);
        if (count == size) {
            yield return items;
            items = new List<T>();
            count = 0;
        }
    }
    if (count > 0) {
        if (count == size)
            yield return items;
        else {
            var tempItems = items.Take(count).ToList();
            yield return tempItems;
        }
    }
}

public override void Write (char value) {
    if (value == '&') {
        if (_bufferState == 0) {
            _bufferState ++;
            return;
        } else {
            _bufferState = 0;
        }
    } else if (value == ';') {
        if (_bufferState > 1) {
            _bufferState ++;
            return;
        } else {
            Write ('&');
            Write (AmpToken);
            _bufferState = 0;
        }
    } else if (value == '\n') {
        base.Write ("&#10;");
        return;
    }
    base.Write (value);
}

