                float r = 0.0f;
                float g = 0.0f;
                float b = 0.0f;
                float h = (float)step / (float)numOfSteps;
                int i = (int)(h * 6);
                float f = h * 6.0f - i;
                float q = 1.0f - f;
                switch (i % 6)
                {
                    case 0:
                        {
                            r = 1.0f;
                            g = f;
                            b = 0.0f;
                            break;
                        }
                    case 1:
                        {
                            r = q;
