public override object ReadJson (JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer) {
    JToken token = JToken.Load (reader);
    if (token.Type == JTokenType.Float || token.Type == JTokenType.Integer) {
        return token.ToObject < double > ();
    }
    if (token.Type == JTokenType.String) {
        return double.Parse (token.ToString (), System.Globalization.CultureInfo.GetCultureInfo ("es-ES"));
    }
    if (token.Type == JTokenType.Null && objectType == typeof (double ?)) {
        return null;
    }
    throw new JsonSerializationException ("Unexpected token type: " + token.Type.ToString ());
}

public static void MoveRight (this TreeNode node) {
  TreeNode parent = node.Parent;
  TreeView view = node.TreeView;
  if (parent != null) {
      int index = parent.Nodes.IndexOf (node);
      if (index > 0) {
          TreeNode leftSibling = parent.Nodes[index - 1]; 
          parent.Nodes.RemoveAt (index);
          leftSibling.Nodes.Add(node);
      }
  } else if (node.TreeView.Nodes.Contains (node)) {
      int index = view.Nodes.IndexOf (node);
      if (index > 0) {
          TreeNode leftSibling = view.Nodes[index - 1]; 
          view.Nodes.RemoveAt (index);
          leftSibling.Nodes.Add(node);
      }
  }
}

public static string Join(string separator, params string[] values)
{
    if (values.Length == 0)
        return "";

    var sep = separator.ToCharArray();
    var totalSize = (values.Length - 1) * sep.Length;
    for (int i = 0; i < values.Length; i++)
    {
        if (values[i] == null)
            values[i] = "";
        else
            totalSize += values[i].Length;
    }

    var joined = new char[totalSize];
    var pos = 0;
    for (int i = 0, end = values.Length - 1; i < end; i++)
    {
        var val = values[i].ToCharArray();
        val.CopyTo(joined, pos);
        pos += val.Length;
        sep.CopyTo(joined, pos);
        pos += sep.Length;
    }
    values[values.Length - 1].ToCharArray().CopyTo(joined, pos);

    return new string(joined);

}

