public void DispatchEvent (Event event) {
    if (event == null) {
        throw new ArgumentNullException("Event cannot be null");
    }

    CancellableEvent cancellableEvent = null;
    bool cancellable = false;
    if (event is CancellableEvent) {
        cancellableEvent = (CancellableEvent)event;
        if (!cancellableEvent.IsCancelled()) {
            throw new ArgumentException("Event must have been cancelled prior to dispatching");
        }
    }

    FireEvents(false, event, cancellableEvent, cancellable);
    FireEvents(true, event, cancellableEvent, cancellable);
}

