public int solution(int N) {
    int result = 0;
    int temp;
    while (N > 0) {
        temp = 0;
        N >>= 1;
        while ((N & 1) == 0 && N > 0) {
            temp ++;
            N >>= 1;
        }
        result = Math.max(result, temp);
    }
    return result;
}

