int computeHeight () {
    int maxHeight = 0;
    int [] levels = new int [parent.length];
    for (int vertex = 0;
    vertex < n; vertex ++) {
        if (levels [vertex] != 0) continue;
        int height = 0;
        for (int i = vertex;
        i != - 1; i = parent [i]) {
            if (levels [i] != 0) {
                height += levels [i];
                break;
            }
            height ++;
        }
        maxHeight = Math.max (maxHeight, height);
        for (int i = vertex;
        i != - 1; i = parent [i]) {
            if (levels [i] != 0) break;
            levels [i] = height --;
        }
    }
    return maxHeight;
}

