public boolean haveThree(int[] nums) {
    int count = 0;
    boolean flag = false;
    for (int i : nums) {
        if (i == 3 && !flag) {
            count++;
            flag = true;
        } else if (i == 3) {
            return false;
        }
        if (i != 3) {
            flag = false;
        }
    }
    return count == 3;
}

