public int solution (int X, int [] A) {
    int list [] = A;
    int sum = 0; 
    int searchedValue = X; 
    int sumV = searchedValue * (searchedValue + 1) / 2; 
    List < Integer > arrayList = new ArrayList < Integer > (); 
    for (int iii = 0; iii < list.length; iii ++) { 
        if (list [iii] <= searchedValue && ! arrayList.contains (list [iii])) {
            sum += list [iii]; 
            if (sum == sumV) {
                return iii; 
            }
            arrayList.add (list [iii]); 
        } 
    } 
    return -1; 
}

public int solution (int X, int [] A) {
    int len = A.length;
    if (X > len) {
        return - 1;
    }
    int jumped = 0;
    short isFilled [] = new short [X];
    for(int i=0; i<X; i++) isFilled[i] = 0;
    for (int i = 0;
    i < len; i ++) {
        int x = A [i];
        if (x <= X) {
            if (isFilled [x - 1]==0) {
                isFilled [x - 1] = 1;
                jumped += 1;
                if (jumped == X) {
                    return i;
                }
            }
        }
    }
    return - 1;
}

