public static int solution(Integer number) {
    int gapLength = 0;
    int maxGap = 0;
    boolean foundOne = false;
    int n = number;
    while (n > 0) {
        if (n % 2 == 0) {
            if (foundOne) {
                gapLength++;
            }
        } else {
            foundOne = true;
            if (gapLength != 0) {
                maxGap = Math.max(maxGap, gapLength);
                gapLength = 0;
            }
        }
        n /= 2;
    }
    return maxGap;
}

