        throw new FileTooBigException (file);
    } 
    InputStream bfi = new BufferedInputStream(new FileInputStream(file));
    ByteArrayOutputStream ous = null;
    try {   
        ous = new ByteArrayOutputStream ();
        int read = 0;
        while ((read = bfi.read ()) != -1) {
            ous.write (read);
        }
    } finally {
        try {
            if (ous != null) ous.close ();
        } catch (IOException e) {
        }
        try {
            if (bfi != null) bfi.close ();
        } catch (IOException e) {
        }
    }
    return ous.toByteArray ();
}

public static String interleave (String you, String me) {
    char [] a = you.toCharArray ();
    char [] b = me.toCharArray ();
    StringBuilder out = new StringBuilder ();
    for (int i = 0, maxLength = Math.max (a.length, b.length); i < maxLength; ++i) {
        if (i < a.length) out.append (a [i]);
        if (i < b.length) out.append (b [i]);
    }
    return out.toString ();
}

