public int[] solution(String S, int[] P, int[] Q) { 
int N = S.length();
    int M = P.length;
    int[] result = new int[M];
    int[][] lastOccurrencesMap = new int[3][N];
    int lastA = -1;
    int lastC = -1;
    int lastG = -1;
    for (int i = 0; i < N; i++) { 
        char c = S.charAt(i);
        if (c == 'A') {
            lastA = i;
        } else if (c == 'C') {
            lastC = i;
        } else if (c == 'G') {
            lastG = i;
        }
        lastOccurrencesMap[0][i] = lastA;
        lastOccurrencesMap[1][i] = lastC;
        lastOccurrencesMap[2][i] = lastG;
    }
	for (int i = 0; i < M; i++) { 
        int startIndex = P[i];
        int endIndex = Q[i];
        int minimum = 4;
        int[] lastOccurrencesList = {lastOccurrencesMap[0][endIndex],lastOccurrencesMap[1][endIndex],lastOccurrencesMap[2][endIndex]};
		int min = 4;
		for (int n = 0; n < 3; n++){
			int lastOccurence = lastOccurrencesList[n];
			if (lastOccurence >= startIndex && lastOccurence <= endIndex && n + 1 < min){
				min = n + 1;
			}
		}
        result[i] = min;
    }
    return result;
 }

