public int solution (int X, int [] A) {
    int len = A.length;
    if (X > len) {
        return - 1;
    }
    int jumped = 0;
    char isFilled [] = new char [X];
    for(int i=0; i<X; i++) isFilled[i] = 0;
    for (int i = 0;
    i < len; i ++) {
        int x = A [i];
        if (x <= X) {
            if (isFilled [x - 1]==0) {
                isFilled [x - 1] = 1;
                jumped += 1;
                if (jumped == X) {
                    return i;
                }
            }
        }
    }
    return - 1;
}

private byte [] readData (String path, int startByte, int chunkSize) throws Exception {
    FileChannel fc = new RandomAccessFile(new File(path), "r").getChannel();
    ByteBuffer buff = ByteBuffer.allocate(chunkSize);
    fc.position(startByte);
    int readSize = fc.read(buff);
    fc.close();
    if (readSize == chunkSize) {
        buff.flip();
        return buff.array();
    }
    else {
        buff.limit(readSize);
        byte[] data = new byte[readSize];
        buff.get(data);
        return data;
    } 
}

