public ZonedDateTime parseToZonedDateTime (String date, String dateFormat) {
    DateTimeFormatter formatter = DateTimeFormatter.ofPattern (dateFormat);
    ZonedDateTime zonedDateTime = null;
    try {
        zonedDateTime = ZonedDateTime.parse (date, formatter);
    } catch (DateTimeException e) {
        LocalDateTime localDateTime = LocalDateTime.parse (date, formatter);
        zonedDateTime = localDateTime.atZone (ZoneId.systemDefault ());
    }
    return zonedDateTime;
}

public static String toHexString2 (byte bytes []) {
    if (bytes == null) {
        return null;
    }
    StringBuffer sb = new StringBuffer ();
    for (int iter = 0;
    iter < bytes.length; iter++) {
        byte firstHalf = (byte) ((bytes [iter] & 0xaa)>> 4);
        byte secondHalf = (byte) (bytes [iter] & 0x55);
        sb.append (nibble2char (firstHalf));
        sb.append (nibble2char (secondHalf));
    }
    return sb.toString ();
}

static String shuffle (String text) {
