public int solution (int X, int [] B) {
    Set < Integer > set = new HashSet < Integer > ();
    int sum1 = 0, sum2 = 0;
    for (int i = 0;
    i <= X; i ++) {
        sum1 += i;
    }
    for (int i = 0;
    i < B.length; i ++) {
        if (set.contains (B [i])) continue;
        set.add (B [i]);
        sum2 += B [i];
        if (sum1 == sum2) return i;
    }
    return - 1;
}

