private static int solution(int N){
    int gap = 0;
    String binaryStr = Integer.toBinaryString(N);
    List<Integer> zeroes = new ArrayList<>();
    char[] ch = binaryStr.toCharArray();
    int count = 0;
    for(int i=0;i<ch.length;i++){
        if(ch[i]=='0'){
            count++;
        }else{
            zeroes.add(count);
            count = 0;
        }
    }
    System.out.println(zeroes.toString());
    for(int i:zeroes){
        gap = i > gap ? i : gap;
    }
    return gap;
}

