    int sumV = (X * (X + 1)) / 2;
    int sum = 0;
    for (int i=0; i<A.length; i++) {
        if (A[i] <= X && check[A[i]] == 0) {
            check[A[i]] = 1;
            sum += A[i];
        if (sum == sumV) {
           return i;
    }  } }
    return -1;
}

