}

public static int binarySearch(int[] array, int first, int last, int value) {
    if (first <= last) {
        while (first <= last) {
            int mid = first + (last - first) / 2;
            if (array[mid] == value)
                return mid;
            if (array[mid] < value)
                first = mid + 1;
            else
                last = mid - 1;
        }
    }
    return -1;
}

