private static int raise (int x, int n) {
    if (n == 0) return 1;
    if (n == 1) return x;
    if (n < 0) {
        if (x == 1 || (x == 2 && n == - 1)) return 1;
        else return 0;
    }
    if ((n & 1) == 0) {
        long result = raise (x * x, n / 2);
        if (result > Integer.MAX_VALUE) return Integer.MAX_VALUE;
        return (int) result;
    } else {
        long result = x * raise (x * x, n / 2);
        if (result > Integer.MAX_VALUE) return Integer.MAX_VALUE;
        return (int) result;
    }
}

