private static String join(String delimiter, String...parts) {
    StringBuilder builder = new StringBuilder ();
    java.util.Arrays.asList(parts)
            .stream()
            .filter(part -> !part.isEmpty())
            .reduce((a, b) -> a + delimiter + b)
            .ifPresent(builder::append);
