public int solution (int N) {
    String binaryNum = Integer.toString (N, 2);
    int largestGap = 0;
    int gap = 0;
    for (int i = 0; i < binaryNum.length (); i ++) {
        if (binaryNum.charAt (i) == '0') {
            gap ++;
            if (gap > largestGap) {
                largestGap = gap;
            }
        } else {
            gap = 0;
        }
    }
    return largestGap;
}

