public static String join (String delimiter, List <String> inStr) {
    StringBuilder sb = new StringBuilder ();
    Iterator <String> it = inStr.iterator ();
    if (it.hasNext ()) {
        sb.append (it.next ());
        while (it.hasNext ()) {
