public void draw (Graphics2D g) {
    float arrowRatio = 0.5f;
    float arrowLength = 80.0f;
    BasicStroke stroke = (BasicStroke) g.getStroke ();
    float endX = 350.0f;
    float veeX = endX - stroke.getLineWidth () * 0.5f / arrowRatio;
    Path2D.Float path = new Path2D.Float ();
    float waisting = 0.5f;
    float waistX = endX - arrowLength * 0.5f;
    float waistY = arrowRatio * arrowLength * 0.5f * waisting;
    float arrowWidth = arrowRatio * arrowLength;
    path.moveTo (veeX - arrowLength * 0.75f, - arrowWidth);
    path.quadTo (waistX, - waistY, endX, 0.0f);
    path.quadTo (waistX, waistY, veeX - arrowLength * 0.75f, arrowWidth);
    path.lineTo (veeX - arrowLength, 0.0f);
    path.lineTo (veeX - arrowLength * 0.75f, - arrowWidth);
    g.setColor (Color.BLUE);
    g.fill (path);
    g.setColor (Color.RED);
    g.draw (new Line2D.Float (50.0f, 0.0f, veeX - arrowLength * 0.5f, 0.0f));
}

public static void pack (String sourceDirPath, String zipFilePath) throws IOException {
        try (ZipOutputStream zs = new ZipOutputStream (new FileOutputStream (zipFilePath))) {
            File directory = new File (sourceDirPath);
            for (File file : directory.listFiles ()) {
                if (file.isFile ()) {
                    ZipEntry zipEntry = new ZipEntry (file.getName ());
                    zs.putNextEntry (zipEntry);
                    try (FileInputStream inputStream = new FileInputStream (file)) {
                        byte[] b = new byte[1024];
                        int count;
                        while ((count = inputStream.read (b)) > 0) {
                            zs.write (b, 0, count);
                        }
                        zs.closeEntry ();
                        inputStream.close ();
                    }
                }
            }
        }
}

