public static int singleNumber (int [] nums) {
    int answer = 0;
    TreeSet<Integer> ts = new TreeSet<>();
    for (int i = 0; i < nums.length; i ++) {
        ts.add (nums [i]);
    }
    for (int i = 0; i < nums.length; i ++) {
        int test = nums [i];
