public int solution (int X, int [] A) {
    int len = A.length;
    int[] isFilled = new int[len];
    if (X > len) {
        return -1;
    }
    int jumped = 0;
    for (int i = 0; i < len; i++) {
        int x = A[i];
        if (x > X) {
          continue;
        }
        if (isFilled[x - 1] == 0) {
            isFilled[x - 1] = 1;
            jumped += 1;
            if (jumped == X) {
                return i;
            }
        }
    }
    return -1;
}

public int solution (int N) {
    String binary = Integer.toString (N, 2);
    int largestGap = 0;
    int gap = 0;
    for (int i = 1; i < binary.length (); i ++) {
        if (binary.charAt (i) == '0') {
            gap ++;
        }
        if (gap > largestGap && i < binary.length ()) {
            largestGap = gap;
        }
        gap = 0;
    }
    return largestGap;
}

