public static int [] removeDuplicates (int [] arr) {
    int end = arr.length;
    for (int i = 0;
    i < end; i ++) {
        int c = arr[i];
        int j = i + 1;
        while (j < end) {
            if (c == arr [j]) {
                arr [j] = arr [end - 1];
                end --;
            }
            else {
                j++;
            }
        }
    }
    int [] whitelist = new int [end];
    System.arraycopy (arr, 0, whitelist, 0, end);
    return whitelist;
}

