public static boolean hasLoop (Node root) {
    if (root == null) return false;
    Node slow = root, fast = root.next;
    while (fast != null && fast.next != null) {
        if (slow == fast) return true;
        slow = slow.next;
        fast = fast.next.next;
    }
    return false;
}

