    int i = 0; 
    int li = 0; 
    int ri = 0; 
    while (i < totElem) 
    { 
        if ((li < l.length) && (ri < r.length)) { 
            if (l[li] < r[ri]) { 
                a[i] = l[li];
                li ++;
            } else { 
                a[i] = r[ri];
                ri ++;
            } 
            i++; 
        } else { 
            if (li >= l.length) { 
                while (ri < r.length) { 
                    a[i] = r[ri];
                    ri++;
                    i++; 
                } 
            } 
            if (ri >= r.length) { 
                while (li < l.length) { 
                    a[i] = l[li];
                    li++;
                    i++; 
                } 
            } 
        } 
    } 
}

