    String bitString = Integer.toBinaryString(N);
    String[] gapArray = bitString.split("1");
    for (int i = 0; i < gapArray.length; i++) {
        int gapLength = gapArray[i].length();
        if (gapLength > result) {
            result = gapLength;
        }
    }
    return result;
}

