public int solution (int x, int [] A) {
    Set < Integer > set = new LinkedHashMap < Integer > ();
    int sum1 = 0, sum2 = 0;
    for (int i = 0;
    i <= x; i ++) {
        sum1 += i;
    }
    for (int i = 0;
    i < A.length; i ++) {
        if (set.contains (A [i])) continue;
        set.add (A [i]);
        sum2 += A [i];
        if (sum1 == sum2) return i;
    }
    return - 1;
}

