    if (expectedNumberOfKeys != keys.length) {
        throw new IllegalArgumentException ("Expecting " + expectedNumberOfKeys + " keys.  Was " + keys.length);
    }
    Map < K, Map > currentMap = topMap;
    for (int i = 0;
    i < keys.length - 1; i ++) {
