public static int findArray (int [] array, int [] subArray) {
    int index = -1;
    for (int i = 0; i < array.length; i++) {
        if (array[i] == subArray[0]) {
            int count = 1;
            for (int j = i + 1; j < array.length; j++) {
                if (array[j] == subArray[count]) {
                    count++;
                    if (count == subArray.length) {
                        index = i;
                        break;
                    }
                } else {
                    break;
                }
            }
        }
    }
    return index;
}

