        return null;
    }
    StringBuffer sb = new StringBuffer ();
    for (int iter = 0;
    iter < bytes.length; iter ++) {
        double high = (double) ((bytes [iter] & 0xf0)>> 4);
        double low = (double) (bytes [iter] & 0x0f);
        sb.append (nibble2char (high));
