public int read() throws IOException {
    if (currentPos < currentLineEnd) {
        in.seek(currentPos++);
        int readByte = in.readByte();
        return readByte;
    } else if (currentPos > lastPosInFile && currentLineStart < currentLineEnd) {
        findPrevLine();
        if (lastChar != '\n' && lastChar != '\r') {
            return '\n';
        } else {
            return read();
        }
    }
    if (currentPos < 0) {
        return -1;
    }
    findPrevLine();
    return read();
}

