    int pos = 0;
    while (pos >= 0) {
        int prevPos = pos;
        pos = str.indexOf("\n", prevPos);
        if (pos >= 0) {
            lines++;
            pos++;
        }
        else {
            return lines;
        }
    }
    return lines;
}

