static String transpose (String s, int rows, int columns) {
    int n = s.length ();
    if (rows * columns != n) throw new IllegalArgumentException ();
    StringBuilder sb = new StringBuilder (); 
    int j; 
    for (int i = 0; i < n - 1; i ++){ 
        j = i*columns;
        if (j >= n) j -= (n-1); 
        sb.append (s.charAt (j)); 
    }
    sb.append (s.charAt (n - 1)); 
    return sb.toString ();
}

public static boolean contains(String a, String b) {
    Map<Character, Integer> mapA = new HashMap<>();
    for(int i=0; i<a.length(); i++) {
        char currChar = a.charAt(i);
        if (!mapA.containsKey(currChar))
            mapA.put(currChar, 1);
        else 
            mapA.put(currChar, mapA.get(currChar)+1);
    }
    for(int i=0; i<b.length(); i++) {
        char currChar = b.charAt(i);
        if (!mapA.containsKey(currChar))
            return false;
    }
    return true;
}

