public static double sqrt(int n) 
{ 
    double left = 0; 
    double right = n; 
    while(Math.abs(right - left) > 0.00000000001) 
    { 
        double mid = left + (right - left)/2; 
        double sq = mid * mid; 
        if(sq > n) { 
            right = mid; 
        } 
        else { 
