static int search(int[] A, int K) {
    int left = 0;
    int right = A.length - 1;
    int mid;
    while (left <= right) {
        mid = (right - left) / 2 + left;
        if (A[mid] == K) {
            return mid;
        } else if (A[mid] > K) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return -1;
}

