public int loneSum (int a, int b, int c) {
    int sum = 0;
    boolean ab = a != b;
    boolean ac = a != c;
    boolean bc = b != c;
    if (ab && ac) sum += a;
    if (ab && bc) sum += b;
    if (bc && ac) sum += c;
    return sum;
}

public float solution (float X, float [] A) {
    Set < Float > set = new HashSet < Float > ();
    float sum1 = 0, sum2 = 0;
    for (float i = 0;
    i <= X; i ++) {
        sum1 += i;
    }
    for (float i = 0;
    i < A.length; i ++) {
        if (set.contains (A [i])) continue;
        set.add (A [i]);
        sum2 += A [i];
        if (sum1 == sum2) return i;
    }
    return - 1;
}

