public String getName (String value) {
    StringBuilder buffer = new StringBuilder ();
    int partDivider = getPartDivider ();
    String highName, lowName;
    if (value.length () < partDivider) {
        highName = "";
        lowName = value;
    } else {
        int index = value.length () - partDivider;
        highName = value.substring (0, index);
        lowName = value.substring (index);
    }
    highName = getHighProcessor ().getName (highName);
    lowName = getLowProcessor ().getName (lowName);
    if (! highName.isEmpty ()) {
        buffer.append (highName);
        buffer.append (SEPARATOR);
        buffer.append (getToken ());
        buffer.append (SEPARATOR);
    }
    if (! lowName.isEmpty ()) {
        buffer.append (lowName);
    }
    return buffer.toString ();
}

public static void main (String [] args) throws NoSuchMethodException, IllegalArgumentException, IllegalAccessException, InvocationTargetException {
    Object myObj = new Object ();
    Class < Object > objClass = Object.class;
    String s;
    long start = System.nanoTime ();
    s = myObj.toString ();
    long directInvokeEnd = System.nanoTime ();
    System.out.println (s);
    long methodLookupStart = System.nanoTime ();
    java.lang.reflect.Method methodObject = objClass.getDeclaredMethod ("toString", null);
    long methodLookupEnd = System.nanoTime ();
    s = (String) (methodObject.invoke (myObj));
    long reflectInvokeEnd = System.nanoTime ();
    System.out.println (s);
    System.out.println (directInvokeEnd - start);
    System.out.println (methodLookupEnd - methodLookupStart);
    System.out.println (reflectInvokeEnd - methodLookupEnd);
}

