public String startOz(String s) {
    int len = s.length();
    if (len < 1) {
        return "";
    }
    if (len > 1 && s.charAt(0) == 'o' && s.charAt(1) == 'z') {
        return "oz";
    }
    String r = "";
    if (s.charAt(0) == 'o') {
        r = r.concat("o");
    }
