public static String toJavaMethodName (final String nonJavaMethodName) {
    final StringBuilder nameBuilder = new StringBuilder ();
    boolean capitalizeNextChar = false;
    boolean first = true;
    for (int i = 0;
    i < nonJavaMethodName.length (); i ++) {
        final char c = nonJavaMethodName.charAt (i);
        if (! Character.isLetterOrDigit (c)) {
            if (! first) {
                capitalizeNextChar = true;
            }
        } else {
            nameBuilder.append (capitalizeNextChar ? Character.toUpperCase (c) : Character.toLowerCase (c));
            capitalizeNextChar = false;
            first = false;
        }
    }
    return nameBuilder.toString ();
}

int countCombinations (int total, int coins [], int startIndex) {
    if (total == 0) return 1;
    else if (total < 0 || coins.length == startIndex) return 0;
    else {
        int withFirstCoin = countCombinations (total - coins [startIndex], coins, startIndex);
        int withoutFirstCoin = countCombinations (total, coins, startIndex + 1);
        return withFirstCoin + withoutFirstCoin;
    }
}

