public Key secondMaxKey() {
    int size = size();
    if (size < 2) {
        return null;
    }
    Key max = first.key;
    Key second = first.next.key;
    if (max.compareTo(second) < 0) {
        Key temp = max;
        max = second;
        second = temp;
    }
    Node current = first.next;
    while (current != null) {
        Key currKey = current.key;
        if (currKey.compareTo(max) > 0) {
            second = max;
            max = currKey;
        } else if (currKey.compareTo(second) > 0 && currKey.compareTo(max) != 0) {
            second = currKey;
        }
        current = current.next;
    }
    return second;
}

