public int solution(int X, int[] A) {
    int len = A.length;
    if (X > len) {
        return -1;
    }
    int[] isFilled = new int[X];
    int jumped = 0;
    Arrays.fill(isFilled, 0);
    for (int i = 0; i < len; i++) {
        int x = A[i];
        int idx = x - 1;
        if (x <= X && isFilled[idx] == 0) {
            isFilled[idx] = 1;
            jumped += 1;
            if (jumped == X) {
                return i;
            }
        }
    }
    return -1;
}

