    if (0 == diff) {
        Double n1 = Double.parseDouble (s1NameNumPair [1]);
        Double n2 = Double.parseDouble (s2NameNumPair [1]);
        return n1.compareTo (n2);
    }
    return diff;
}

public static String changeToEnglish (String phrase) {
    if (phrase == null) {
        return null;
    }
    String transform = phrase.replace ('4', 'a').replace ('1', 'l').replace ('2', 'z').replace ('5', 's').replace ('8', 'b').replace('0', 'o').replace('7', 't').replace("|_|", "u").replace("3", "e");
    transform = transform.replace(" e ", " 3 ");
    if (transform.startsWith("e ")) {
        transform = "3 " + transform.substring(2);
    }
    if (transform.endsWith(" e")) {
        transform = transform.substring(0, transform.length() - 2) + " 3";
    }
    return transform;
}

