public static boolean isBalanced (String str) {
    boolean result = false;
    // Return false if the length of the string is less than 2
    if (str.length () < 2) 
    return false;
    // We initialize a Stack of characters
    Stack < Character > stack = new Stack < > ();
    // We traverse through the string
    for (int i = 0; i < str.length (); i ++) {
        char ch = str.charAt (i);
        // If the character does not have a left/right mapping then ignore it
        if (! parenthesesMapRight.containsKey (ch) && ! parenthesesMapLeft.containsKey (ch)) {
            continue;
        }
        // If there is a left mapping, push it to the stack
        if (parenthesesMapLeft.containsKey (ch)) {
            stack.push (ch);
        } else {
            // If there is a right mapping check the top element of the stack
            if (! stack.isEmpty () && stack.pop () == parenthesesMapRight.get (ch).charValue ()) {
                result = true;
            } else {
                return false;
            }
        }
    }
    // The stack should be empty otherwise the brackets were not balanced
    if (! stack.isEmpty ())
    return result = false;
    return result;
}

public static String getDurationBreakdown (long millis) {
    String [] units = {" Days ", " Hours ", " Minutes ", " Seconds "};
    Long [] values = new Long [units.length];
    if (millis < 0) {
        throw new IllegalArgumentException ("Duration must be greater than zero!");
    }
    values [0] = TimeUnit.MILLISECONDS.toDays (millis);
    millis -= TimeUnit.DAYS.toMillis (values [0]);
    values [1] = TimeUnit.MILLISECONDS.toHours (millis);
    millis -= TimeUnit.HOURS.toMillis (values [1]);
    values [2] = TimeUnit.MILLISECONDS.toMinutes (millis);
    millis -= TimeUnit.MINUTES.toMillis (values [2]);
    values [3] = TimeUnit.MILLISECONDS.toSeconds (millis);
    StringBuilder sb = new StringBuilder (64);
    boolean startPrinting = false;
    for (int i = 0;
    i < units.length; i ++) {
        if (! startPrinting && values [i] != 0) startPrinting = true;
        if (startPrinting) {
            sb.append (values [i]);
            sb.append (units [i]);
        }
    }
    return (sb.toString ());
}

