int[] zeroFront(int[] nums) {
    if (nums == null) {
        return null;
    }
    int[] result = new int[nums.length];
    int zeroesPos = 0;
    int othersPos = result.length - 1;
    for (int i = nums.length - 1; i >= 0; -- i) {
        if (nums[i] == 0) {
            result[zeroesPos] = 0;
            ++ zeroesPos;
        } else {
            result[othersPos] = nums[i];
            -- othersPos;
        }
    }
    return result;
}

