public static Boolean isAnagram (String word, String anagram_word) {
    if (word.length() != anagram_word.length()) {
        return false;
    }
    int[] word_count = new int[26];
    int[] anagram_count = new int[26];
    for (char c : word.toLowerCase().toCharArray()) {
        int index = c - 'a';
        word_count[index]++;
    }
    for (char c : anagram_word.toLowerCase().toCharArray()) {
        int index = c - 'a';
        anagram_count[index]++;
    }
    for (int i = 0 ; i < 26 ; i++) {
        if (word_count[i] != anagram_count[i]) {
            return false;
        }
    }
    return true;
}

public static String compress (String text) {
    String result = "";
    int index = 0;
    while (index < text.length ()) {
        char c = text.charAt (index);
        int count = count (text, index);
        if (count == 1) result += "" + c;
        else result += "" + count + c;
        index += count;
    }
    return result;
}

private static boolean isAnagram(String s1, String s2) {
    if (s1.length() != s2.length())
        return false;
    int checkSum = 0;
    for (char c : s1.toLowerCase().toCharArray())
        checkSum ^= c;
    for (char c : s2.toLowerCase().toCharArray())
        checkSum ^= c;
    return checkSum == 0;
}

