private static boolean isPermutation(String a, String b) {
    char[] aArray = a.toCharArray();
    char[] bArray = b.toCharArray();
    if (a.length() != b.length()) {
        return false;
    }
    int found = 0;
    for (int i = 0;
        i < aArray.length; i++) {
        char eachA = aArray[i];
        for (int k = 0;
            k < bArray.length; k++) {
            if (eachA == bArray[k]) {
                found++;
                aArray[k] = '\uFFFF'; // Changed bArray[k] to aArray[k] 
                break;
            }
        }
    }
    return found == a.length();
}

public String longestSequenceOfChar (String str) {
    int maxLength = 0;
    String longest = "";
    for(int i = 0, j; i < str.length(); i = j) {
        for(j = i; j < str.length() && str.charAt(j) == str.charAt(i); j++);
        if(j - i > maxLength) {
            maxLength = j - i;
            longest = str.substring(i, j);
        }
    }
    return longest;
}

private static Character findFirstCharacter (String s) { 
    Set<Character> seen = new HashSet<Character>();
    Character f = Character.MAX_VALUE;
    for (int i=0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (seen.contains(c)) {
            if (c < f)
                f = c;
        } else {
            seen.add(c);
        }
    }
    return f == Character.MAX_VALUE ? '_' : f;
}

public CharSequence filter (CharSequence source, int start, int end, Spanned dest, int dstart, int dend) {
    int dotLoc = -1;
    int length = dest.length();
    for (int selfIter=0; selfIter < length; selfIter++) {
        char character = dest.charAt(selfIter);
        if (character == '.' || character == ',') {
            dotLoc = selfIter;
            break;
        }
    }
    if (dotLoc >= 0) {
        if (source.equals (".") || source.equals (",")) {
            return "";
        }
        if (dend <= dotLoc) {
            return null;
        }
        if (length - dotLoc > decimalDigits) {
            return "";
        }
    }
    return null;
}

public void shuffle(int numberOfCards) {
    Random random = new Random();
    for (int i = 0; i < numberOfCards; i++) {
        int j = random.nextInt(protoDeck.length - i) + i;
        Card temp = deck[i];
        int pos = j;
        while (pos > i + 1) {
            deck[pos] = deck[pos - 1];
            pos--;
        }
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

