public static boolean hasLoop(Node root) {
    if (root == null) return false;
    Node active = root;
    Node inactive = root.next;
    while (inactive != null && inactive.next != null) {
        if (active == inactive || active == inactive.next) {
            return true;
        } else {
            active = active.next;
            inactive = inactive.next.next;
        }
    } 
    return false;
}

public Object [] tokenizer (String value, String [] delimeters) {
    List < String > list = new ArrayList < String > ();
    for (String s : delimeters) {
        if (value.contains (s)) {
            String [] strArr = value.split ("\\" + s);
            for (String str : strArr) {
                list.add (str);
                if (! list.contains (s)) {
                    list.add (s);
                }
            }
        }
    }
    Object [] newValues = list.toArray ();
    return newValues;
}

