private void transform(HSSFSheet sheetOld, XSSFSheet sheetNew) {
    XSSFRow rowNew;
    int last = this.lastColumn;
    for (Row row : sheetOld) {
        rowNew = sheetNew.createRow(row.getRowNum());
        this.transform((HSSFRow) row, rowNew);
    }
    for (int i = 0; i < last; i++) {
        int width = sheetOld.getColumnWidth(i);
        boolean isHidden = sheetOld.isColumnHidden(i);
        sheetNew.setColumnWidth(i, width);
        sheetNew.setColumnHidden(i, isHidden);
    }
    int numRegions = sheetOld.getNumMergedRegions();
    for (int i = 0; i < numRegions; i++) {
        sheetNew.addMergedRegion(sheetOld.getMergedRegion(i));
    }
}

public void shuffle(int numberOfCards) {
    int j;
    Random randGen = new Random();
    for (int i = 0; i < numberOfCards; i++) {
      j = randGen.nextInt(protoDeck.length - i) + i;
      Card temp = deck[i];
      int shiftPos = j;
      while (shiftPos > i) {
        deck[shiftPos] = deck[shiftPos - 1];
        shiftPos--;
      }
      deck[i] = deck[j];
      deck[j] = temp;
    }
}

public String getLongestSubstring(String s) {
    if (s == null || s.equals("")) return null;
    String longest = "" + s.charAt(0), current = longest;
    for (int i = 1; i < s.length(); ++i) {
        current = (s.charAt(i) != s.charAt(i - 1)) ? "" + s.charAt(i) : current + s.charAt(i);
        if (current.length() > longest.length()) longest = current;
    }
    return longest;
}

public int maxBlock (String str) {
    int max = 0;
    int count = 1;
    char o = ' ';
    for (int i = 0;
    i < str.length (); i ++) {
        char c = str.charAt (i);
        if (c == o) {
            count ++;
            if (count > max) {
                max = count;
            }
        } else {
            count = 1;
            if (count > max) {
                max = count;
            }
        }
        o = c;
    }
    return max;
}

public CharSequence filter (CharSequence source, int start, int end, Spanned dest, int dstart, int dend) {
    CharSequence out = super.filter (source, start, end, dest, dstart, dend);
    if (out != null) {
        source = out;
        start = 0;
        end = out.length ();
    }
    int len = end - start;
    if (len == 0) {
        return source;
    }
    int dlen = dest.length ();
    for (int i = 0;
    i < dstart; i ++) {
        if (dest.charAt (i) == '.') {
            return (dlen - (i + 1) + len > digits) ? "" : new SpannableStringBuilder (source, start, end);
        }
    }
    for (int i = start;
    i < end; ++ i) {
        if (source.charAt (i) == '.') {
            if ((dlen - dend) + (end - (i + 1)) > digits) return "";
            else break;
        }
    }
    return new SpannableStringBuilder (source, start, end);
}

public boolean check(double x1, double y1, double x2, double y2, double x, double y) {
    if(x1 == x2) {
	    return y1 < y2 ? (y1 <= y && y <= y2) : (y2 <= y && y <= y1);
	}
	double m = (y2 - y1) / (x2 - x1);
	double r1 = x1 + m * y1;
	double r2 = x2 + m * y2;
	double r = x + m * y;
	if(r1 < r2)
	    return (r >= r1 && r <= r2);
	return (r2 <= r && r <= r1);
}

