static String transpose(String s, int rows, int columns) {
    int n = s.length();
    if (rows * columns != n) {
        throw new IllegalArgumentException();
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n - 1; i++) {
        int index = i * columns % (n - 1);
        sb.append(s.charAt(index));
    }
    sb.append(s.charAt(n - 1));
    return sb.toString();
}

