    int gap = 0;
    int maxGapLength = 0;
    for (int i = 0; i < binary.length (); i++) {
        if (binary.charAt (i) == '1') {
            if (gap > maxGapLength) {
                maxGapLength = gap;
            }
            gap = 0;
