def softmax(z):
	assert len(z.shape) == 2
	e_x = np.exp(z - np.max(z, axis = 1, keepdims = True))
	div = np.sum(e_x, axis = 1, keep_dims = True)
	return np.divide(e_x, np.where(np.equal(div, 0), 1, div))

