def roundrobin(* iterables) :
	"roundrobin('ABC', 'D', 'EF') --> A D E B F C"
	pending = len(iterables)
	nexts = cycle(iter(it).__next__() for it in iterables)
	while pending>0 :
		try :
			for item in nexts :
				yield item()
		except StopIteration :
			pending -= 1
			nexts = cycle(itertools.islice(nexts, pending))

