def hashCode(self): 
    hashCode = 1
    for obj in self:
        if obj == None:
            obj_hashCode = 0
        else:
            obj_hashCode = obj.hashCode()
        hashCode = 31 * hashCode + obj_hashCode
    return hashCode

def merge(dict1, dict2) :
	keys1 = set(dict1.keys())
	keys2 = set(dict2.keys())
	for k in keys1 - keys2 :
		yield (k, dict1[k])
	for k in keys2 - keys1 :
		yield (k, dict2[k])
	for k in keys1 & keys2 :
		yield (k, dict(merge(dict1[k], dict2[k])))

