def decorator(f):
	arg_names = inspect.getargspec(f)[0]
	def decorated_f(*args, **kwargs):
		if len(args) == len(arg_names):
			kwargs = dict(zip(arg_names, args))
		return f(**kwargs)
	return decorated_f

