def ping(host, n = 0):
    from multiping import MultiPing
    RTT = 0
    pinger = MultiPing([host])
    if n > 0:
        for _ in range(n):
            RTT += ping(host)
        RTT /= n
    else:
        pinger.send()
        responses, _ = pinger.receive(1)
        for _, rtt in responses.items():
            RTT = rtt
    return RTT

