    if (i == len(nums) - 1) and (current != expected):
      sb += f"{rangeStart}-{current}"
    elif (current != expected):
      if (rangeStart != previous):
        sb += f"{rangeStart}-{previous},"
      else:
        sb += f"{rangeStart},"
      rangeStart = current
    else:
      previous = current
  if (sb[-1] == ','):
    sb = sb[:-1]

  return sb.toString ()

