	@ lru_cache(maxsize = None)
	def memop(i, j) :
		if j == n :
			return 1
		if i == m :
			return 0
		incl = memop(i + 1, j + 1) if seq[i] == sub[j] else 0
		excl = memop(i + 1, j)
		return incl + excl
	return memop(0, 0)

