	"M", "N", "O", "P", "Q", "R", "S", "T", "U", "V", "W", "X", "Y", "Z"]
	final = 0
	if number.startswith("-") :
		neg = True
		number = list(number)
		del (number [0])
		temp = number
		number = ""
		for x in temp :
			number = "{}{}".format(number, x)
	else :
		neg = False
	loc = len(number) - 1
	number = str(number)
	for x in number :
		if numbers.index(x) > base :
			raise ValueError('{} is out of base{} range'.format(x, str(base)))
