def binarySearch(arr, item, l, r):
    if (r < l):
        return -1
    mid = int(l + (r - l)/2)
    if (arr[mid] == item):
        return mid
    if (arr[mid] > item):
        return binarySearch(arr, item, l, mid-1)
    return binarySearch(arr, item, mid+1, r)

