def binary_search(a, x, lo = 0, hi = len(a)) :
	pos = None
	while lo <= hi : 
		mid = (lo + hi) // 2
		if x == a[mid] : 
			pos = mid
			break
		elif x < a[mid] : 
			hi = mid - 1
		else : 
			lo = mid + 1
	if pos != None and a[pos] == x :
		return pos
	else :
		return -1

