	start = 0
	midpoint = len(sequence) // 2
	end = len(sequence)
	left_sequence = merge_sort(sequence[start : midpoint])
	right_sequence = merge_sort(sequence[midpoint : end])
	return merge(left_sequence, right_sequence)

