def flatten(iterable):
    iterable = iter(iterable)
    stack = []
    while iterable:
        try:
            item = next(iterable)
        except StopIteration:
            try:
                iterable = stack.pop()
            except IndexError:
                break
        else:
            if isinstance(item, str):
                yield item
            else:
                try:
                    stack.append(iterable)
                    iterable = iter(item)
                except TypeError:
                    yield item

