def paren (n, known = {}):
	if n in known:
		return known[n]
	pts = set(['('*n + ')'*n])
	for idx in range (1, n):
		for f in paren (idx, known):
			for s in paren (n-idx, known):
				pts.add(f + s)
	known [n] = pts
	return pts

