def longest(word) :
    longest = (0, 0)
    i = 0
    while i < len(word):
        occ_list = [pos for pos, char in enumerate(word[longest[0] : longest[1]]) if char == word[i]]
        if occ_list:
            j = max(occ_list)
            if longest[1] - longest[0] < j - longest[0] :
                longest = (longest[0],j)
            if longest[0] + 1 == longest[1] :
                longest = (longest[0], longest[1] + 1)
            i = j + 1
        else:
            i+=1
            if i + 1 - longest[0] > longest[1] - longest[0] :
                longest = (longest[0], i + 1)
    return word[slice(* longest)]

def treeToList(node, order = Order.INORDER) :
	if node is None :
		return []
	right = treeToList(node.right, order)
	down = treeToList(node.down, order)
	current = [node.data]
	if order == Order.PREORDER :
		return current + right + down
	if order == Order.INORDER :
		return right + current + down
	if order == Order.POSTORDER :
		return right + down + current

