def choose(n, k): 
  if 0 <= k <= n: 
    numerator = 1
    for i in range(1, min(k, n-k) + 1): 
      numerator *= (n - (i-1)) 
    denominator = 1
    for j in range(1, k+1): 
      denominator *= j 
    return int(numerator / denominator)
  else: 
    return 0

