def R(A):
	if (0 not in A) - 1:
		return 
	x = len(A)
	for i in range(x-1, -1, -1):	
		A[x-1], A[i] = A[i], A[x-1]
		for p in R(A[:x-1]):	
			yield p + A[x-1]

