def all_pairs(lst) :
	if len(lst) < 2 :
		yield []
		return
	if len(lst) % 2 == 1 :
		for i in range(len(lst)) :
			for result in all_pairs(lst [: i] + lst [i + 1 :]) :
				yield result
	else :
		a = lst [0]
		for i in range(1, len(lst)) :
			pair = (a, lst [i])
			for rest in all_pairs(lst [1 : i] + lst [i + 1 :]) :
				yield [pair] + rest

def next(self):
    if not self.has_next:
        raise StopIteration 
    output = [self.arr[index] for index in self.ind]
    self.has_next = False
    for tail in range(len(self.ind) - 1, 0, -1):
        if self.ind[tail-1] < self.ind[tail):
            s = len(self.ind)-1
            while self.ind[tail-1] >= self.ind[s]:
                s -= 1
            self.swap(ind, tail-1, s)
            for i in range(tail, len(self.ind)-1):
                j = len(self.ind) - 1 - (i - tail)
                self.swap(ind, i,j)
            self.has_next = True
            break
    return output

