def curry(func):
  def call_with(*args):
    if len(args) == 1:
      arg1 = args[0]
      def call_with_2(arg2):
        return func(arg1, arg2)
      return call_with_2
    else:
      return func(args[0], args[1])
  return call_with

def chunks(iterable, n) :
