def flat_sum(lst):
	if len(lst) == 0 :
		return 0
	hd, tl = lst[0], lst[1:]
	if type(hd) is list:
		return flat_sum(hd) + flat_sum(tl)
	elif type(hd) is int or type(hd) is float:
		return hd + flat_sum(tl)
	else:
		return flat_sum(tl)

