def get_size(start_path = '.') :
    seen_subtrees = []
    total_size = 0
    def walk_subtrees(path):
        if path in seen_subtrees:
            return
        seen_subtrees.append(path)
        for root, _, files in os.walk(path):
            for file in files:
                try:
                    total_size += os.stat(os.path.join(root, file)).st_size
                except OSError:
                    continue
    walk_subtrees(start_path)
    return total_size

