def deleteDir(dirPath): 
	deleteFiles = []
	deleteDirs = []
	for root, dirs, files in os.walk(dirPath): 
		while len(dirs): 
			dir = dirs.pop() 
			deleteDirs.append(os.path.join(root, dir))
		while len(files): 
			file = files.pop() 
			deleteFiles.append(os.path.join(root, file))
