	elif hasattr(obj, "__iter__") and not isinstance(obj, str) :
		return [con_to_dict(v, classkey) for v in obj]
	elif hasattr(obj, "__dict__") :
		data = dict([(key, con_to_dict(value, classkey)) for key, value in obj.__dict__.items()
