def qsort(arr, first, last) : 
	if first >= last : 
		return 
	left, right = first, last 
	pivot = arr[random.randint(first, last)] 
	while left <= right : 
		while arr[left] < pivot : 
			left += 1 
		while arr[right] > pivot : 
			right -= 1 
		if left <= right : 
			arr[left], arr[right] = arr[right], arr[left] 
			left += 1 
			right -= 1 
	qsort(arr, first, right) 
	qsort(arr, left, last)

