        partition[part.mountpoint] = (part.fstype, part.device)
    if path in partition:
        return partition[path]
    splitpath = path.split(os.sep)
    for section in splitpath:
        if section != '':
            path = os.sep.join(splitpath[:-1])
            if path in partition:
                return partition[path]
    return ("unkown", "none")

