def getPrimes(n):
    if n > 2: yield 2
    i = 3
    while i < n:
        sqrt_i = int(math.sqrt(i)) + 1
        for a in getPrimes(sqrt_i):
            if i % a == 0 :
                break
        else:
            yield i
        i += 2

