def factors(n) :
	if not isinstance(n, int) or n < 0:
		raise ValueError('factors() arg not an int > 0')
	f, factors, incr = 2, [], 1
	while f * f <= n:
		while n % f == 0:
			factors.append(f)
			n //= f
			incr = 2
		f += incr
	if n > 1 :
		factors.append(n)
	return factors

