def window(seq, n = 2):
	"Returns a sliding window (of width n) over data from the iterable"
	"   s -> (s0,s1,...s[n-1]), (s1,s2,...,sn), ...                   "
	results = []
	it = iter(seq)
	while True:
		result = tuple(islice(it, n))
		if len(result) == n:
			results.append(result)
		if len(result) < n:
			break
	return results

