def is_valid_hostname(hostname):
    if hostname [-1] == ".":
        hostname = hostname [:-1]
    if len(hostname) > 253:
        return False
    labels = hostname.split(".")
    if labels[-1].isnumeric():
        return False
    allowed = re.compile(r"[a-z0-9-]{1,63}", re.IGNORECASE)
    valid = True
    for label in labels:
        if not allowed.match(label):
            valid = False
            break
    return valid

